'use client'

import React, { useState, useEffect } from 'react'
import Image from 'next/image'
import {
    Loader2, Wand2, Crop, Trash2, Search, ImageIcon, Save, RefreshCw
} from 'lucide-react'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import TagSelector from '@/components/tags/TagSelector'
import ImageCropper from '@/components/ImageCropper'
import { CATEGORY_LABELS } from '@/lib/constants'
import { GlobalItem } from '@/app/admin/data-browser/types'
import { parseCachedTags } from '@/app/admin/data-browser/utils'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'

interface EditItemDialogProps {
    open: boolean
    onOpenChange: (open: boolean) => void
    item: GlobalItem | null
    onSave: (items: Partial<GlobalItem>) => Promise<void>
    onDelete: (id: string) => void
    loading: boolean
}

export function EditItemDialog({
    open,
    onOpenChange,
    item,
    onSave,
    onDelete,
    loading
}: EditItemDialogProps) {
    // Local form state
    const [title, setTitle] = useState('')
    const [description, setDescription] = useState('')
    const [image, setImage] = useState('')
    const [categoryType, setCategoryType] = useState<string | null>(null)
    const [tags, setTags] = useState<string[]>([])
    const [metadata, setMetadata] = useState('')

    // Helpers
    const [isGeneratingDescription, setIsGeneratingDescription] = useState(false)
    const [isGeneratingTags, setIsGeneratingTags] = useState(false)
    const [mediaResults, setMediaResults] = useState<any[]>([])
    const [imageToCrop, setImageToCrop] = useState<string | null>(null)
    const [imageUploadMode, setImageUploadMode] = useState<'url' | 'upload'>('url')

    const supabase = createClient()

    // Initialize from item
    useEffect(() => {
        if (item && open) {
            setTitle(item.title)
            setDescription(item.description || '')
            setImage(item.image_url || '')
            setCategoryType(item.category_type)
            setTags(parseCachedTags(item.cached_tags).map(t => t.id))
            setMetadata(item.metadata ? JSON.stringify(item.metadata) : '')
        }
    }, [item, open])

    // Reset loop
    useEffect(() => {
        if (!open) {
            setMediaResults([])
            setImageToCrop(null)
        }
    }, [open])

    const handleSave = async () => {
        if (!item) return

        // Resolve tags to objects for cache
        let resolvedTags: { id: string; name: string }[] = []
        if (tags.length > 0) {
            const { data } = await supabase.from('tags').select('id, name').in('id', tags)
            resolvedTags = data || []
        }

        await onSave({
            id: item.id,
            title,
            description,
            image_url: image,
            category_type: categoryType || '',
            metadata: metadata ? JSON.parse(metadata) : item.metadata,
            cached_tags: resolvedTags
        })
    }

    const doSearch = async () => {
        if (!title) return
        try {
            const { data } = await fetch(`/api/search/metadata?q=${encodeURIComponent(title)}&type=${categoryType || ''}`).then(r => r.json())
            setMediaResults(data || [])
        } catch (e) {
            toast.error('Search failed')
        }
    }

    const handleMetadataMatch = (result: any) => {
        setTitle(result.title)
        setDescription(result.description || description)
        if (result.imageUrl) setImage(result.imageUrl)
        if (result.releaseDate) {
            // Try to extract year and put into metadata or release_year if exposed
        }
        setMediaResults([])
        toast.success(`Autofilled from ${result.source}`)
    }

    const handleAutoFill = async () => {
        if (!title) return
        setIsGeneratingDescription(true)
        try {
            const response = await fetch('/api/ai/regenerate-description', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ itemId: item?.id, title, type: categoryType, preview: true })
            })
            const data = await response.json()
            if (data.description) setDescription(data.description)
        } catch (e) {
            toast.error('Failed to generate description')
        } finally {
            setIsGeneratingDescription(false)
        }
    }

    const handleAutoTag = async () => {
        if (!title) return
        setIsGeneratingTags(true)
        try {
            const { generateTagsAction } = await import('@/lib/actions/ai')
            const data = await generateTagsAction({
                title: title,
                type: categoryType || '',
                description: description || ''
            })

            if (data.tags && data.tags.length > 0) {
                const { createTagsBatch } = await import('@/lib/actions/tags')
                const validTags = await createTagsBatch(data.tags)
                setTags(prev => Array.from(new Set([...prev, ...validTags.map(t => t.id)])))
                toast.success(`Generated ${validTags.length} tags`)
            }
        } catch (e) {
            toast.error('Failed to generate tags')
        } finally {
            setIsGeneratingTags(false)
        }
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="bg-zinc-950 border-zinc-800 sm:max-w-[900px] max-h-[90vh] overflow-y-auto">
                <DialogHeader className="pb-2">
                    <DialogTitle className="font-serif text-xl">Edit Item</DialogTitle>
                </DialogHeader>

                <div className="grid gap-6 py-4">
                    {/* Title Row */}
                    <div className="grid gap-2">
                        <div className="flex justify-between items-center">
                            <label className="text-sm font-medium text-zinc-300 uppercase tracking-wider">Name</label>
                        </div>
                        <div className="flex gap-2">
                            <Input
                                value={title}
                                onChange={(e) => setTitle(e.target.value)}
                                className="bg-zinc-900/50 border-zinc-800 font-medium"
                                placeholder="Item Title"
                            />
                            <Button
                                variant="secondary"
                                onClick={doSearch}
                                disabled={!title}
                                className="shrink-0 bg-zinc-800 hover:bg-zinc-700 text-zinc-300"
                            >
                                <Search className="w-4 h-4 mr-2" />
                                Search
                            </Button>
                        </div>

                        {/* Search Results */}
                        {mediaResults.length > 0 && (
                            <div className="mt-2 grid grid-cols-1 gap-1 bg-zinc-900 border border-zinc-800 rounded-md p-2 max-h-[200px] overflow-y-auto">
                                <div className="flex justify-between items-center px-1 pb-2">
                                    <span className="text-xs text-zinc-500">Select to auto-fill:</span>
                                    <Button variant="ghost" size="sm" className="h-5 text-[10px]" onClick={() => setMediaResults([])}>Clear</Button>
                                </div>
                                {mediaResults.map((result, i) => (
                                    <button
                                        key={i}
                                        onClick={() => handleMetadataMatch(result)}
                                        className="flex items-start gap-3 p-2 hover:bg-zinc-800 rounded text-left transition-colors group"
                                    >
                                        <div className="w-8 h-12 bg-zinc-800 rounded overflow-hidden shrink-0 relative">
                                            {result.imageUrl ? <Image src={result.imageUrl} alt="" fill className="object-cover" /> : null}
                                        </div>
                                        <div>
                                            <div className="text-sm font-medium text-zinc-300 group-hover:text-cyan-400">{result.title}</div>
                                            <div className="text-xs text-zinc-500 line-clamp-1">{result.description}</div>
                                        </div>
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Category */}
                    <div className="grid gap-2">
                        <label className="text-sm font-medium text-zinc-300 uppercase tracking-wider">Category</label>
                        <Select value={categoryType || 'null'} onValueChange={(val) => setCategoryType(val === 'null' ? null : val)}>
                            <SelectTrigger className="bg-zinc-900/50 border-zinc-800">
                                <SelectValue placeholder="Select a category" />
                            </SelectTrigger>
                            <SelectContent className="bg-zinc-900 border-zinc-800 text-zinc-300">
                                <SelectItem value="null">Uncategorized</SelectItem>
                                {Object.entries(CATEGORY_LABELS).map(([key, label]) => (
                                    <SelectItem key={key} value={key}>{label}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    {/* Description */}
                    <div className="grid gap-2">
                        <div className="flex justify-between items-center">
                            <label className="text-sm font-medium text-zinc-300 uppercase tracking-wider">Description</label>
                            <Button
                                variant="ghost"
                                size="sm"
                                className="h-6 text-xs text-cyan-500 hover:text-cyan-400 hover:bg-cyan-950/30"
                                onClick={handleAutoFill}
                                disabled={isGeneratingDescription || !title}
                            >
                                {isGeneratingDescription ? <Loader2 className="w-3 h-3 animate-spin mr-1" /> : <Wand2 className="w-3 h-3 mr-1" />}
                                Auto-Fill
                            </Button>
                        </div>
                        <Textarea
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            rows={6}
                            className={`bg-zinc-900/50 border-zinc-800 text-sm leading-relaxed text-zinc-300 resize-none ${isGeneratingDescription ? 'animate-pulse' : ''}`}
                        />
                    </div>

                    {/* Bottom Row: Image & Tags */}
                    <div className="grid grid-cols-1 md:grid-cols-[160px_1fr] gap-6">
                        {/* Image Column */}
                        <div className="space-y-3">
                            <label className="text-sm font-medium text-zinc-300 uppercase tracking-wider block">Image</label>
                            <div className="aspect-[2/3] bg-zinc-900 rounded-lg overflow-hidden border border-zinc-800 relative group">
                                {image ? (
                                    <>
                                        <Image src={image} alt="Preview" fill className="object-cover" />
                                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-2 p-2">
                                            <Button size="sm" variant="secondary" className="w-full h-7 text-xs" onClick={() => setImageToCrop(image)}>
                                                <Crop className="w-3 h-3 mr-1" /> Crop
                                            </Button>
                                            <Button size="sm" variant="destructive" className="w-full h-7 text-xs" onClick={() => setImage('')}>
                                                <Trash2 className="w-3 h-3 mr-1" /> Remove
                                            </Button>
                                        </div>
                                    </>
                                ) : (
                                    <div className="w-full h-full flex flex-col items-center justify-center text-zinc-600 gap-2 p-4 text-center">
                                        <ImageIcon className="w-6 h-6" />
                                        <span className="text-[10px]">No Image</span>
                                    </div>
                                )}
                            </div>

                            {!image && (
                                <div className="grid grid-cols-2 gap-2">
                                    <Button variant={imageUploadMode === 'url' ? 'secondary' : 'outline'} size="sm" onClick={() => setImageUploadMode('url')} className="text-xs h-7">URL</Button>
                                    <Button variant={imageUploadMode === 'upload' ? 'secondary' : 'outline'} size="sm" onClick={() => setImageUploadMode('upload')} className="text-xs h-7">Up</Button>
                                </div>
                            )}

                            {image ? null : imageUploadMode === 'url' ? (
                                <Input value={image} onChange={e => setImage(e.target.value)} className="h-8 text-xs bg-zinc-900 border-zinc-800" placeholder="https://..." />
                            ) : (
                                <Input
                                    type="file"
                                    className="h-8 text-xs bg-zinc-900 border-zinc-800 file:text-zinc-400"
                                    onChange={(e) => {
                                        const file = e.target.files?.[0]
                                        if (file) {
                                            const reader = new FileReader()
                                            reader.onload = () => setImageToCrop(reader.result as string)
                                            reader.readAsDataURL(file)
                                        }
                                    }}
                                />
                            )}
                        </div>

                        {/* Tags Column */}
                        <div className="space-y-3">
                            <div className="flex justify-between items-center">
                                <label className="text-sm font-medium text-zinc-300 uppercase tracking-wider">Tags</label>
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    className="h-6 text-xs text-purple-400 hover:text-purple-300 hover:bg-purple-950/30"
                                    onClick={handleAutoTag}
                                    disabled={isGeneratingTags || !title}
                                >
                                    {isGeneratingTags ? <Loader2 className="w-3 h-3 animate-spin mr-1" /> : <Wand2 className="w-3 h-3 mr-1" />}
                                    Auto-Tag
                                </Button>
                            </div>
                            <div className="min-h-[200px] bg-zinc-900/30 border border-zinc-800 rounded-lg p-2">
                                <TagSelector
                                    selectedTags={tags}
                                    onTagsChange={setTags}
                                    isLoading={isGeneratingTags}
                                />
                            </div>
                        </div>
                    </div>
                </div>

                <DialogFooter className="border-t border-zinc-800/50 pt-4 flex justify-between sm:justify-between items-center">
                    <Button
                        variant="destructive"
                        onClick={() => {
                            if (item) onDelete(item.id)
                        }}
                        className="bg-red-950/50 text-white hover:bg-red-900/50 border border-red-900/50"
                    >
                        <Trash2 className="w-4 h-4 mr-2" />
                        Delete Item
                    </Button>
                    <div className="flex gap-2">
                        <Button variant="ghost" onClick={() => onOpenChange(false)}>Cancel</Button>
                        <Button onClick={handleSave} disabled={loading} className="bg-cyan-600 hover:bg-cyan-700 text-white">
                            {loading ? <RefreshCw className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                            Save Changes
                        </Button>
                    </div>
                </DialogFooter>
            </DialogContent>

            {/* Image Cropper Modal Layered */}
            {imageToCrop && (
                <ImageCropper
                    imageSrc={imageToCrop}
                    aspectRatio={2 / 3}
                    onCropComplete={async (croppedImage) => {
                        const response = await fetch(croppedImage)
                        const blob = await response.blob()
                        const fileFormData = new FormData()
                        fileFormData.append('file', blob, 'cropped.jpg')
                        const { uploadImage: uploadAction } = await import('@/lib/actions/upload')
                        const url = await uploadAction(fileFormData)
                        if (url) setImage(url)
                        setImageToCrop(null)
                    }}
                    onCancel={() => setImageToCrop(null)}
                />
            )}
        </Dialog>
    )
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import { normalizeCategory } from '@/lib/constants'
import type { GlobalItem, Stats } from '../types'
import type { useDataBrowserState } from './useDataBrowserState'

// Helper to infer the return type of the state hook
type BrowserState = ReturnType<typeof useDataBrowserState>

export function useDataFetching(state: BrowserState) {
    const { filters, ui, sort } = state
    const [items, setItems] = useState<GlobalItem[]>([])
    const [loading, setLoading] = useState(true)
    const [stats, setStats] = useState<Stats>({ total: 0, byCategory: {} })
    const supabase = createClient()

    const fetchStats = useCallback(async () => {
        // Fetch raw count (often fails or returns 0 if RLS is strict on count(*))
        const { count } = await supabase
            .from('global_items')
            .select('*', { count: 'exact', head: true })

        // Fetch category breakdown (Security Definer RPC - reliable)
        const { data: catStats } = await (supabase.rpc('get_category_stats') as any)

        // Group by normalized category to merge variations
        const byCategory: Record<string, number> = {}
        let sumFromCategories = 0

        if (catStats) {
            catStats.forEach((item: any) => {
                const key = normalizeCategory(item.category)
                byCategory[key] = (byCategory[key] || 0) + item.count
                sumFromCategories += item.count
            })
        }

        // Fallback: If count is 0 but we have category stats, use the sum
        const effectiveTotal = (count && count > 0) ? count : sumFromCategories

        setStats({ total: effectiveTotal || 0, byCategory })
    }, [supabase])

    const fetchItems = useCallback(async () => {
        setLoading(true)

        // Special case: Short Description filter uses dedicated RPC
        if (filters.shortDesc && !filters.missingImage && !filters.uncategorized) {
            try {
                // Get IDs of items with short descriptions
                const { data: shortIds, error: rpcError } = await ((supabase as any).rpc('get_short_description_items', {
                    p_category_types: filters.selectedCategories.length > 0 ? filters.selectedCategories : null,
                    p_limit: ui.pageSize,
                    p_offset: (ui.page - 1) * ui.pageSize
                }) as any)

                if (rpcError) {
                    console.error('Error fetching short descriptions:', rpcError)
                    setLoading(false)
                    return
                }

                if (!shortIds || shortIds.length === 0) {
                    setItems([])
                    ui.setTotalPages(0)
                    ui.setTotalCount(0)
                    setLoading(false)
                    return
                }

                // Fetch full items by IDs
                const { data, error } = await supabase
                    .from('global_items')
                    .select('*')
                    .in('id', shortIds.map((r: any) => r.id))
                    .order(sort.sortField, { ascending: sort.sortOrder === 'asc', nullsFirst: false })

                if (error) {
                    console.error('Error fetching items:', error)
                    setLoading(false)
                    return
                }

                setItems(data || [])
                ui.setTotalPages(1) // RPC doesn't return total count easily
                ui.setTotalCount(shortIds.length)
                setLoading(false)
                return
            } catch (err) {
                console.error('Short description RPC error:', err)
                setLoading(false)
                return
            }
        }

        // =================================================================
        // OPTIMIZED PATH: Use browse_items RPC for basic browsing
        // =================================================================
        const hasActiveFilters = Object.keys(filters.activeFilters).length > 0
        const hasAdvancedFilters = filters.missingImage || filters.uncategorized || hasActiveFilters

        if (!hasAdvancedFilters) {
            try {
                const { data, error } = await ((supabase as any).rpc('browse_items', {
                    p_category_types: filters.selectedCategories.length > 0 ? filters.selectedCategories : null,
                    p_search: filters.debouncedSearchQuery && filters.debouncedSearchQuery.length >= 3 ? filters.debouncedSearchQuery : null,
                    p_page: ui.page,
                    p_page_size: ui.pageSize,
                    p_sort_field: sort.sortField,
                    p_sort_order: sort.sortOrder
                }) as any)

                if (error) {
                    console.error('RPC error:', error)
                    toast.error('Failed to load items: ' + (error?.message || 'Unknown error'))
                    setItems([])
                    ui.setTotalPages(0)
                    ui.setTotalCount(0)
                    setLoading(false)
                    return
                }

                // Total count is included in each row
                const totalCount = data?.[0]?.total_count || 0
                setItems(data || [])
                ui.setTotalPages(Math.ceil(totalCount / ui.pageSize))
                ui.setTotalCount(totalCount)
                setLoading(false)
                return
            } catch (err: any) {
                console.error('RPC exception:', err)
                toast.error('Query failed: ' + (err?.message || 'Timeout'))
                setItems([])
                ui.setTotalPages(0)
                ui.setTotalCount(0)
                setLoading(false)
                return
            }
        }

        // =================================================================
        // ADVANCED FILTERS PATH: Full query with all columns
        // =================================================================
        const SELECTED_COLUMNS = 'id,external_id,source,title,description,image_url,release_year,metadata,cached_tags,category_type,last_metadata_update,created_at,external_ids,cast,director,writer,studio,genres,content_rating,runtime,vote_average,trailer_url,tagline,episodes,season,source_material,romaji_title,original_creator,platforms,developers,publishers,playtime,metacritic,min_players,max_players,min_playtime,max_playtime,min_age,mechanics,categories,complexity,designers,artists,is_expansion,bgg_id,original_language,origin_countries,original_title,status,homepage,budget,revenue,production_companies,networks,number_of_seasons,number_of_episodes,keywords,watch_providers,backdrop_path,logo_path,studios,banner_url,imdb_rating,imdb_votes,rotten_tomatoes_rating,metacritic_rating,awards_text,box_office,time_to_beat,game_engines,websites,game_modes,perspectives,videos,screenshots,franchise,dlc_count,release_date,families,rank_overall,best_players,min_age_community,language_dependence,followers,album_type,label,total_tracks,upc,audio_features,isrc,duration_ms,album_name,artist_names,preview_url,volumes,chapters,format,staff,description_length,description_parts,anilist_score,vote_count,popularity,track_number,themes'

        let query = supabase
            .from('global_items')
            .select(SELECTED_COLUMNS, { count: 'estimated' })
            .order(sort.sortField, { ascending: sort.sortOrder === 'asc', nullsFirst: false })
            .range((ui.page - 1) * ui.pageSize, ui.page * ui.pageSize - 1)

        // Text Search
        if (filters.debouncedSearchQuery && filters.debouncedSearchQuery.length >= 3) {
            const cleanQuery = filters.debouncedSearchQuery.trim()
            query = query.ilike('title', `%${cleanQuery}%`)
        }

        // URL-based filters (Exact match)
        const af = filters.activeFilters
        if (af.director) query = query.eq('director', af.director)
        if (af.studio) query = query.eq('studio', af.studio)
        if (af.content_rating) query = query.eq('content_rating', af.content_rating)
        if (af.year) query = query.eq('release_year', parseInt(af.year))
        if (af.category) query = query.eq('category_type', af.category.toUpperCase().replace(/-/g, '_'))
        if (af.language) query = query.eq('original_language', af.language)
        if (af.writer) query = query.ilike('writer', `%${af.writer}%`)

        // Array contains filters
        if (af.cast) query = query.contains('cast', [af.cast])
        if (af.genre) query = query.contains('genres', [af.genre])
        if (af.platform) query = query.contains('platforms', [af.platform])
        if (af.designer) query = query.contains('designers', [af.designer])
        if (af.mechanic) query = query.contains('mechanics', [af.mechanic])
        if (af.artist) query = query.contains('artists', [af.artist])
        if (af.tag) query = query.contains('cached_tags', [{ name: af.tag }])

        if (af.developer) {
            const dev = af.developer.replace(/"/g, '\\"').replace(/,/g, '\\,')
            query = query.or(`studio.eq."${dev}",developers.cs.{"${dev}"}`)
        }
        if (af.production) {
            const prod = af.production.replace(/"/g, '\\"').replace(/,/g, '\\,')
            query = query.or(`production_companies.cs.{"${prod}"},networks.cs.{"${prod}"},publishers.cs.{"${prod}"}`)
        }

        // Build OR conditions
        const orConditions: string[] = []

        if (filters.selectedCategories.length > 0) {
            query = query.in('category_type', filters.selectedCategories)
        }

        if (filters.missingImage) orConditions.push('image_url.is.null')
        if (filters.uncategorized) orConditions.push('category_type.is.null')

        if (orConditions.length > 0) {
            query = query.or(orConditions.join(','))
        }

        try {
            const { data, count, error } = await query

            if (error) {
                console.error('Error fetching items:', error)
                toast.error('Failed to load items')
                setItems([])
                ui.setTotalPages(0)
                ui.setTotalCount(0)
                return
            }

            setItems(data || [])
            ui.setTotalPages(Math.ceil((count || 0) / ui.pageSize))
            ui.setTotalCount(count || 0)
        } catch (err: any) {
            console.error('Exception fetching items:', err)
            toast.error('Search failed')
            setItems([])
            ui.setTotalPages(0)
            ui.setTotalCount(0)
        } finally {
            setLoading(false)
        }
    }, [supabase, ui.page, ui.pageSize, filters.debouncedSearchQuery, filters.missingImage, filters.shortDesc, filters.uncategorized, filters.selectedCategories, filters.activeFilters, sort.sortField, sort.sortOrder])

    // Effects
    useEffect(() => {
        fetchItems()
    }, [fetchItems])

    // Reset page on filter change
    useEffect(() => {
        ui.setPage(1)
    }, [filters.debouncedSearchQuery, filters.selectedCategories, filters.missingImage, filters.shortDesc, filters.uncategorized])

    // Defer stats loading
    useEffect(() => {
        const timer = setTimeout(() => fetchStats(), 100)
        return () => clearTimeout(timer)
    }, [fetchStats])

    return {
        items,
        setItems, // Exposed for manual updates (deletion)
        loading,
        setLoading,
        stats,
        fetchItems,
        fetchStats
    }
}

'use client'

import { useCallback } from 'react'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import type { GlobalItem } from '../types'
import type { useDataBrowserState } from './useDataBrowserState'

type BrowserState = ReturnType<typeof useDataBrowserState>

interface ItemActionsProps {
    state: BrowserState
    refreshItems: () => Promise<void>
    onItemsDeleted: (ids: string[]) => void
}

export function useItemActions({ state, refreshItems, onItemsDeleted }: ItemActionsProps) {
    const { selection, modals } = state
    const supabase = createClient()

    // --------------------------------------------------------
    // DELETE
    // --------------------------------------------------------
    const handleDelete = useCallback(async (id: string) => {
        try {
            const { error } = await supabase.from('global_items').delete().eq('id', id)
            if (error) throw error

            toast.success('Item deleted')
            onItemsDeleted([id])

            // If viewing details of deleted item, close it
            if (modals.viewItem?.id === id) {
                modals.setViewItem(null)
            }
        } catch (err: any) {
            console.error('Delete error:', err)
            toast.error('Failed to delete item')
        }
    }, [supabase, modals, onItemsDeleted])

    const handleBulkDelete = useCallback(async () => {
        if (selection.selectedIds.size === 0) return

        try {
            const ids = Array.from(selection.selectedIds)
            const { error } = await supabase.from('global_items').delete().in('id', ids)

            if (error) throw error

            toast.success(`Deleted ${ids.length} items`)
            onItemsDeleted(ids)
            selection.setSelectedIds(new Set())
            modals.setDeleteConfirm(null)
        } catch (err: any) {
            console.error('Bulk delete error:', err)
            toast.error('Failed to delete items')
        }
    }, [supabase, selection, modals, onItemsDeleted])

    const handleDeleteSource = useCallback(async (source: string) => {
        try {
            // Note: This matches the original logic which likely relies on strict source string matching
            const { error } = await supabase.from('global_items').delete().eq('source', source)

            if (error) throw error

            toast.success(`Deleted all items from ${source}`)
            refreshItems() // Full refresh needed for bulk source delete
            modals.setDeleteConfirm(null)
        } catch (err: any) {
            console.error('Source delete error:', err)
            toast.error('Failed to delete items from source')
        }
    }, [supabase, refreshItems, modals])

    // --------------------------------------------------------
    // ANALYZE / UPDATE
    // --------------------------------------------------------
    const handleAnalyze = useCallback(async () => {
        if (selection.selectedIds.size === 0) return

        const loadingToast = toast.loading(`Analyzing ${selection.selectedIds.size} items...`)

        try {
            const ids = Array.from(selection.selectedIds)

            // Call API endpoint
            const response = await fetch('/api/ai/enrich-metadata', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ itemIds: ids })
            })

            if (!response.ok) {
                throw new Error('Analysis failed')
            }

            const result = await response.json()
            toast.success(`Analysis complete: ${result.updated} updated`)
            selection.setSelectedIds(new Set())
            refreshItems()
        } catch (err: any) {
            console.error('Analysis error:', err)
            toast.error('Analysis failed: ' + err.message)
        } finally {
            toast.dismiss(loadingToast)
        }
    }, [selection, refreshItems])

    const handleRefreshMetadata = useCallback(async (item: GlobalItem) => {
        const loadingToast = toast.loading(`Refreshing ${item.title}...`)
        try {
            const response = await fetch('/api/ai/enrich-metadata', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    itemId: item.id,
                    title: item.title,
                    type: item.category_type,
                    force: true
                })
            })

            if (!response.ok) throw new Error('Refresh failed')

            toast.success(`Refreshed ${item.title}`)
            refreshItems()
        } catch (err: any) {
            console.error('Refresh error:', err)
            toast.error('Refresh failed')
        } finally {
            toast.dismiss(loadingToast)
        }
    }, [refreshItems])

    const handleRegenerateDescription = useCallback(async (item: GlobalItem) => {
        const loadingToast = toast.loading(`Regenerating description for ${item.title}...`)
        try {
            const response = await fetch('/api/ai/regenerate-description', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    itemId: item.id,
                    title: item.title,
                    type: item.category_type
                })
            })

            if (!response.ok) throw new Error('Regeneration failed')

            toast.success(`Regenerated description for ${item.title}`)
            refreshItems()
        } catch (err: any) {
            console.error('Regeneration error:', err)
            toast.error('Regeneration failed')
        } finally {
            toast.dismiss(loadingToast)
        }
    }, [refreshItems])

    const handleGenerateTags = useCallback(async (item: GlobalItem) => {
        const loadingToast = toast.loading(`Generating tags for ${item.title}...`)
        try {
            const response = await fetch('/api/ai/generate-tags', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    itemId: item.id,
                    title: item.title,
                    type: item.category_type
                })
            })

            if (!response.ok) throw new Error('Tag generation failed')

            toast.success(`Generated tags for ${item.title}`)
            refreshItems()
        } catch (err: any) {
            console.error('Tag error:', err)
            toast.error('Tag generation failed')
        } finally {
            toast.dismiss(loadingToast)
        }
    }, [refreshItems])

    // --------------------------------------------------------
    // ADD / EDIT
    // --------------------------------------------------------
    const handleSaveItem = useCallback(async (item: Partial<GlobalItem>) => {
        try {
            if (modals.editMode === 'edit' && item.id) {
                const { error } = await (supabase
                    .from('global_items') as any)
                    .update(item)
                    .eq('id', item.id)

                if (error) throw error
                toast.success('Item updated')
            } else {
                // Remove ID for creation to let DB generate it (if using UUID) or ensure it's provided
                const { id, ...newItem } = item
                const { error } = await (supabase
                    .from('global_items') as any)
                    .insert([newItem])

                if (error) throw error
                toast.success('Item created')
            }

            modals.setEditItem(null)
            refreshItems()
        } catch (err: any) {
            console.error('Save error:', err)
            toast.error('Failed to save item')
        }
    }, [supabase, modals, refreshItems])

    return {
        handleDelete,
        handleBulkDelete,
        handleDeleteSource,
        handleAnalyze,
        handleRefreshMetadata,
        handleRegenerateDescription,
        handleGenerateTags,
        handleSaveItem
    }
}

