export default function DataBrowserPage() {
    const searchParams = useSearchParams()
    const router = useRouter()

    const [items, setItems] = useState<GlobalItem[]>([])
    const [loading, setLoading] = useState(true)
    const [stats, setStats] = useState<Stats>({ total: 0, byCategory: {} })

    // URL-based filters (from FilterPill clicks)
    const activeFilters = useMemo(() => {
        const filters: Record<string, string> = {}
        const filterKeys = ['director', 'cast', 'studio', 'genre', 'tag', 'developer', 'platform', 'designer', 'mechanic', 'artist', 'content_rating', 'year', 'category', 'writer', 'production', 'language']
        filterKeys.forEach(key => {
            const value = searchParams.get(key)
            if (value) filters[key] = value
        })
        return filters
    }, [searchParams])

    const hasActiveFilters = Object.keys(activeFilters).length > 0

    const removeFilter = (key: string) => {
        const params = new URLSearchParams(searchParams.toString())
        params.delete(key)
        router.push(`/admin/data-browser?${params.toString()}`)
    }

    const clearAllFilters = () => {
        router.push('/admin/data-browser')
    }

    // Filters
    const [selectedCategories, setSelectedCategories] = useState<string[]>([])
    const [missingImage, setMissingImage] = useState(false)
    const [shortDesc, setShortDesc] = useState(false)
    const [uncategorized, setUncategorized] = useState(false)
    const [searchQuery, setSearchQuery] = useState('')
    const [debouncedSearchQuery, setDebouncedSearchQuery] = useState('')

    // UI State
    const [tileSize, setTileSize] = useState(50) // 0-100 scale for slider
    const [page, setPage] = useState(1)
    const [totalPages, setTotalPages] = useState(1)
    const [totalCount, setTotalCount] = useState(0)

    // Sort State (Default to created_at desc)
    const [sortField, setSortField] = useState('last_metadata_update')
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc')
    // Dynamic page size based on tile size / grid columns
    // Estimates visible rows * columns to fill viewport
    const getItemsPerPage = useCallback(() => {
        // Approximate columns at different tile sizes
        if (tileSize <= 15) return 120  // 12 cols * 10 rows
        if (tileSize <= 30) return 80   // 10 cols * 8 rows
        if (tileSize <= 50) return 56   // 8 cols * 7 rows
        if (tileSize <= 70) return 36   // 6 cols * 6 rows
        if (tileSize <= 85) return 25   // 5 cols * 5 rows
        return 16                        // 4 cols * 4 rows
    }, [tileSize])

    const pageSize = getItemsPerPage()

    // Selection
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set())

    // Modals
    // Modals
    const [editItem, setEditItem] = useState<GlobalItem | null>(null)
    const [editCategoryType, setEditCategoryType] = useState<string | null>(null)
    const [editTitle, setEditTitle] = useState('')

    const [editDescription, setEditDescription] = useState('')
    const [editImage, setEditImage] = useState('')
    const [editTags, setEditTags] = useState<string[]>([])
    const [editMetadata, setEditMetadata] = useState('')
    const [imageUploadMode, setImageUploadMode] = useState<'url' | 'upload'>('url')
    const [mediaResults, setMediaResults] = useState<any[]>([])
    const [isGeneratingDescription, setIsGeneratingDescription] = useState(false)
    const [isGeneratingTags, setIsGeneratingTags] = useState(false)
    const [imageToCrop, setImageToCrop] = useState<string | null>(null)
    const [editMode, setEditMode] = useState<'view' | 'edit'>('view')

    const [deleteConfirm, setDeleteConfirm] = useState<{ type: 'single' | 'selected' | 'source'; source?: string; id?: string } | null>(null)
    const [reportItem, setReportItem] = useState<GlobalItem | null>(null)
    const [viewItem, setViewItem] = useState<GlobalItem | null>(null)  // Item details view
    const [maintenanceOpen, setMaintenanceOpen] = useState(false)
    const [steamGridKey, setSteamGridKey] = useState('')
    const [confirmText, setConfirmText] = useState('')
    const [actionLoading, setActionLoading] = useState(false)

    // Bulk action state
    const [bulkActionProgress, setBulkActionProgress] = useState<{ current: number; total: number; action: string } | null>(null)

    // Per-item regeneration loading states
    const [regeneratingDescriptionIds, setRegeneratingDescriptionIds] = useState<Set<string>>(new Set())
    const [regeneratingTagIds, setRegeneratingTagIds] = useState<Set<string>>(new Set())
    const [refreshingMetadataIds, setRefreshingMetadataIds] = useState<Set<string>>(new Set())

    const supabase = createClient()

    // Fetch config on mount/open
    useEffect(() => {
        if (maintenanceOpen) {
            const fetchConfig = async () => {
                const { data } = await (supabase
                    .from('system_settings') as any)
                    .select('value')
                    .eq('key', 'STEAMGRIDDB_API_KEY')
                    .single()
                if (data) setSteamGridKey(data.value)
            }
            fetchConfig()
        }
    }, [maintenanceOpen, supabase])

    const handleSaveConfig = async () => {
        setActionLoading(true)
        try {
            const { error } = await supabase
                .from('system_settings')
                .upsert({
                    key: 'STEAMGRIDDB_API_KEY',
                    value: steamGridKey,
                    category: 'integrations',
                    is_secret: true
                } as any)

            if (error) throw error
            toast.success('Configuration saved')
        } catch (error) {
            console.error('Failed to save config:', error)
            toast.error('Failed to save configuration')
        } finally {
            setActionLoading(false)
        }
    }

    // ========================================================================
    // DATA FETCHING
    // ========================================================================

    const fetchStats = useCallback(async () => {
        // Fetch raw count (often fails or returns 0 if RLS is strict on count(*))
        const { count } = await supabase
            .from('global_items')
            .select('*', { count: 'exact', head: true })

        // Fetch category breakdown (Security Definer RPC - reliable)
        const { data: catStats } = await (supabase.rpc('get_category_stats') as any)

        // Group by normalized category to merge variations
        const byCategory: Record<string, number> = {}
        let sumFromCategories = 0

        if (catStats) {
            catStats.forEach((item: any) => {
                const key = normalizeCategory(item.category)
                byCategory[key] = (byCategory[key] || 0) + item.count
                sumFromCategories += item.count
            })
        }

        // Fallback: If count is 0 but we have category stats, use the sum
        const effectiveTotal = (count && count > 0) ? count : sumFromCategories

        setStats({ total: effectiveTotal || 0, byCategory })
    }, [supabase])

    const fetchItems = useCallback(async () => {
        setLoading(true)

        // Special case: Short Description filter uses dedicated RPC
        if (shortDesc && !missingImage && !uncategorized) {
            try {
                // Get IDs of items with short descriptions
                const { data: shortIds, error: rpcError } = await ((supabase as any).rpc('get_short_description_items', {
                    p_category_types: selectedCategories.length > 0 ? selectedCategories : null,
                    p_limit: pageSize,
                    p_offset: (page - 1) * pageSize
                }) as any)

                if (rpcError) {
                    console.error('Error fetching short descriptions:', rpcError)
                    setLoading(false)
                    return
                }

                if (!shortIds || shortIds.length === 0) {
                    setItems([])
                    setTotalPages(0)
                    setTotalCount(0)
                    setLoading(false)
                    return
                }

                // Fetch full items by IDs
                const { data, error } = await supabase
                    .from('global_items')
                    .select('*')
                    .in('id', shortIds.map((r: any) => r.id))
                    .order(sortField, { ascending: sortOrder === 'asc', nullsFirst: false })

                if (error) {
                    console.error('Error fetching items:', error)
                    setLoading(false)
                    return
                }

                setItems(data || [])
                setTotalPages(1) // RPC doesn't return total count easily
                setTotalCount(shortIds.length)
                setLoading(false)
                return
            } catch (err) {
                console.error('Short description RPC error:', err)
                setLoading(false)
                return
            }
        }

        // =================================================================
        // OPTIMIZED PATH: Use browse_items RPC for basic browsing
        // This is MUCH faster for category/search because it:
        // 1. Only returns columns needed for grid display
        // 2. Truncates descriptions to 200 chars
        // 3. Has a statement_timeout to prevent hanging
        // =================================================================
        const hasAdvancedFilters = missingImage || uncategorized || Object.keys(activeFilters).length > 0

        if (!hasAdvancedFilters) {
            try {
                console.log('[DEBUG] Using browse_items RPC:', {
                    p_category_types: selectedCategories.length > 0 ? selectedCategories : null,
                    p_search: debouncedSearchQuery && debouncedSearchQuery.length >= 3 ? debouncedSearchQuery : null,
                    p_page: page,
                    p_page_size: pageSize,
                    p_sort_field: sortField,
                    p_sort_order: sortOrder
                })

                const { data, error } = await ((supabase as any).rpc('browse_items', {
                    p_category_types: selectedCategories.length > 0 ? selectedCategories : null,
                    p_search: debouncedSearchQuery && debouncedSearchQuery.length >= 3 ? debouncedSearchQuery : null,
                    p_page: page,
                    p_page_size: pageSize,
                    p_sort_field: sortField,
                    p_sort_order: sortOrder
                }))

                console.log('[DEBUG] RPC returned:', { error, dataLength: data?.length, firstItem: data?.[0]?.title })

                if (error) {
                    console.error('RPC error:', error)
                    toast.error('Failed to load items: ' + (error?.message || 'Unknown error'))
                    setItems([])
                    setTotalPages(0)
                    setTotalCount(0)
                    setLoading(false)
                    return
                }

                // Total count is included in each row
                const totalCount = data?.[0]?.total_count || 0
                setItems(data || [])
                setTotalPages(Math.ceil(totalCount / pageSize))
                setTotalCount(totalCount)
                setLoading(false)
                return
            } catch (err: any) {
                console.error('RPC exception:', err)
                toast.error('Query failed: ' + (err?.message || 'Timeout'))
                setItems([])
                setTotalPages(0)
                setTotalCount(0)
                setLoading(false)
                return
            }
        }

        // =================================================================
        // ADVANCED FILTERS PATH: Full query with all columns
        // Used when quality filters or URL-based filters are active
        // =================================================================
        const SELECTED_COLUMNS = 'id,external_id,source,title,description,image_url,release_year,metadata,cached_tags,category_type,last_metadata_update,created_at,external_ids,cast,director,writer,studio,genres,content_rating,runtime,vote_average,trailer_url,tagline,episodes,season,source_material,romaji_title,original_creator,platforms,developers,publishers,playtime,metacritic,min_players,max_players,min_playtime,max_playtime,min_age,mechanics,categories,complexity,designers,artists,is_expansion,bgg_id,original_language,origin_countries,original_title,status,homepage,budget,revenue,production_companies,networks,number_of_seasons,number_of_episodes,keywords,watch_providers,backdrop_path,logo_path,studios,banner_url,imdb_rating,imdb_votes,rotten_tomatoes_rating,metacritic_rating,awards_text,box_office,time_to_beat,game_engines,websites,game_modes,perspectives,videos,screenshots,franchise,dlc_count,release_date,families,rank_overall,best_players,min_age_community,language_dependence,followers,album_type,label,total_tracks,upc,audio_features,isrc,duration_ms,album_name,artist_names,preview_url,volumes,chapters,format,staff,description_length,description_parts,anilist_score,vote_count,popularity,track_number,themes'

        let query = supabase
            .from('global_items')
            .select(SELECTED_COLUMNS, { count: 'estimated' })
            .order(sortField, { ascending: sortOrder === 'asc', nullsFirst: false })
            .range((page - 1) * pageSize, page * pageSize - 1)

        // Text Search - require 3+ chars to avoid expensive full-table scans
        // Uses debouncedSearchQuery for performance (400ms delay on keystrokes)
        if (debouncedSearchQuery && debouncedSearchQuery.length >= 3) {
            // Use simpler pattern matching for better performance
            const cleanQuery = debouncedSearchQuery.trim()
            query = query.ilike('title', `%${cleanQuery}%`)
        }

        // URL-based filters (from FilterPill clicks)
        // Exact match filters
        if (activeFilters.director) {
            query = query.eq('director', activeFilters.director)
        }
        if (activeFilters.studio) {
            query = query.eq('studio', activeFilters.studio)
        }
        if (activeFilters.content_rating) {
            query = query.eq('content_rating', activeFilters.content_rating)
        }
        if (activeFilters.year) {
            query = query.eq('release_year', parseInt(activeFilters.year))
        }
        if (activeFilters.category) {
            query = query.eq('category_type', activeFilters.category.toUpperCase().replace(/-/g, '_'))
        }
        if (activeFilters.language) {
            query = query.eq('original_language', activeFilters.language)
        }
        if (activeFilters.writer) {
            query = query.ilike('writer', `%${activeFilters.writer}%`)
        }

        // Array contains filters (cast, genres, platforms, etc.)
        if (activeFilters.cast) {
            query = query.contains('cast', [activeFilters.cast])
        }
        if (activeFilters.genre) {
            query = query.contains('genres', [activeFilters.genre])
        }
        if (activeFilters.developer) {
            // Escape special characters for PostgREST query
            const dev = activeFilters.developer.replace(/"/g, '\\"').replace(/,/g, '\\,')
            query = query.or(`studio.eq."${dev}",developers.cs.{"${dev}"}`)
        }
        if (activeFilters.production) {
            // Escape special characters for PostgREST query
            const prod = activeFilters.production.replace(/"/g, '\\"').replace(/,/g, '\\,')
            query = query.or(`production_companies.cs.{"${prod}"},networks.cs.{"${prod}"},publishers.cs.{"${prod}"}`)
        }
        if (activeFilters.platform) {
            query = query.contains('platforms', [activeFilters.platform])
        }
        if (activeFilters.designer) {
            query = query.contains('designers', [activeFilters.designer])
        }
        if (activeFilters.mechanic) {
            query = query.contains('mechanics', [activeFilters.mechanic])
        }
        if (activeFilters.artist) {
            query = query.contains('artists', [activeFilters.artist])
        }
        // Tag filter - search in cached_tags JSONB
        if (activeFilters.tag) {
            query = query.contains('cached_tags', [{ name: activeFilters.tag }])
        }

        // Build OR conditions for quality filters
        const orConditions: string[] = []

        // Category Filter (AND logic - restricts scope)
        if (selectedCategories.length > 0) {
            query = query.in('category_type', selectedCategories)
        }

        // Quality Filters (OR logic - match ANY)
        if (missingImage) {
            orConditions.push('image_url.is.null')
        }

        if (uncategorized) {
            orConditions.push('category_type.is.null')
        }

        // Apply combined OR filter for quality issues
        if (orConditions.length > 0) {
            query = query.or(orConditions.join(','))
        }

        try {
            const { data, count, error } = await query

            if (error) {
                console.error('Error fetching items:', (error as any)?.message || error)
                console.error('Active filters:', JSON.stringify(activeFilters, null, 2))
                console.error('Search query:', debouncedSearchQuery)
                toast.error('Failed to load items: ' + ((error as any)?.message || 'Unknown error'))
                setItems([])
                setTotalPages(0)
                setTotalCount(0)
                return
            }

            setItems(data || [])
            setTotalPages(Math.ceil((count || 0) / pageSize))
            setTotalCount(count || 0)
        } catch (err: any) {
            console.error('Exception fetching items:', err)
            toast.error('Search failed: ' + (err?.message || 'Query timeout'))
            setItems([])
            setTotalPages(0)
            setTotalCount(0)
        } finally {
            setLoading(false)
        }
    }, [supabase, page, debouncedSearchQuery, missingImage, shortDesc, uncategorized, selectedCategories, pageSize, activeFilters, sortField, sortOrder])

    // Load items first (fast), then stats in background
    useEffect(() => {
        fetchItems()
    }, [fetchItems])

    // Reset page to 1 when search or category filters change (fixes search+filter combo bug)
    useEffect(() => {
        setPage(1)
    }, [debouncedSearchQuery, selectedCategories, missingImage, shortDesc, uncategorized])

    // Debounce search query - wait 400ms after user stops typing before triggering search
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearchQuery(searchQuery)
        }, 400)
        return () => clearTimeout(timer)
    }, [searchQuery])

    // Defer stats loading - runs after items are displayed
    useEffect(() => {
        const timer = setTimeout(() => fetchStats(), 100)
        return () => clearTimeout(timer)
    }, [fetchStats])

    // Select visible items
    useEffect(() => {
        // Reset selection when page/items change if desired, or keep cross-page selection?
        // Let's keep selection but make "Select All" only select visible items
    }, [items])

    // ========================================================================
    // ACTIONS
    // ========================================================================

    const handleSelectVisible = () => {
        const visibleIds = items.map(i => i.id)
        const allSelected = visibleIds.every(id => selectedIds.has(id))

        const newSet = new Set(selectedIds)
        if (allSelected) {
            visibleIds.forEach(id => newSet.delete(id))
        } else {
            visibleIds.forEach(id => newSet.add(id))
        }
        setSelectedIds(newSet)
    }

    // Track last clicked item for Shift selection - use useRef to persist across renders
    const lastClickedRef = useRef<string | null>(null)

    const handleItemClick = (id: string, event: React.MouseEvent) => {
        // Prevent text selection on shift+click
        if (event.shiftKey) {
            event.preventDefault()
        }

        // Don't select if clicking on action buttons (edit/view/regen)
        const target = event.target as HTMLElement
        if (target.closest('button') || target.closest('[role="button"]')) {
            return
        }

        const newSet = new Set(selectedIds)

        if (event.shiftKey && lastClickedRef.current) {
            // Shift+click: Select range between last clicked and current
            const lastIdx = items.findIndex(i => i.id === lastClickedRef.current)
            const currentIdx = items.findIndex(i => i.id === id)

            if (lastIdx !== -1 && currentIdx !== -1) {
                const start = Math.min(lastIdx, currentIdx)
                const end = Math.max(lastIdx, currentIdx)

                for (let i = start; i <= end; i++) {
                    newSet.add(items[i].id)
                }
            }
        } else if (event.ctrlKey || event.metaKey) {
            // Ctrl+click: Toggle single item (add/remove from selection)
            if (newSet.has(id)) {
                newSet.delete(id)
            } else {
                newSet.add(id)
            }
        } else {
            // Normal click: Toggle selection for this item
            if (newSet.has(id)) {
                // If already selected, deselect it
                newSet.delete(id)
            } else {
                // Otherwise clear others and select this one
                newSet.clear()
                newSet.add(id)
            }
        }

        lastClickedRef.current = id
        setSelectedIds(newSet)
    }

    // Double-click handler to open item details
    const handleItemDoubleClick = (item: GlobalItem) => {
        setViewItem(item)
    }

    // Clear selection handler
    const handleClearSelection = () => {
        setSelectedIds(new Set())
    }

    const handleBulkDelete = async () => {
        if (!deleteConfirm) return

        // Double confirmation for source delete
        if (deleteConfirm.type === 'source' && confirmText !== 'DELETE') {
            return
        }

        setActionLoading(true)

        if (deleteConfirm.type === 'selected') {
            const { error } = await (supabase
                .from('global_items') as any)
                .delete()
                .in('id', Array.from(selectedIds))

            if (!error) {
                setSelectedIds(new Set())
                fetchItems()
                fetchStats()
            }
        } else if (deleteConfirm.type === 'single' && deleteConfirm.id) {
            const { error } = await (supabase
                .from('global_items') as any)
                .delete()
                .eq('id', deleteConfirm.id)

            if (!error) {
                // Remove from local items immediately
                setItems(items => items.filter(i => i.id !== deleteConfirm.id))
                toast.success('Item deleted')
                setEditItem(null) // Close modal if open
                fetchStats()
            } else {
                toast.error('Failed to delete item')
            }
        } else if (deleteConfirm.type === 'source' && deleteConfirm.source) {
            const { data: itemsToDelete } = await (supabase
                .from('global_items') as any)
                .select('id, external_ids')

            const idsToDelete = (itemsToDelete as any[])
                ?.filter(item => item.external_ids && deleteConfirm.source! in item.external_ids)
                .map(item => item.id) || []

            if (idsToDelete.length > 0) {
                // Batch delete in chunks of 1000 to avoid request limits
                for (let i = 0; i < idsToDelete.length; i += 1000) {
                    await (supabase
                        .from('global_items') as any)
                        .delete()
                        .in('id', idsToDelete.slice(i, i + 1000))
                }

                fetchItems()
                fetchStats()
            }
        }

        setDeleteConfirm(null)
        setMaintenanceOpen(false)
        setConfirmText('')
        setActionLoading(false)
    }
    const doSearch = async (searchTerm: string) => {
        if (!searchTerm || searchTerm.length < 2) return

        const { searchMediaAction } = await import('@/lib/actions/media')

        // Use editItem type or category filter if available
        const type = editCategoryType || editItem?.category_type || 'general'

        const response = await searchMediaAction(searchTerm, type, null, undefined)

        if (response.success) {
            setMediaResults(response.data)
        } else {
            toast.error('Search failed')
        }
    }

    const handleMetadataMatch = async (result: any) => {
        // Update fields immediately
        setEditTitle(result.title)
        setEditImage(result.imageUrl || editImage)
        setImageUploadMode(result.imageUrl ? 'url' : imageUploadMode)
        setEditDescription('Γ£¿ Generating AI curated description...')
        setEditTags([]) // Clear tags

        // Store external ID and other metadata
        const newMetadata = {
            ...(typeof editItem?.metadata === 'object' ? editItem.metadata : {}),
            external_ids: { ...editItem?.external_ids, [result.source || 'tmdb']: result.id },
            release_year: result.year
        }
        setEditMetadata(JSON.stringify(newMetadata))

        setMediaResults([])

        // Trigger AI
        setIsGeneratingDescription(true)
        setIsGeneratingTags(true)

        const { generateDescriptionAction, generateTagsAction } = await import('@/lib/actions/ai')
        const type = editCategoryType || editItem?.category_type || 'general'

        // Description
        generateDescriptionAction({
            title: result.title,
            type: type,
            context: result.description
        }).then(data => {
            if (data.description) setEditDescription(data.description)
        }).finally(() => setIsGeneratingDescription(false))

        // Tags
        generateTagsAction({
            title: result.title,
            type: type,
            description: result.description
        }).then(async data => {
            if (data.tags && data.tags.length > 0) {
                const { createTagsBatch } = await import('@/lib/actions/tags')
                const validTags = await createTagsBatch(data.tags)
                setEditTags(validTags.map(t => t.id))
                toast.success(`Generated ${validTags.length} tags`)
            }
        }).finally(() => setIsGeneratingTags(false))
    }

    const handleAutoFill = async () => {
        if (!editTitle) return
        setIsGeneratingDescription(true)
        try {
            const { generateDescription } = await import('@/lib/actions/ai')
            const description = await generateDescription(editTitle, editCategoryType || editItem?.category_type || '')
            if (description) setEditDescription(description)
        } finally {
            setIsGeneratingDescription(false)
        }
    }

    const handleAutoTag = async () => {
        if (!editTitle) return
        setIsGeneratingTags(true)
        try {
            const { generateTags } = await import('@/lib/actions/ai')
            // generateTags already creates tags in DB and returns { id, name }[]
            const tags = await generateTags(editTitle, editDescription, editCategoryType || editItem?.category_type || '')
            if (tags.length > 0) {
                // Tags are already created, just add their IDs to the state
                const newIds = tags.map((t: { id: string; name: string }) => t.id)
                setEditTags(prev => Array.from(new Set([...prev, ...newIds])))
                toast.success(`Generated ${tags.length} tags`)
            } else {
                toast.error('No tags generated')
            }
        } catch (error) {
            console.error('Auto-tag error:', error)
            toast.error('Failed to generate tags')
        } finally {
            setIsGeneratingTags(false)
        }
    }

    const handleSaveEdit = async () => {
        if (!editItem) return
        setActionLoading(true)

        // Resolve tags to objects for cache
        let resolvedTags: { id: string; name: string }[] = []
        if (editTags.length > 0) {
            const { data } = await supabase.from('tags').select('id, name').in('id', editTags)
            resolvedTags = data || []
        }

        await (supabase
            .from('global_items') as any)
            .update({
                title: editTitle,
                description: editDescription,
                image_url: editImage,
                metadata: editMetadata ? JSON.parse(editMetadata) : editItem.metadata,
                cached_tags: resolvedTags,
                category_type: editCategoryType
            })
            .eq('id', editItem.id)

        setEditItem(null)
        fetchItems()
        setActionLoading(false)
    }

    const handleRegenerate = async (item: GlobalItem) => {
        // Add to loading set
        setRegeneratingDescriptionIds(prev => new Set(prev).add(item.id))

        try {
            // Call enrich-metadata with descriptionOnly=true (only regenerates description, skips metadata)
            const response = await fetch('/api/ai/enrich-metadata', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    itemId: item.id,
                    title: item.title,
                    type: item.category_type,
                    descriptionOnly: true  // Only regenerate description, skip metadata fetch
                })
            })

            if (response.ok) {
                const data = await response.json()
                // Update local state with description only
                setItems(prev => prev.map(i =>
                    i.id === item.id
                        ? {
                            ...i,
                            description: data.description,
                            description_parts: data.description_parts
                        }
                        : i
                ))

                toast.success('Description regenerated')
            } else {
                toast.error('Failed to regenerate description')
            }
        } catch (error) {
            console.error('Failed to regenerate:', error)
            toast.error('Failed to regenerate description')
        } finally {
            // Remove from loading set
            setRegeneratingDescriptionIds(prev => {
                const next = new Set(prev)
                next.delete(item.id)
                return next
            })
        }
    }

    // Force refresh all metadata from providers (OMDB, TMDB, etc.)
    const handleRefreshMetadata = async (item: GlobalItem) => {
        setRefreshingMetadataIds(prev => new Set(prev).add(item.id))

        try {
            const response = await fetch('/api/ai/enrich-metadata', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    itemId: item.id,
                    title: item.title,
                    type: item.category_type,
                    force: true  // Force update all fields
                })
            })

            if (response.ok) {
                const data = await response.json()
                // Update local state with all enriched fields
                setItems(prev => prev.map(i =>
                    i.id === item.id
                        ? {
                            ...i,
                            description: data.description,
                            description_parts: data.description_parts,
                            ...data.enrichedData
                        }
                        : i
                ))

                if (data.omdbRatings?.length > 0) {
                    toast.success(`Metadata refreshed: ${data.omdbRatings.join(', ')}`)
                } else if (data.enriched) {
                    toast.success(`Metadata refreshed: ${data.fieldsUpdated.length} fields updated`)
                } else {
                    toast.success('Metadata refreshed')
                }
            } else {
                toast.error('Failed to refresh metadata')
            }
        } catch (error) {
            console.error('Failed to refresh metadata:', error)
            toast.error('Failed to refresh metadata')
        } finally {
            setRefreshingMetadataIds(prev => {
                const next = new Set(prev)
                next.delete(item.id)
                return next
            })
        }
    }

    const handleGenerateTagsForItem = async (item: GlobalItem) => {
        // Add to loading set
        setRegeneratingTagIds(prev => new Set(prev).add(item.id))

        try {
            const { generateTagsAction } = await import('@/lib/actions/ai')
            const data = await generateTagsAction({
                title: item.title,
                type: item.category_type,
                description: item.description || ''
            })

            if (data.tags && data.tags.length > 0) {
                const { createTagsBatch } = await import('@/lib/actions/tags')
                const validTags = await createTagsBatch(data.tags)
                const cachedTags = validTags.map(t => ({ id: t.id, name: t.name }))

                // Save to database
                await (supabase.from('global_items') as any).update({
                    cached_tags: cachedTags
                }).eq('id', item.id)

                // Update local state immediately
                setItems(prev => prev.map(i =>
                    i.id === item.id
                        ? { ...i, cached_tags: cachedTags }
                        : i
                ))

                toast.success(`Generated ${validTags.length} tags`)
            } else {
                toast.error('No tags generated')
            }
        } catch (error) {
            console.error('Failed to generate tags:', error)
            toast.error('Failed to generate tags')
        } finally {
            // Remove from loading set
            setRegeneratingTagIds(prev => {
                const next = new Set(prev)
                next.delete(item.id)
                return next
            })
        }
    }

    // ========================================================================
    // BULK ACTIONS
    // ========================================================================

    const handleBulkRegenerateDescriptions = async () => {
        if (selectedIds.size === 0) return

        const ids = Array.from(selectedIds)
        const total = ids.length
        const limit = pLimit(5) // Concurrency of 5

        setBulkActionProgress({ current: 0, total, action: 'Regenerating descriptions' })

        let success = 0
        let completed = 0

        const promises = ids.map(id => limit(async () => {
            const item = items.find(it => it.id === id)
            if (!item) {
                completed++
                setBulkActionProgress({ current: completed, total, action: 'Regenerating descriptions' })
                return
            }

            try {
                const response = await fetch('/api/ai/regenerate-description', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ itemId: item.id, title: item.title, type: item.category_type })
                })
                if (response.ok) success++
            } catch (e) {
                console.error('Bulk regen error for', item.title, e)
            } finally {
                completed++
                setBulkActionProgress({ current: completed, total, action: 'Regenerating descriptions' })
            }
        }))

        await Promise.all(promises)

        setBulkActionProgress(null)
        setSelectedIds(new Set())
        fetchItems()
        toast.success(`Regenerated ${success}/${total} descriptions`)
    }

    const handleBulkRegenerateTags = async () => {
        if (selectedIds.size === 0) return

        const ids = Array.from(selectedIds)
        const total = ids.length
        const limit = pLimit(5) // Concurrency of 5

        setBulkActionProgress({ current: 0, total, action: 'Regenerating tags' })

        const { generateTagsAction } = await import('@/lib/actions/ai')
        const { createTagsBatch } = await import('@/lib/actions/tags')

        let success = 0
        let completed = 0

        const promises = ids.map(id => limit(async () => {
            const item = items.find(it => it.id === id)
            if (!item) {
                completed++
                setBulkActionProgress({ current: completed, total, action: 'Regenerating tags' })
                return
            }

            try {
                const data = await generateTagsAction({
                    title: item.title,
                    type: item.category_type,
                    description: item.description || ''
                })

                if (data.tags && data.tags.length > 0) {
                    const validTags = await createTagsBatch(data.tags)
                    await (supabase.from('global_items') as any).update({
                        cached_tags: validTags.map(t => ({ id: t.id, name: t.name }))
                    }).eq('id', item.id)
                    success++
                }
            } catch (e) {
                console.error('Bulk tag error for', item.title, e)
            } finally {
                completed++
                setBulkActionProgress({ current: completed, total, action: 'Regenerating tags' })
            }
        }))

        await Promise.all(promises)

        setBulkActionProgress(null)
        setSelectedIds(new Set())
        fetchItems()
        toast.success(`Regenerated tags for ${success}/${total} items`)
    }

    // ========================================================================
    // RENDER HELPERS
    // ========================================================================

    const getGridCols = () => {
        // Map 0-100 slider value to grid columns
        // 0 = smallest (most columns), 100 = largest (fewest columns)
        if (tileSize <= 15) return 'grid-cols-6 md:grid-cols-8 lg:grid-cols-10 xl:grid-cols-12'
        if (tileSize <= 30) return 'grid-cols-4 md:grid-cols-6 lg:grid-cols-8 xl:grid-cols-10'
        if (tileSize <= 50) return 'grid-cols-3 md:grid-cols-5 lg:grid-cols-6 xl:grid-cols-8'
        if (tileSize <= 70) return 'grid-cols-2 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6'
        if (tileSize <= 85) return 'grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5'
        return 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4'
    }

    // ========================================================================
    // RENDER
    // ========================================================================

    return (
        <div className="min-h-screen text-white p-6 font-sans selection:bg-cyan-500/30">

            {/* Header */}
            <div className="flex justify-between items-start mb-6">
                <div>
                    <h1 className="text-3xl font-serif font-bold text-white mb-2">Data Browser</h1>
                    <p className="text-zinc-400">Manage and curate your content database</p>
                </div>

                <div className="flex items-center gap-3">
                    <LayoutGrid className="w-4 h-4 text-zinc-400" />
                    <Slider
                        value={[tileSize]}
                        onValueChange={(v) => setTileSize(v[0])}
                        min={0}
                        max={100}
                        step={5}
                        className="w-32"
                    />
                </div>
            </div>

            {/* Stats Bar */}
            <div className="bg-zinc-900/30 border border-zinc-800 rounded-lg p-4 mb-6 backdrop-blur-md">
                <div className="flex flex-wrap gap-6 items-center">
                    <div className="text-lg font-semibold">
                        Total Items: <span className="text-cyan-400">{stats.total.toLocaleString()}</span>
                    </div>
                    <div className="h-6 w-px bg-zinc-800" />
                    {Object.entries(stats.byCategory)
                        .sort((a, b) => {
                            // Push 'null' (Uncategorized) to the end
                            if (a[0] === 'null') return 1
                            if (b[0] === 'null') return -1
                            // Then sort by count descending
                            return b[1] - a[1]
                        })
                        .slice(0, 12)
                        .map(([cat, count]) => {
                            const label = formatCategoryLabel(cat)
                            const isNull = cat === 'null'
                            return (
                                <div key={cat} className="text-sm text-zinc-400 flex items-center gap-1.5">
                                    <span className={isNull ? "text-red-400 font-medium" : "text-zinc-300"}>
                                        {label}:
                                    </span>
                                    <span className="text-white font-mono">{count.toLocaleString()}</span>
                                </div>
                            )
                        })}
                </div>
            </div>

            {/* Active Filters Bar */}
            {hasActiveFilters && (
                <div className="bg-red-950/20 border border-red-900/30 rounded-lg p-3 mb-6 flex flex-wrap items-center gap-2">
                    <span className="text-sm text-red-300 font-medium mr-2">Active Filters:</span>
                    {Object.entries(activeFilters).map(([key, value]) => (
                        <Badge
                            key={key}
                            className="bg-red-900/50 text-red-200 border-red-800 cursor-pointer hover:bg-red-800/50 transition-colors"
                            onClick={() => removeFilter(key)}
                        >
                            <span className="text-red-400 mr-1 capitalize">{key.replace(/_/g, ' ')}:</span>
                            {value}
                            <X className="w-3 h-3 ml-1.5" />
                        </Badge>
                    ))}
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={clearAllFilters}
                        className="text-red-400 hover:text-red-300 hover:bg-red-900/30 ml-auto"
                    >
                        Clear All
                    </Button>
                </div>
            )}

            <div className="flex gap-6 items-start">
                {/* Sidebar Filters */}
                <div className="w-64 flex-shrink-0 sticky top-6">
                    <div className="bg-zinc-900/30 border border-zinc-800 rounded-lg p-4 backdrop-blur-md">
                        <h3 className="font-semibold mb-4 text-zinc-300">Filters</h3>

                        {/* Search */}
                        <div className="mb-4">
                            <div className="relative">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500" />
                                <Input
                                    placeholder="Search titles..."
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="pl-9 bg-zinc-900/50 border-zinc-700"
                                />
                            </div>
                        </div>

                        {/* Category Filter */}
                        <div className="mb-4">
                            <h4 className="text-sm font-medium text-zinc-400 mb-2">Category</h4>
                            <div className="space-y-1.5">
                                {Object.entries(CATEGORY_ICONS).map(([key, { icon: Icon, color, label }]) => (
                                    <label key={key} className="flex items-center gap-2 cursor-pointer hover:bg-zinc-800/50 p-1.5 rounded transition-colors">
                                        <Checkbox
                                            checked={selectedCategories.includes(key)}
                                            onCheckedChange={(checked) => {
                                                if (checked) setSelectedCategories([...selectedCategories, key])
                                                else setSelectedCategories(selectedCategories.filter(s => s !== key))
                                            }}
                                            className="data-[state=checked]:bg-cyan-600 data-[state=checked]:border-cyan-600 border-zinc-600"
                                        />
                                        <Icon className={`w-4 h-4 ${color}`} />
                                        <span className="text-sm text-zinc-300">{label}</span>
                                    </label>
                                ))}
                            </div>
                        </div>

                        {/* Quality Filters */}
                        <div className="mb-4">
                            <h4 className="text-sm font-medium text-zinc-400 mb-2">Quality Issues</h4>
                            <div className="space-y-1.5">
                                <label className="flex items-center gap-2 cursor-pointer hover:bg-zinc-800/50 p-1.5 rounded transition-colors">
                                    <Checkbox checked={missingImage} onCheckedChange={(c) => setMissingImage(!!c)} className="border-zinc-600" />
                                    <ImageIcon className="w-4 h-4 text-yellow-500" />
                                    <span className="text-sm text-zinc-300">Missing Image</span>
                                </label>
                                <label className="flex items-center gap-2 cursor-pointer hover:bg-zinc-800/50 p-1.5 rounded transition-colors">
                                    <Checkbox checked={shortDesc} onCheckedChange={(c) => setShortDesc(!!c)} className="border-zinc-600" />
                                    <FileText className="w-4 h-4 text-orange-500" />
                                    <span className="text-sm text-zinc-300">Short Description</span>
                                </label>
                                <label className="flex items-center gap-2 cursor-pointer hover:bg-zinc-800/50 p-1.5 rounded transition-colors">
                                    <Checkbox checked={uncategorized} onCheckedChange={(c) => setUncategorized(!!c)} className="border-zinc-600" />
                                    <AlertTriangle className="w-4 h-4 text-red-500" />
                                    <span className="text-sm text-zinc-300">Uncategorized</span>
                                </label>
                            </div>
                        </div>

                        {/* Maintenance Button */}
                        <div className="pt-4 border-t border-zinc-800 mt-4">
                            <Button
                                variant="outline"
                                className="w-full justify-start text-zinc-400 hover:text-white hover:bg-zinc-800 border-zinc-700"
                                onClick={() => setMaintenanceOpen(true)}
                            >
                                <ShieldAlert className="w-4 h-4 mr-2" />
                                Database Maintenance
                            </Button>
                        </div>
                    </div>
                </div>

                {/* Main Content */}
                <div className="flex-1">
                    {/* Actions Bar */}
                    <div className="flex flex-col gap-4 mb-4 bg-zinc-900/30 p-4 rounded-lg border border-zinc-800">
                        {/* Advanced Filters */}
                        <div className="flex flex-wrap items-center justify-between gap-4">
                            <AdvancedFilterBar
                                categoryType={selectedCategories[0]} // Pass first selected category as context, or undefined
                                currentSort={sortField}
                                currentOrder={sortOrder}
                                onSortChange={(field: string, order: 'asc' | 'desc') => {
                                    setSortField(field)
                                    setSortOrder(order)
                                }}
                            />

                            <div className="flex items-center gap-2">
                                <div className="flex items-center gap-4 pl-2">
                                    <div className="flex items-center gap-2">
                                        <Button
                                            variant="outline"
                                            size="sm"
                                            onClick={handleSelectVisible}
                                            className="h-7 text-xs border-zinc-700 hover:bg-zinc-800"
                                        >
                                            {items.length > 0 && items.every(i => selectedIds.has(i.id)) ? 'Deselect All' : 'Select All'}
                                        </Button>
                                        {selectedIds.size > 0 && (
                                            <Button
                                                variant="ghost"
                                                size="sm"
                                                onClick={handleClearSelection}
                                                className="h-7 text-xs text-zinc-400 hover:text-white"
                                            >
                                                <X className="w-3 h-3 mr-1" />
                                                Clear ({selectedIds.size})
                                            </Button>
                                        )}
                                        <span className="text-xs text-zinc-600">|</span>
                                        <span className="text-xs text-zinc-500">
                                            {items.length} on page / {totalCount.toLocaleString()} total
                                        </span>

                                    </div>

                                    {selectedIds.size > 0 && !bulkActionProgress && (
                                        <>
                                            <div className="h-4 w-px bg-zinc-700" />
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                onClick={handleBulkRegenerateDescriptions}
                                                className="h-8 text-xs border-zinc-700 hover:bg-zinc-800"
                                            >
                                                <Sparkles className="w-3 h-3 mr-2" />
                                                Regen Descriptions
                                            </Button>
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                onClick={handleBulkRegenerateTags}
                                                className="h-8 text-xs border-zinc-700 hover:bg-zinc-800"
                                            >
                                                <Tag className="w-3 h-3 mr-2" />
                                                Regen Tags
                                            </Button>
                                            <Button
                                                variant="destructive"
                                                size="sm"
                                                onClick={() => setDeleteConfirm({ type: 'selected' })}
                                                className="h-8 text-xs"
                                            >
                                                <Trash2 className="w-3 h-3 mr-2" />
                                                Delete
                                            </Button>
                                        </>
                                    )}

                                    {bulkActionProgress && (
                                        <div className="flex items-center gap-2 text-xs text-cyan-400">
                                            <RefreshCw className="w-3 h-3 animate-spin" />
                                            <span>{bulkActionProgress.action}: {bulkActionProgress.current}/{bulkActionProgress.total}</span>
                                        </div>
                                    )}
                                </div>

                                <div className="flex items-center gap-2">
                                    <Button
                                        variant="ghost"
                                        size="sm"
                                        onClick={() => { fetchItems(); fetchStats(); }}
                                        className="h-8 text-zinc-400 hover:text-white"
                                    >
                                        <RefreshCw className="w-3.5 h-3.5 mr-2" />
                                        Refresh
                                    </Button>
                                </div>
                            </div>

                            {/* Items Grid */}
                            {loading ? (
                                <div className="flex items-center justify-center w-full h-64">
                                    <div className="flex flex-col items-center gap-2">
                                        <RefreshCw className="w-8 h-8 animate-spin text-cyan-500" />
                                        <p className="text-zinc-500 text-sm">Loading items...</p>
                                    </div>
                                </div>
                            ) : (
                                <div className={`grid gap-4 ${getGridCols()}`}>
                                    {items.map(item => {
                                        const catInfo = CATEGORY_ICONS[item.category_type]
                                        const CategoryIcon = catInfo?.icon || Film

                                        return (
                                            <Card
                                                key={item.id}
                                                onClick={(e) => handleItemClick(item.id, e)}
                                                onDoubleClick={() => handleItemDoubleClick(item)}
                                                className={`select-none group bg-zinc-900/40 border-zinc-800/50 overflow-hidden cursor-pointer transition-all hover:border-zinc-600 hover:shadow-lg hover:shadow-cyan-900/10 ${selectedIds.has(item.id) ? 'ring-2 ring-cyan-500 border-transparent' : ''}`}
                                            >
                                                <div className="relative aspect-[2/3] bg-zinc-900 overflow-hidden">
                                                    {item.image_url ? (
                                                        <Image
                                                            src={item.image_url}
                                                            alt={item.title}
                                                            fill
                                                            className="object-cover transition-transform duration-500 group-hover:scale-105"
                                                            unoptimized
                                                        />
                                                    ) : (
                                                        <div className="w-full h-full flex flex-col items-center justify-center text-zinc-700 p-4 text-center">
                                                            <ImageIcon className="w-8 h-8 mb-2 opacity-50" />
                                                            <span className="text-xs">No Image</span>
                                                        </div>
                                                    )}

                                                    {/* Overlays */}
                                                    <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/20 to-transparent opacity-60 group-hover:opacity-80 transition-opacity" />

                                                    {/* Selection Indicator (checkmark when selected) */}
                                                    {selectedIds.has(item.id) && (
                                                        <div className="absolute top-2 left-2 w-5 h-5 bg-cyan-500 rounded-full flex items-center justify-center z-10">
                                                            <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                                                                <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                                                            </svg>
                                                        </div>
                                                    )}

                                                    {/* Category Icon (always visible, top-right) */}
                                                    <div className="absolute top-2 right-2 z-10 group-hover:opacity-0 transition-opacity">
                                                        <div className="w-6 h-6 rounded-md bg-black/50 backdrop-blur-sm flex items-center justify-center border border-white/10">
                                                            <CategoryIcon className="w-3.5 h-3.5 text-white/80" />
                                                        </div>
                                                    </div>

                                                    {/* Top-Right Context Menu (appears on hover) */}
                                                    <div className="absolute top-2 right-2 z-20 opacity-0 group-hover:opacity-100 transition-opacity">
                                                        <DropdownMenu>
                                                            <DropdownMenuTrigger asChild>
                                                                <Button
                                                                    size="icon"
                                                                    variant="secondary"
                                                                    className="h-7 w-7 rounded-full bg-black/60 hover:bg-black/80 text-white border-0 backdrop-blur-md"
                                                                    onClick={(e) => e.stopPropagation()}
                                                                >
                                                                    <MoreHorizontal className="w-4 h-4" />
                                                                </Button>
                                                            </DropdownMenuTrigger>
                                                            <DropdownMenuContent align="end" className="bg-zinc-900 border-zinc-800 min-w-[140px]">
                                                                <DropdownMenuItem
                                                                    onClick={(e) => {
                                                                        e.stopPropagation()
                                                                        setEditItem(item)
                                                                        setEditCategoryType(item.category_type)
                                                                        setEditTitle(item.title)
                                                                        setEditDescription(item.description || '')
                                                                        setEditImage(item.image_url || '')
                                                                        setEditTags(parseCachedTags(item.cached_tags).map(t => t.id))
                                                                        setEditMetadata(item.metadata ? JSON.stringify(item.metadata) : '')
                                                                        setEditMode('edit')
                                                                    }}
                                                                    className="text-zinc-300 focus:bg-zinc-800 focus:text-white cursor-pointer"
                                                                >
                                                                    <Pencil className="w-3.5 h-3.5 mr-2" />
                                                                    Edit
                                                                </DropdownMenuItem>
                                                                <DropdownMenuSeparator className="bg-zinc-800" />
                                                                <DropdownMenuItem
                                                                    onClick={(e) => {
                                                                        e.stopPropagation()
                                                                        handleRegenerate(item)
                                                                    }}
                                                                    disabled={regeneratingDescriptionIds.has(item.id)}
                                                                    className="text-zinc-300 focus:bg-zinc-800 focus:text-white cursor-pointer"
                                                                >
                                                                    <Wand2 className={`w-3.5 h-3.5 mr-2 ${regeneratingDescriptionIds.has(item.id) ? 'animate-pulse' : ''}`} />
                                                                    Regenerate Description
                                                                </DropdownMenuItem>
                                                                <DropdownMenuItem
                                                                    onClick={(e) => {
                                                                        e.stopPropagation()
                                                                        handleGenerateTagsForItem(item)
                                                                    }}
                                                                    disabled={regeneratingTagIds.has(item.id)}
                                                                    className="text-zinc-300 focus:bg-zinc-800 focus:text-white cursor-pointer"
                                                                >
                                                                    <Tag className="w-3.5 h-3.5 mr-2" />
                                                                    Generate Tags
                                                                </DropdownMenuItem>
                                                                <DropdownMenuItem
                                                                    onClick={(e) => {
                                                                        e.stopPropagation()
                                                                        handleRefreshMetadata(item)
                                                                    }}
                                                                    disabled={refreshingMetadataIds.has(item.id)}
                                                                    className="text-zinc-300 focus:bg-zinc-800 focus:text-white cursor-pointer"
                                                                >
                                                                    <RefreshCw className={`w-3.5 h-3.5 mr-2 ${refreshingMetadataIds.has(item.id) ? 'animate-spin' : ''}`} />
                                                                    Refresh Metadata
                                                                </DropdownMenuItem>
                                                                <DropdownMenuItem
                                                                    onClick={(e) => {
                                                                        e.stopPropagation()
                                                                        console.log('Raw data:', item)
                                                                        toast.info('Raw data logged to console')
                                                                    }}
                                                                    className="text-zinc-300 focus:bg-zinc-800 focus:text-white cursor-pointer"
                                                                >
                                                                    <FileText className="w-3.5 h-3.5 mr-2" />
                                                                    Raw Data
                                                                </DropdownMenuItem>
                                                                <DropdownMenuItem
                                                                    onClick={(e) => {
                                                                        e.stopPropagation()
                                                                        setReportItem(item)
                                                                    }}
                                                                    className="text-amber-400 focus:bg-amber-950/50 focus:text-amber-300 cursor-pointer"
                                                                >
                                                                    <Flag className="w-3.5 h-3.5 mr-2" />
                                                                    Flag Data
                                                                </DropdownMenuItem>
                                                                <DropdownMenuSeparator className="bg-zinc-800" />
                                                                <DropdownMenuItem
                                                                    onClick={(e) => {
                                                                        e.stopPropagation()
                                                                        setDeleteConfirm({ type: 'single', id: item.id })
                                                                    }}
                                                                    className="text-red-400 focus:bg-red-950/50 focus:text-red-300 cursor-pointer"
                                                                >
                                                                    <Trash2 className="w-3.5 h-3.5 mr-2" />
                                                                    Delete
                                                                </DropdownMenuItem>
                                                            </DropdownMenuContent>
                                                        </DropdownMenu>
                                                    </div>

                                                    {/* Hero Action - View Details Button */}
                                                    <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/30 backdrop-blur-[1px]">
                                                        <Button
                                                            variant="secondary"
                                                            className="bg-cyan-600 hover:bg-cyan-500 text-white border-0 shadow-lg shadow-cyan-900/30 px-4 py-2 h-auto"
                                                            onClick={(e) => {
                                                                e.stopPropagation()
                                                                setViewItem(item)
                                                            }}
                                                        >
                                                            <span className="text-sm font-medium">View Details</span>
                                                        </Button>
                                                    </div>

                                                    {/* Title Overlay with Year */}
                                                    <div className="absolute bottom-0 left-0 right-0 p-3 pointer-events-none">
                                                        <h4 className="font-medium text-sm text-white leading-tight line-clamp-2 drop-shadow-md">{item.title}</h4>
                                                        {item.release_year && (
                                                            <p className="text-xs text-zinc-400 mt-0.5">{item.release_year}</p>
                                                        )}
                                                    </div>
                                                </div>

                                                {/* Description Footer */}
                                                <CardContent className="p-3 bg-zinc-900">
                                                    <p className="text-[11px] text-zinc-400 line-clamp-3 leading-relaxed">
                                                        {item.description || <span className="italic opacity-50">No description available.</span>}
                                                    </p>
                                                    {/* Tags Display */}
                                                    {(() => {
                                                        const tags = parseCachedTags(item.cached_tags)
                                                        return tags.length > 0 && (
                                                            <div className="flex flex-wrap gap-1 mt-2">
                                                                {tags.slice(0, 3).map(tag => (
                                                                    <Badge key={tag.id} variant="secondary" className="text-[9px] px-1.5 py-0 h-4 bg-zinc-800 text-zinc-400 border-0">
                                                                        {tag.name}
                                                                    </Badge>
                                                                ))}
                                                                {tags.length > 3 && (
                                                                    <span className="text-[9px] text-zinc-500 self-center">+{tags.length - 3}</span>
                                                                )}
                                                            </div>
                                                        )
                                                    })()}
                                                </CardContent>
                                            </Card>
                                        )
                                    })}
                                </div>
                            )}

                            {/* Pagination */}
                            <div className="w-full flex flex-col items-center gap-3 mt-8 pb-8">
                                <div className="flex items-center gap-2">
                                    {/* First Page */}
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        disabled={page === 1}
                                        onClick={() => setPage(1)}
                                        className="bg-black border-zinc-700 px-2"
                                        title="First Page"
                                    >
                                        <ChevronLeft className="w-4 h-4" />
                                        <ChevronLeft className="w-4 h-4 -ml-2" />
                                    </Button>

                                    {/* Previous */}
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        disabled={page === 1}
                                        onClick={() => setPage(p => p - 1)}
                                        className="bg-black border-zinc-700"
                                    >
                                        <ChevronLeft className="w-4 h-4 mr-1" />
                                        Prev
                                    </Button>

                                    {/* Page Input */}
                                    <div className="flex items-center gap-2 px-3">
                                        <span className="text-sm text-zinc-500">Page</span>
                                        <Input
                                            type="number"
                                            min={1}
                                            max={totalPages}
                                            value={page}
                                            onChange={(e) => {
                                                const val = parseInt(e.target.value)
                                                if (!isNaN(val) && val >= 1 && val <= totalPages) {
                                                    setPage(val)
                                                }
                                            }}
                                            onBlur={(e) => {
                                                const val = parseInt(e.target.value)
                                                if (isNaN(val) || val < 1) setPage(1)
                                                else if (val > totalPages) setPage(totalPages)
                                            }}
                                            className="w-16 h-8 bg-zinc-900 border-zinc-700 text-center font-mono text-sm"
                                        />
                                        <span className="text-sm text-zinc-500">of</span>
                                        <span className="text-sm text-zinc-300 font-mono">{totalPages}</span>
                                    </div>

                                    {/* Next */}
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        disabled={page === totalPages}
                                        onClick={() => setPage(p => p + 1)}
                                        className="bg-black border-zinc-700"
                                    >
                                        Next
                                        <ChevronRight className="w-4 h-4 ml-1" />
                                    </Button>

                                    {/* Last Page */}
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        disabled={page === totalPages}
                                        onClick={() => setPage(totalPages)}
                                        className="bg-black border-zinc-700 px-2"
                                        title="Last Page"
                                    >
                                        <ChevronRight className="w-4 h-4" />
                                        <ChevronRight className="w-4 h-4 -ml-2" />
                                    </Button>
                                </div>

                                {/* Item Count Info */}
                                <span className="text-xs text-zinc-500">
                                    {totalCount.toLocaleString()} items total
                                </span>
                            </div>
                        </div>
                    </div>

                    {/* View Mode */}
                    <ItemDetailView
                        item={editItem as any}
                        isOpen={!!editItem && editMode === 'view'}
                        onClose={() => { setEditItem(null); setEditMode('view'); }}
                        onEdit={() => setEditMode('edit')}
                        onDelete={() => {
                            if (editItem) {
                                setDeleteConfirm({ type: 'single', id: editItem.id })
                            }
                        }}
                    />

                    {/* Edit Mode */}
                    <Dialog open={!!editItem && editMode === 'edit'} onOpenChange={(open) => { if (!open) { setEditItem(null); setEditMode('view'); } }}>
                        <DialogContent className="bg-zinc-950 border-zinc-800 sm:max-w-[900px] max-h-[90vh] overflow-y-auto">
                            <DialogHeader className="pb-2">
                                <DialogTitle className="font-serif text-xl">Edit Item</DialogTitle>
                            </DialogHeader>



                            <div className="grid gap-6 py-4">
                                {/* Title Row */}
                                <div className="grid gap-2">
                                    <div className="flex justify-between items-center">
                                        <label className="text-sm font-medium text-zinc-300 uppercase tracking-wider">Name</label>
                                    </div>
                                    <div className="flex gap-2">
                                        <Input
                                            value={editTitle}
                                            onChange={(e) => setEditTitle(e.target.value)}
                                            className="bg-zinc-900/50 border-zinc-800 font-medium"
                                            placeholder="Item Title"
                                        />
                                        <Button
                                            variant="secondary"
                                            onClick={() => doSearch(editTitle)}
                                            disabled={!editTitle}
                                            className="shrink-0 bg-zinc-800 hover:bg-zinc-700 text-zinc-300"
                                        >
                                            <Search className="w-4 h-4 mr-2" />
                                            Search
                                        </Button>
                                    </div>

                                    {/* Search Results */}
                                    {mediaResults.length > 0 && (
                                        <div className="mt-2 grid grid-cols-1 gap-1 bg-zinc-900 border border-zinc-800 rounded-md p-2 max-h-[200px] overflow-y-auto">
                                            <div className="flex justify-between items-center px-1 pb-2">
                                                <span className="text-xs text-zinc-500">Select to auto-fill:</span>
                                                <Button variant="ghost" size="sm" className="h-5 text-[10px]" onClick={() => setMediaResults([])}>Clear</Button>
                                            </div>
                                            {mediaResults.map((result, i) => (
                                                <button
                                                    key={i}
                                                    onClick={() => handleMetadataMatch(result)}
                                                    className="flex items-start gap-3 p-2 hover:bg-zinc-800 rounded text-left transition-colors group"
                                                >
                                                    <div className="w-8 h-12 bg-zinc-800 rounded overflow-hidden shrink-0 relative">
                                                        {result.imageUrl ? <Image src={result.imageUrl} alt="" fill className="object-cover" /> : null}
                                                    </div>
                                                    <div>
                                                        <div className="text-sm font-medium text-zinc-300 group-hover:text-cyan-400">{result.title}</div>
                                                        <div className="text-xs text-zinc-500 line-clamp-1">{result.description}</div>
                                                    </div>
                                                </button>
                                            ))}
                                        </div>
                                    )}
                                </div>

                                {/* Category */}
                                <div className="grid gap-2">
                                    <label className="text-sm font-medium text-zinc-300 uppercase tracking-wider">Category</label>
                                    <Select value={editCategoryType || 'null'} onValueChange={(val) => setEditCategoryType(val === 'null' ? null : val)}>
                                        <SelectTrigger className="bg-zinc-900/50 border-zinc-800">
                                            <SelectValue placeholder="Select a category" />
                                        </SelectTrigger>
                                        <SelectContent className="bg-zinc-900 border-zinc-800 text-zinc-300">
                                            <SelectItem value="null">Uncategorized</SelectItem>
                                            {Object.entries(CATEGORY_LABELS).map(([key, label]) => (
                                                <SelectItem key={key} value={key}>{label}</SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>

                                {/* Description */}
                                <div className="grid gap-2">
                                    <div className="flex justify-between items-center">
                                        <label className="text-sm font-medium text-zinc-300 uppercase tracking-wider">Description</label>
                                        <Button
                                            variant="ghost"
                                            size="sm"
                                            className="h-6 text-xs text-cyan-500 hover:text-cyan-400 hover:bg-cyan-950/30"
                                            onClick={handleAutoFill}
                                            disabled={isGeneratingDescription || !editTitle}
                                        >
                                            {isGeneratingDescription ? <Loader2 className="w-3 h-3 animate-spin mr-1" /> : <Wand2 className="w-3 h-3 mr-1" />}
                                            Auto-Fill
                                        </Button>
                                    </div>
                                    <Textarea
                                        value={editDescription}
                                        onChange={(e) => setEditDescription(e.target.value)}
                                        rows={6}
                                        className={`bg-zinc-900/50 border-zinc-800 text-sm leading-relaxed text-zinc-300 resize-none ${isGeneratingDescription ? 'animate-pulse' : ''}`}
                                    />
                                </div>

                                {/* Bottom Row: Image & Tags */}
                                <div className="grid grid-cols-1 md:grid-cols-[160px_1fr] gap-6">
                                    {/* Image Column */}
                                    <div className="space-y-3">
                                        <label className="text-sm font-medium text-zinc-300 uppercase tracking-wider block">Image</label>
                                        <div className="aspect-[2/3] bg-zinc-900 rounded-lg overflow-hidden border border-zinc-800 relative group">
                                            {editImage ? (
                                                <>
                                                    <Image src={editImage} alt="Preview" fill className="object-cover" />
                                                    <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-2 p-2">
                                                        <Button size="sm" variant="secondary" className="w-full h-7 text-xs" onClick={() => setImageToCrop(editImage)}>
                                                            <Crop className="w-3 h-3 mr-1" /> Crop
                                                        </Button>
                                                        <Button size="sm" variant="destructive" className="w-full h-7 text-xs" onClick={() => setEditImage('')}>
                                                            <Trash2 className="w-3 h-3 mr-1" /> Remove
                                                        </Button>
                                                    </div>
                                                </>
                                            ) : (
                                                <div className="w-full h-full flex flex-col items-center justify-center text-zinc-600 gap-2 p-4 text-center">
                                                    <ImageIcon className="w-6 h-6" />
                                                    <span className="text-[10px]">No Image</span>
                                                </div>
                                            )}
                                        </div>

                                        {!editImage && (
                                            <div className="grid grid-cols-2 gap-2">
                                                <Button variant={imageUploadMode === 'url' ? 'secondary' : 'outline'} size="sm" onClick={() => setImageUploadMode('url')} className="text-xs h-7">URL</Button>
                                                <Button variant={imageUploadMode === 'upload' ? 'secondary' : 'outline'} size="sm" onClick={() => setImageUploadMode('upload')} className="text-xs h-7">Up</Button>
                                            </div>
                                        )}

                                        {editImage ? null : imageUploadMode === 'url' ? (
                                            <Input value={editImage} onChange={e => setEditImage(e.target.value)} className="h-8 text-xs bg-zinc-900 border-zinc-800" placeholder="https://..." />
                                        ) : (
                                            <Input
                                                type="file"
                                                className="h-8 text-xs bg-zinc-900 border-zinc-800 file:text-zinc-400"
                                                onChange={(e) => {
                                                    const file = e.target.files?.[0]
                                                    if (file) {
                                                        const reader = new FileReader()
                                                        reader.onload = () => setImageToCrop(reader.result as string)
                                                        reader.readAsDataURL(file)
                                                    }
                                                }}
                                            />
                                        )}
                                    </div>

                                    {/* Tags Column */}
                                    <div className="space-y-3">
                                        <div className="flex justify-between items-center">
                                            <label className="text-sm font-medium text-zinc-300 uppercase tracking-wider">Tags</label>
                                            <Button
                                                variant="ghost"
                                                size="sm"
                                                className="h-6 text-xs text-purple-400 hover:text-purple-300 hover:bg-purple-950/30"
                                                onClick={handleAutoTag}
                                                disabled={isGeneratingTags || !editTitle}
                                            >
                                                {isGeneratingTags ? <Loader2 className="w-3 h-3 animate-spin mr-1" /> : <Wand2 className="w-3 h-3 mr-1" />}
                                                Auto-Tag
                                            </Button>
                                        </div>
                                        <div className="min-h-[200px] bg-zinc-900/30 border border-zinc-800 rounded-lg p-2">
                                            <TagSelector
                                                selectedTags={editTags}
                                                onTagsChange={setEditTags}
                                                isLoading={isGeneratingTags}
                                            />
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <DialogFooter className="border-t border-zinc-800/50 pt-4 flex justify-between sm:justify-between items-center">
                                <Button
                                    variant="destructive"
                                    onClick={() => {
                                        if (editItem) {
                                            setDeleteConfirm({ type: 'single', id: editItem.id })
                                        }
                                    }}
                                    className="bg-red-950/50 text-white hover:bg-red-900/50 border border-red-900/50"
                                >
                                    <Trash2 className="w-4 h-4 mr-2" />
                                    Delete Item
                                </Button>
                                <div className="flex gap-2">
                                    <Button variant="ghost" onClick={() => setEditMode('view')}>Cancel</Button>
                                    <Button onClick={handleSaveEdit} disabled={actionLoading} className="bg-cyan-600 hover:bg-cyan-700 text-white">
                                        {actionLoading ? <RefreshCw className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                                        Save Changes
                                    </Button>
                                </div>
                            </DialogFooter>
                        </DialogContent>
                    </Dialog>

                    {/* Image Cropper Modal */}
                    {imageToCrop && (
                        <ImageCropper
                            imageSrc={imageToCrop}
                            aspectRatio={2 / 3}
                            onCropComplete={async (croppedImage) => {
                                const response = await fetch(croppedImage)
                                const blob = await response.blob()
                                const fileFormData = new FormData()
                                fileFormData.append('file', blob, 'cropped.jpg')
                                const { uploadImage } = await import('@/lib/actions/upload')
                                const url = await uploadImage(fileFormData)
                                if (url) setEditImage(url)
                                setImageToCrop(null)
                            }}
                            onCancel={() => setImageToCrop(null)}
                        />
                    )}


                    {/* Maintenance Modal */}
                    <Dialog open={maintenanceOpen} onOpenChange={setMaintenanceOpen}>
                        <DialogContent className="bg-zinc-950 border-zinc-800 sm:max-w-md">
                            <DialogHeader>
                                <DialogTitle className="flex items-center gap-2 text-zinc-100 font-bold">
                                    <Settings className="w-5 h-5 text-blue-500" />
                                    System Configuration
                                </DialogTitle>
                                <DialogDescription className="text-zinc-400">
                                    Manage API keys and database maintenance.
                                </DialogDescription>
                            </DialogHeader>

                            <div className="space-y-6 py-4">
                                {/* API Keys Section */}
                                <div className="space-y-3">
                                    <h4 className="text-sm font-medium text-zinc-300 flex items-center gap-2">
                                        <Key className="w-4 h-4 text-yellow-500" />
                                        API Keys
                                    </h4>
                                    <div className="space-y-2">
                                        <label className="text-xs text-zinc-500">SteamGridDB API Key (Vertical Covers)</label>
                                        <div className="flex gap-2">
                                            <Input
                                                type="password"
                                                placeholder="Enter key..."
                                                value={steamGridKey}
                                                onChange={(e) => setSteamGridKey(e.target.value)}
                                                className="bg-zinc-900 border-zinc-800 text-zinc-200 text-sm"
                                            />
                                            <Button
                                                size="sm"
                                                className="bg-blue-600 hover:bg-blue-500"
                                                onClick={handleSaveConfig}
                                                disabled={actionLoading}
                                            >
                                                Save
                                            </Button>
                                        </div>
                                        <p className="text-[10px] text-zinc-600">
                                            Required for high-quality game cover harvesting.
                                        </p>
                                    </div>
                                </div>

                                <div className="h-px bg-zinc-800 w-full" />

                                {/* Maintenance Section */}
                                <div className="space-y-3">
                                    <h4 className="text-sm font-medium text-red-400 flex items-center gap-2">
                                        <ShieldAlert className="w-4 h-4" />
                                        Danger Zone
                                    </h4>

                                    <div className="p-4 bg-red-950/10 border border-red-900/30 rounded-lg space-y-3">
                                        <h5 className="text-xs font-medium text-red-300 flex items-center gap-2">
                                            <Trash2 className="w-3 h-3" />
                                            Bulk Delete by Source
                                        </h5>
                                        <div className="grid grid-cols-2 gap-2">
                                            {['tmdb', 'tmdb_tv', 'anilist', 'bgg', 'rawg', 'google_books', 'spotify_artist', 'itunes_podcast'].map((key) => (
                                                <Button
                                                    key={key}
                                                    variant="outline"
                                                    size="sm"
                                                    className="justify-start border-zinc-800 hover:bg-red-950/30 hover:text-red-400 hover:border-red-900/50 transition-colors h-8 text-xs"
                                                    onClick={() => {
                                                        setDeleteConfirm({ type: 'source', source: key })
                                                        setMaintenanceOpen(false)
                                                    }}
                                                >
                                                    {key.replace('_', ' ').replace(/\b\w/g, c => c.toUpperCase())}
                                                </Button>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </DialogContent>
                    </Dialog>

                    {/* Safe Delete Confirmation */}
                    <Dialog open={!!deleteConfirm} onOpenChange={() => { if (!actionLoading) setDeleteConfirm(null) }}>
                        <DialogContent className="bg-zinc-950 border-zinc-800">
                            <DialogHeader>
                                <DialogTitle className="text-red-500">
                                    {deleteConfirm?.type === 'source' ? 'CRITICAL WARNING' : 'Confirm Deletion'}
                                </DialogTitle>
                                <DialogDescription className="text-zinc-300">
                                    {deleteConfirm?.type === 'selected'
                                        ? `Are you sure you want to delete ${selectedIds.size} selected items?`
                                        : deleteConfirm?.type === 'single'
                                            ? 'Are you sure you want to delete this item? This action cannot be undone.'
                                            : <>
                                                You are about to delete <span className="font-bold text-white">ALL</span> items from <span className="font-bold text-white">{(deleteConfirm?.source || '').replace('_', ' ').replace(/\b\w/g, c => c.toUpperCase())}</span>.
                                                <br /><br />
                                                This action cannot be undone. All associated data will be lost forever.
                                            </>
                                    }
                                </DialogDescription>
                            </DialogHeader>

                            {deleteConfirm?.type === 'source' && (
                                <div className="py-2">
                                    <label className="text-xs text-zinc-500 mb-1 block">Type <strong>DELETE</strong> to confirm:</label>
                                    <Input
                                        value={confirmText}
                                        onChange={(e) => setConfirmText(e.target.value)}
                                        className="bg-red-950/20 border-red-900/50 text-red-200 placeholder:text-red-900/50 font-mono"
                                        placeholder="DELETE"
                                    />
                                </div>
                            )}

                            <DialogFooter>
                                <Button variant="ghost" onClick={() => setDeleteConfirm(null)} disabled={actionLoading}>Cancel</Button>
                                <Button
                                    variant="destructive"
                                    onClick={handleBulkDelete}
                                    disabled={actionLoading || (deleteConfirm?.type === 'source' && confirmText !== 'DELETE')}
                                >
                                    {actionLoading ? <RefreshCw className="w-4 h-4 animate-spin" /> : 'Confirm Delete'}
                                </Button>
                            </DialogFooter>
                        </DialogContent>
                    </Dialog>
                </div>

                {/* Report Dialog */}
                {reportItem && (
                    <ReportItemDialog
                        globalItemId={reportItem.id}
                        itemTitle={reportItem.title}
                        open={!!reportItem}
                        onOpenChange={(open) => !open && setReportItem(null)}
                    />
                )}

                {/* Item Detail View */}
                <ItemDetailView
                    item={viewItem as any}
                    isOpen={!!viewItem}
                    onClose={() => setViewItem(null)}
                    onItemChange={(item: any) => setViewItem(item)}
                    onEdit={(item: any) => {
                        setViewItem(null)
                        setEditItem(item)
                        setEditCategoryType(item.category_type)
                        setEditTitle(item.title)
                        setEditDescription(item.description || '')
                        setEditImage(item.image_url || '')
                        setEditTags(parseCachedTags(item.cached_tags).map((t: any) => t.id))
                        setEditMetadata(item.metadata ? JSON.stringify(item.metadata) : '')
                        setEditMode('edit')
                    }}
                    onDelete={(id) => {
                        setViewItem(null)
                        setDeleteConfirm({ type: 'single', id })
                    }}
                />
            </div>
        </div>
    )
}

'use client'

import { useState, useEffect } from 'react'
import { Card, CardContent, CardHeader } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription, SheetFooter } from '@/components/ui/sheet'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Separator } from '@/components/ui/separator'
import {
    Flag, CheckCircle2, XCircle, RefreshCw,
    Clock, User, FileText, ExternalLink, Loader2, Eye, Save
} from 'lucide-react'
import { toast } from 'sonner'
import Image from 'next/image'
import Link from 'next/link'
import { getReports, getReportStats, resolveReport, type Report, type ReportStats, type ReportStatus } from '@/lib/actions/reports'
import { createClient } from '@/lib/supabase/client'

// ============================================================================
// CONFIG
// ============================================================================

const STATUS_CONFIG: Record<ReportStatus, { label: string; color: string; icon: React.ElementType }> = {
    pending: { label: 'Pending', color: 'bg-amber-500/10 text-amber-500 border-amber-500/20', icon: Clock },
    resolved: { label: 'Resolved', color: 'bg-green-500/10 text-green-500 border-green-500/20', icon: CheckCircle2 },
    dismissed: { label: 'Dismissed', color: 'bg-zinc-500/10 text-zinc-400 border-zinc-500/20', icon: XCircle },
}

const REASON_LABELS: Record<string, string> = {
    inaccurate_data: 'Inaccurate Data',
    duplicate: 'Duplicate Entry',
    inappropriate: 'Inappropriate Content',
    other: 'Other Issue',
}

// ============================================================================
// TYPES
// ============================================================================

interface ItemData {
    id: string
    title: string
    description: string | null
    image_url: string | null
    category_type: string | null
    release_year: number | null
    // Media metadata
    genres: string[] | null
    director: string | null
    studio: string | null
    cast: string[] | null
    production_companies: string[] | null
    // Ratings
    vote_average: number | null
    content_rating: string | null
    runtime: number | null
    // TV/Anime
    number_of_seasons: number | null
    number_of_episodes: number | null
    episodes: number | null
    status: string | null
    // Gaming
    developers: string[] | null
    publishers: string[] | null
    platforms: string[] | Array<{ name?: string }> | null
    // Board Games
    designers: string[] | null
    min_players: number | null
    max_players: number | null
    complexity: number | null
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export default function AdminReportsPage() {
    const [reports, setReports] = useState<Report[]>([])
    const [stats, setStats] = useState<ReportStats>({ pending: 0, resolved: 0, dismissed: 0, total: 0 })
    const [loading, setLoading] = useState(true)
    const [activeTab, setActiveTab] = useState<ReportStatus | 'all'>('pending')

    // Review sheet state
    const [reviewReport, setReviewReport] = useState<Report | null>(null)
    const [itemData, setItemData] = useState<ItemData | null>(null)
    const [loadingItem, setLoadingItem] = useState(false)

    // Editable fields
    const [editTitle, setEditTitle] = useState('')
    const [editDescription, setEditDescription] = useState('')
    const [editImage, setEditImage] = useState('')

    // Action state
    const [isResolving, setIsResolving] = useState(false)

    const supabase = createClient()

    useEffect(() => {
        loadData()
    }, [activeTab])

    const loadData = async () => {
        setLoading(true)
        try {
            const [reportsData, statsData] = await Promise.all([
                getReports(activeTab === 'all' ? undefined : activeTab as ReportStatus),
                getReportStats(),
            ])
            setReports(reportsData.reports)
            setStats(statsData)
        } catch (error) {
            toast.error('Failed to load reports')
        } finally {
            setLoading(false)
        }
    }

    // Open the review sheet and fetch item data
    const openReview = async (report: Report) => {
        setReviewReport(report)
        setLoadingItem(true)

        try {
            const { data, error } = await (supabase.from('global_items') as any)
                .select(`
                    id, title, description, image_url, category_type, release_year,
                    genres, director, studio, cast, production_companies,
                    vote_average, content_rating, runtime,
                    number_of_seasons, number_of_episodes, episodes, status,
                    developers, publishers, platforms,
                    designers, min_players, max_players, complexity
                `)
                .eq('id', report.globalItemId)
                .single()

            if (error) throw error

            setItemData(data)
            setEditTitle(data?.title || '')
            setEditDescription(data?.description || '')
            setEditImage(data?.image_url || '')
        } catch (error) {
            console.error('Failed to load item:', error)
            toast.error('Failed to load item data')
        } finally {
            setLoadingItem(false)
        }
    }

    const closeReview = () => {
        setReviewReport(null)
        setItemData(null)
    }

    // Dismiss report without changes
    const handleDismiss = async () => {
        if (!reviewReport) return

        setIsResolving(true)
        try {
            const result = await resolveReport(reviewReport.id, 'dismissed', 'No changes made')
            if (result.success) {
                toast.success('Report dismissed')
                closeReview()
                loadData()
            } else {
                toast.error(result.error || 'Failed to dismiss report')
            }
        } catch (error) {
            toast.error('An unexpected error occurred')
        } finally {
            setIsResolving(false)
        }
    }

    // Update item and resolve report
    const handleUpdateAndResolve = async () => {
        if (!reviewReport || !itemData) return

        setIsResolving(true)
        try {
            // Check for changes and update item
            const updates: Record<string, string> = {}
            if (editTitle !== itemData.title) updates.title = editTitle
            if (editDescription !== (itemData.description || '')) updates.description = editDescription
            if (editImage !== (itemData.image_url || '')) updates.image_url = editImage

            const hasChanges = Object.keys(updates).length > 0

            if (hasChanges) {
                const { error } = await (supabase.from('global_items') as any)
                    .update(updates)
                    .eq('id', reviewReport.globalItemId)

                if (error) throw error
            }

            // Resolve the report
            const changedFields = Object.keys(updates)
            const notes = hasChanges
                ? `Item data updated: ${changedFields.join(', ')}`
                : 'Reviewed and confirmed data is correct'

            const result = await resolveReport(reviewReport.id, 'resolved', notes)

            if (result.success) {
                toast.success(hasChanges ? 'Item updated and report resolved' : 'Report resolved')
                closeReview()
                loadData()
            } else {
                toast.error(result.error || 'Failed to resolve report')
            }
        } catch (error) {
            console.error('Failed to update:', error)
            toast.error('Failed to update item')
        } finally {
            setIsResolving(false)
        }
    }

    const formatDate = (dateStr: string) => {
        return new Date(dateStr).toLocaleDateString('en-US', {
            month: 'short',
            day: 'numeric',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
        })
    }

    return (
        <div className="container mx-auto py-8 px-4">
            {/* Header */}
            <div className="mb-8">
                <h1 className="text-3xl font-bold text-white flex items-center gap-3">
                    <Flag className="w-8 h-8 text-amber-500" />
                    Report Management
                </h1>
                <p className="text-zinc-400 mt-2">Review and resolve user-submitted reports</p>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
                <Card className="bg-zinc-900/50 border-zinc-800">
                    <CardContent className="pt-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-zinc-500 uppercase tracking-wider">Total</p>
                                <p className="text-2xl font-bold text-white">{stats.total}</p>
                            </div>
                            <FileText className="w-8 h-8 text-zinc-600" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="bg-amber-950/20 border-amber-900/30">
                    <CardContent className="pt-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-amber-500/80 uppercase tracking-wider">Pending</p>
                                <p className="text-2xl font-bold text-amber-400">{stats.pending}</p>
                            </div>
                            <Clock className="w-8 h-8 text-amber-500/50" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="bg-green-950/20 border-green-900/30">
                    <CardContent className="pt-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-green-500/80 uppercase tracking-wider">Resolved</p>
                                <p className="text-2xl font-bold text-green-400">{stats.resolved}</p>
                            </div>
                            <CheckCircle2 className="w-8 h-8 text-green-500/50" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="bg-zinc-900/50 border-zinc-800">
                    <CardContent className="pt-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-zinc-500 uppercase tracking-wider">Dismissed</p>
                                <p className="text-2xl font-bold text-zinc-400">{stats.dismissed}</p>
                            </div>
                            <XCircle className="w-8 h-8 text-zinc-600" />
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* Reports List */}
            <Card className="bg-zinc-900/50 border-zinc-800">
                <CardHeader className="border-b border-zinc-800 pb-4">
                    <div className="flex items-center justify-between">
                        <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as any)}>
                            <TabsList className="bg-zinc-800/50">
                                <TabsTrigger value="pending" className="data-[state=active]:bg-amber-500/20 data-[state=active]:text-amber-400">
                                    Pending ({stats.pending})
                                </TabsTrigger>
                                <TabsTrigger value="resolved" className="data-[state=active]:bg-green-500/20 data-[state=active]:text-green-400">
                                    Resolved
                                </TabsTrigger>
                                <TabsTrigger value="dismissed" className="data-[state=active]:bg-zinc-700">
                                    Dismissed
                                </TabsTrigger>
                                <TabsTrigger value="all" className="data-[state=active]:bg-zinc-700">
                                    All
                                </TabsTrigger>
                            </TabsList>
                        </Tabs>

                        <Button variant="ghost" size="sm" onClick={loadData} disabled={loading} className="text-zinc-400">
                            <RefreshCw className={`w-4 h-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
                            Refresh
                        </Button>
                    </div>
                </CardHeader>
                <CardContent className="p-0">
                    {loading ? (
                        <div className="flex items-center justify-center py-12">
                            <RefreshCw className="w-6 h-6 animate-spin text-zinc-500" />
                        </div>
                    ) : reports.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-12 text-zinc-500">
                            <CheckCircle2 className="w-12 h-12 mb-4 opacity-30" />
                            <p>No reports found</p>
                        </div>
                    ) : (
                        <div className="divide-y divide-zinc-800/50">
                            {reports.map((report) => {
                                const statusConfig = STATUS_CONFIG[report.status]
                                const StatusIcon = statusConfig.icon

                                return (
                                    <div key={report.id} className="p-4 hover:bg-zinc-800/30 transition-colors">
                                        <div className="flex gap-4">
                                            {/* Item Image */}
                                            <div className="w-16 h-24 rounded bg-zinc-800 overflow-hidden shrink-0 relative">
                                                {report.itemImage ? (
                                                    <Image src={report.itemImage} alt="" fill className="object-cover" />
                                                ) : (
                                                    <div className="w-full h-full flex items-center justify-center">
                                                        <FileText className="w-6 h-6 text-zinc-700" />
                                                    </div>
                                                )}
                                            </div>

                                            {/* Report Details */}
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-start justify-between gap-4">
                                                    <div>
                                                        <h3 className="font-medium text-white truncate">
                                                            {report.itemTitle || 'Unknown Item'}
                                                        </h3>
                                                        <div className="flex items-center gap-2 mt-1">
                                                            <Badge className={`${statusConfig.color} border text-xs`}>
                                                                <StatusIcon className="w-3 h-3 mr-1" />
                                                                {statusConfig.label}
                                                            </Badge>
                                                            <Badge variant="outline" className="text-xs border-zinc-700 text-zinc-400">
                                                                {REASON_LABELS[report.reason] || report.reason}
                                                            </Badge>
                                                        </div>
                                                    </div>

                                                    {/* Single Review Button */}
                                                    <Button
                                                        size="sm"
                                                        variant="outline"
                                                        className="h-8 text-cyan-400 border-cyan-900/50 hover:bg-cyan-950/50 shrink-0"
                                                        onClick={() => openReview(report)}
                                                    >
                                                        <Eye className="w-3.5 h-3.5 mr-1" />
                                                        Review
                                                    </Button>
                                                </div>

                                                {/* Details */}
                                                {report.details && (
                                                    <p className="text-sm text-zinc-400 mt-2 line-clamp-2">
                                                        {report.details}
                                                    </p>
                                                )}

                                                {/* Meta */}
                                                <div className="flex items-center gap-4 mt-3 text-xs text-zinc-500">
                                                    <span className="flex items-center gap-1">
                                                        <User className="w-3 h-3" />
                                                        {report.reporterName || 'Anonymous'}
                                                    </span>
                                                    <span>{formatDate(report.createdAt)}</span>
                                                    <Link
                                                        href={`/admin/data-browser?id=${report.globalItemId}`}
                                                        className="text-cyan-500 hover:text-cyan-400 flex items-center gap-1"
                                                    >
                                                        <ExternalLink className="w-3 h-3" />
                                                        View Item
                                                    </Link>
                                                </div>

                                                {/* Resolution Notes */}
                                                {report.resolutionNotes && (
                                                    <div className="mt-2 p-2 bg-zinc-800/50 rounded text-xs text-zinc-400 border border-zinc-700/50">
                                                        <span className="text-zinc-500">Resolution notes:</span> {report.resolutionNotes}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                )
                            })}
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Review Sheet */}
            <Sheet open={!!reviewReport} onOpenChange={(open: boolean) => !open && closeReview()}>
                <SheetContent className="w-full sm:max-w-xl bg-zinc-950 border-zinc-800 flex flex-col p-0">
                    <SheetHeader className="px-6 pt-6 pb-4 border-b border-zinc-800 shrink-0">
                        <div className="flex items-center gap-2">
                            <Badge className="bg-amber-500/10 text-amber-500 border-amber-500/20 border">
                                {REASON_LABELS[reviewReport?.reason || ''] || reviewReport?.reason}
                            </Badge>
                        </div>
                        <SheetTitle className="text-zinc-100 text-lg">
                            Review Report
                        </SheetTitle>
                        <SheetDescription className="text-zinc-400">
                            Reported by <span className="text-zinc-300">{reviewReport?.reporterName || 'Anonymous'}</span>
                            {reviewReport?.details && (
                                <span className="block mt-2 text-zinc-500 italic">"{reviewReport.details}"</span>
                            )}
                        </SheetDescription>
                    </SheetHeader>

                    <ScrollArea className="flex-1 px-6">
                        <div className="py-6 space-y-6">
                            {loadingItem ? (
                                <div className="flex items-center justify-center py-12">
                                    <Loader2 className="w-6 h-6 animate-spin text-zinc-500" />
                                </div>
                            ) : itemData ? (
                                <>
                                    {/* Section Header */}
                                    <h3 className="text-sm font-medium text-zinc-300">Item Data</h3>

                                    {/* Item Image */}
                                    <div className="space-y-2">
                                        <label className="text-xs text-zinc-500 uppercase tracking-wider">Image</label>
                                        <div className="flex gap-4">
                                            <div className="w-24 h-36 rounded-lg bg-zinc-800 overflow-hidden shrink-0 relative border border-zinc-700">
                                                {editImage ? (
                                                    <Image
                                                        src={editImage}
                                                        alt=""
                                                        fill
                                                        className="object-cover"
                                                    />
                                                ) : (
                                                    <div className="w-full h-full flex items-center justify-center">
                                                        <FileText className="w-8 h-8 text-zinc-700" />
                                                    </div>
                                                )}
                                            </div>
                                            <div className="flex-1">
                                                <Input
                                                    value={editImage}
                                                    onChange={(e) => setEditImage(e.target.value)}
                                                    placeholder="Image URL..."
                                                    className="bg-zinc-900 border-zinc-800 text-zinc-200"
                                                    disabled={reviewReport?.status !== 'pending'}
                                                />
                                                <p className="text-xs text-zinc-600 mt-1">Enter a new image URL</p>
                                            </div>
                                        </div>
                                    </div>

                                    <Separator className="bg-zinc-800" />

                                    {/* Title */}
                                    <div className="space-y-2">
                                        <label className="text-xs text-zinc-500 uppercase tracking-wider">Title</label>
                                        <Input
                                            value={editTitle}
                                            onChange={(e) => setEditTitle(e.target.value)}
                                            className="bg-zinc-900 border-zinc-800 text-zinc-200"
                                            disabled={reviewReport?.status !== 'pending'}
                                        />
                                    </div>

                                    {/* Description */}
                                    <div className="space-y-2">
                                        <label className="text-xs text-zinc-500 uppercase tracking-wider">Description</label>
                                        <Textarea
                                            value={editDescription}
                                            onChange={(e) => setEditDescription(e.target.value)}
                                            rows={8}
                                            className="bg-zinc-900 border-zinc-800 text-zinc-200 resize-none max-h-[250px] overflow-y-auto whitespace-pre-wrap"
                                            disabled={reviewReport?.status !== 'pending'}
                                        />
                                        <p className="text-xs text-zinc-600">
                                            Tip: Use blank lines to separate paragraphs
                                        </p>
                                    </div>

                                    <Separator className="bg-zinc-800" />

                                    {/* Metadata Section (Read-Only) */}
                                    <div className="space-y-4">
                                        <h3 className="text-sm font-medium text-zinc-300">Item Metadata</h3>

                                        <div className="grid grid-cols-2 gap-3 text-sm">
                                            {/* Category & Year */}
                                            {itemData.category_type && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Category</span>
                                                    <p className="text-zinc-300">{itemData.category_type.replace(/_/g, ' ')}</p>
                                                </div>
                                            )}
                                            {itemData.release_year && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Year</span>
                                                    <p className="text-zinc-300">{itemData.release_year}</p>
                                                </div>
                                            )}

                                            {/* Rating & Runtime */}
                                            {itemData.vote_average != null && itemData.vote_average > 0 && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Rating</span>
                                                    <p className="text-zinc-300">{itemData.vote_average.toFixed(1)}/10</p>
                                                </div>
                                            )}
                                            {itemData.runtime && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Runtime</span>
                                                    <p className="text-zinc-300">{itemData.runtime} min</p>
                                                </div>
                                            )}

                                            {/* TV/Anime Episodes */}
                                            {(itemData.number_of_episodes || itemData.episodes) && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Episodes</span>
                                                    <p className="text-zinc-300">{itemData.number_of_episodes || itemData.episodes}</p>
                                                </div>
                                            )}
                                            {itemData.number_of_seasons && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Seasons</span>
                                                    <p className="text-zinc-300">{itemData.number_of_seasons}</p>
                                                </div>
                                            )}

                                            {/* Board Game Players */}
                                            {(itemData.min_players || itemData.max_players) && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Players</span>
                                                    <p className="text-zinc-300">
                                                        {itemData.min_players === itemData.max_players
                                                            ? itemData.min_players
                                                            : `${itemData.min_players || '?'}-${itemData.max_players || '?'}`}
                                                    </p>
                                                </div>
                                            )}
                                            {itemData.complexity != null && itemData.complexity > 0 && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Complexity</span>
                                                    <p className="text-zinc-300">{itemData.complexity.toFixed(2)}/5</p>
                                                </div>
                                            )}
                                        </div>

                                        {/* Full Width Fields */}
                                        <div className="space-y-3">
                                            {/* Genres */}
                                            {itemData.genres && itemData.genres.length > 0 && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Genres</span>
                                                    <div className="flex flex-wrap gap-1">
                                                        {itemData.genres.map((g, i) => (
                                                            <Badge key={i} variant="outline" className="text-xs border-zinc-700 text-zinc-400">
                                                                {g}
                                                            </Badge>
                                                        ))}
                                                    </div>
                                                </div>
                                            )}

                                            {/* Director/Studio */}
                                            {itemData.director && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Director</span>
                                                    <p className="text-zinc-300 text-sm">{itemData.director}</p>
                                                </div>
                                            )}
                                            {itemData.studio && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Studio</span>
                                                    <p className="text-zinc-300 text-sm">{itemData.studio}</p>
                                                </div>
                                            )}

                                            {/* Developers/Publishers */}
                                            {itemData.developers && itemData.developers.length > 0 && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Developers</span>
                                                    <p className="text-zinc-300 text-sm">{itemData.developers.join(', ')}</p>
                                                </div>
                                            )}
                                            {itemData.publishers && itemData.publishers.length > 0 && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Publishers</span>
                                                    <p className="text-zinc-300 text-sm">{itemData.publishers.join(', ')}</p>
                                                </div>
                                            )}

                                            {/* Designers (Board Games) */}
                                            {itemData.designers && itemData.designers.length > 0 && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Designers</span>
                                                    <p className="text-zinc-300 text-sm">{itemData.designers.join(', ')}</p>
                                                </div>
                                            )}

                                            {/* Platforms */}
                                            {itemData.platforms && itemData.platforms.length > 0 && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Platforms</span>
                                                    <p className="text-zinc-300 text-sm">
                                                        {itemData.platforms.map(p => typeof p === 'string' ? p : p.name).filter(Boolean).join(', ')}
                                                    </p>
                                                </div>
                                            )}

                                            {/* Cast (truncated) */}
                                            {itemData.cast && itemData.cast.length > 0 && (
                                                <div className="space-y-1">
                                                    <span className="text-xs text-zinc-500 uppercase">Cast</span>
                                                    <p className="text-zinc-300 text-sm line-clamp-2">
                                                        {itemData.cast.slice(0, 6).join(', ')}
                                                        {itemData.cast.length > 6 && ` +${itemData.cast.length - 6} more`}
                                                    </p>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </>
                            ) : (
                                <div className="flex flex-col items-center justify-center py-12 text-zinc-500">
                                    <FileText className="w-12 h-12 mb-4 opacity-30" />
                                    <p>Item not found</p>
                                </div>
                            )}
                        </div>
                    </ScrollArea>

                    {/* Footer Actions */}
                    {reviewReport?.status === 'pending' && (
                        <SheetFooter className="px-6 pt-4 pb-6 mt-auto border-t border-zinc-800 shrink-0 gap-2 sm:gap-2">
                            <Button
                                variant="outline"
                                onClick={handleDismiss}
                                disabled={isResolving}
                                className="flex-1 border-zinc-700 text-zinc-400 hover:bg-zinc-800"
                            >
                                {isResolving ? (
                                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                ) : (
                                    <XCircle className="w-4 h-4 mr-2" />
                                )}
                                Dismiss Report
                            </Button>
                            <Button
                                onClick={handleUpdateAndResolve}
                                disabled={isResolving || !itemData}
                                className="flex-1 bg-green-600 hover:bg-green-500 text-white"
                            >
                                {isResolving ? (
                                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                ) : (
                                    <Save className="w-4 h-4 mr-2" />
                                )}
                                Update & Resolve
                            </Button>
                        </SheetFooter>
                    )}
                </SheetContent>
            </Sheet>
        </div>
    )
}

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { createServiceRoleClient } from '@/lib/supabase/service-role'
import { generateStructuredDescription, combineDescription, buildEmbeddingText } from '@/lib/ai/structured-description'
import { generateEmbedding } from '@/lib/harvesters/shared'

const OMDB_API_KEY = process.env.OMDB_API_KEY
const OMDB_BASE_URL = 'https://www.omdbapi.com'
const TMDB_API_KEY = process.env.TMDB_API_KEY || process.env.NEXT_PUBLIC_TMDB_API_KEY

/**
 * Category-specific provider mapping
 */
const PROVIDER_MAP: Record<string, { name: string; searchFn: string }> = {
    MOVIE: { name: 'TMDB + OMDB', searchFn: 'searchTMDB' },
    TV: { name: 'TMDB + OMDB', searchFn: 'searchTMDB' },
    TV_SHOW: { name: 'TMDB + OMDB', searchFn: 'searchTMDB' },
    ANIME: { name: 'AniList', searchFn: 'searchAniList' },
    VIDEO_GAME: { name: 'IGDB', searchFn: 'searchIGDB' },
    BOARD_GAME: { name: 'BGG', searchFn: 'searchBGG' },
    MUSIC_ALBUM: { name: 'Spotify', searchFn: 'searchSpotify' },
    MUSIC_TRACK: { name: 'Spotify', searchFn: 'searchSpotify' },
    MUSIC_ARTIST: { name: 'Spotify', searchFn: 'searchSpotify' },
    BOOK: { name: 'Google Books', searchFn: 'searchGoogleBooks' },
    PODCAST: { name: 'Podcast Index', searchFn: 'searchPodcasts' },
}

/**
 * Fetch OMDB data by IMDB ID
 */
async function fetchOmdbData(imdbId: string) {
    if (!OMDB_API_KEY || !imdbId) return null

    const url = `${OMDB_BASE_URL}/?apikey=${OMDB_API_KEY}&i=${imdbId}&tomatoes=true`
    try {
        const res = await fetch(url)
        if (!res.ok) return null

        const data = await res.json()
        if (data.Response === 'False') return null

        // Extract Rotten Tomatoes safely
        let rtScore: number | null = null
        const rtSource = data.Ratings?.find((r: any) => r.Source === 'Rotten Tomatoes')
        if (rtSource && rtSource.Value) {
            rtScore = parseInt(rtSource.Value.replace('%', ''), 10)
        }

        return {
            imdb_rating: data.imdbRating && data.imdbRating !== 'N/A' ? parseFloat(data.imdbRating) : null,
            imdb_votes: data.imdbVotes ? parseInt(data.imdbVotes.replace(/,/g, ''), 10) : null,
            rotten_tomatoes_rating: rtScore,
            metacritic_rating: data.Metascore && data.Metascore !== 'N/A' ? parseInt(data.Metascore, 10) : null,
            awards: data.Awards && data.Awards !== 'N/A' ? data.Awards : null,
            rated: data.Rated && data.Rated !== 'N/A' ? data.Rated : null,
            writer: data.Writer && data.Writer !== 'N/A' ? data.Writer : null,
            box_office: data.BoxOffice && data.BoxOffice !== 'N/A' ? data.BoxOffice : null,
        }
    } catch (e) {
        return null
    }
}

/**
 * Fetch OMDB data by title and year (fallback)
 */
async function fetchOmdbDataByTitle(title: string, year: number) {
    if (!OMDB_API_KEY) return null
    const url = `${OMDB_BASE_URL}/?apikey=${OMDB_API_KEY}&t=${encodeURIComponent(title)}&y=${year}&tomatoes=true`
    try {
        const res = await fetch(url)
        if (!res.ok) return null
        const data = await res.json()
        if (data.Response === 'False') return null

        let rtScore: number | null = null
        const rtSource = data.Ratings?.find((r: any) => r.Source === 'Rotten Tomatoes')
        if (rtSource && rtSource.Value) {
            rtScore = parseInt(rtSource.Value.replace('%', ''), 10)
        }

        return {
            imdb_rating: data.imdbRating && data.imdbRating !== 'N/A' ? parseFloat(data.imdbRating) : null,
            imdb_votes: data.imdbVotes ? parseInt(data.imdbVotes.replace(/,/g, ''), 10) : null,
            rotten_tomatoes_rating: rtScore,
            metacritic_rating: data.Metascore && data.Metascore !== 'N/A' ? parseInt(data.Metascore, 10) : null,
            awards: data.Awards && data.Awards !== 'N/A' ? data.Awards : null,
            rated: data.Rated && data.Rated !== 'N/A' ? data.Rated : null,
            writer: data.Writer && data.Writer !== 'N/A' ? data.Writer : null,
            box_office: data.BoxOffice && data.BoxOffice !== 'N/A' ? data.BoxOffice : null,
        }
    } catch (e) {
        return null
    }
}

/**
 * API endpoint to enrich item metadata from category-specific providers
 * Also regenerates description and embedding
 */
/**
 * Fetch TMDB details including credits and external IDs
 */
async function fetchTmdbDetails(id: string | number, type: string) {
    if (!TMDB_API_KEY) return null
    const endpoint = type === 'MOVIE' ? 'movie' : 'tv'
    try {
        const url = `https://api.themoviedb.org/3/${endpoint}/${id}?api_key=${TMDB_API_KEY}&append_to_response=credits,keywords,external_ids`
        const res = await fetch(url)
        if (!res.ok) return null
        return await res.json()
    } catch (e) {
        console.error('TMDB Fetch Error:', e)
        return null
    }
}

export async function POST(request: NextRequest) {
    try {
        const { itemId, title, type, force = false, descriptionOnly = false } = await request.json()

        if (!itemId || !title || !type) {
            return NextResponse.json(
                { error: 'Missing required fields: itemId, title, type' },
                { status: 400 }
            )
        }

        const supabase = await createClient()
        const serviceSupabase = createServiceRoleClient()

        // Get current item
        const { data: existingItem, error: fetchError } = await (supabase.from('global_items') as any)
            .select('*')
            .eq('id', itemId)
            .single()

        if (fetchError || !existingItem) {
            return NextResponse.json(
                { error: 'Item not found' },
                { status: 404 }
            )
        }

        const provider = PROVIDER_MAP[type] || { name: 'Unknown', searchFn: null }
        let enrichedData: Record<string, any> = {}
        let providerResult: any = null

        // Skip metadata enrichment if descriptionOnly mode
        if (!descriptionOnly) {
            // Import and call the appropriate search function based on category
            try {
                const { searchMediaAction } = await import('@/lib/actions/media')
                const searchResult = await searchMediaAction(title, type, null, undefined)

                if (searchResult.success && searchResult.data && searchResult.data.length > 0) {
                    // Find best match (usually first result)
                    providerResult = searchResult.data[0]

                    // Fetch full TMDB details for Movies/TV to get cast, crew, networks, etc.
                    if (['MOVIE', 'TV', 'TV_SHOW'].includes(type) && providerResult.id) {
                        const details = await fetchTmdbDetails(providerResult.id, type)
                        if (details) {
                            providerResult = { ...providerResult, ...details }
                        }
                    }

                    // Map provider-specific fields to our schema (force=true overwrites existing)
                    enrichedData = mapProviderData(type, providerResult, existingItem, force)
                }
            } catch (searchError) {
                console.warn(`Provider search failed for ${type}:`, searchError)
                // Continue with description regeneration even if provider search fails
            }
        }

        // For Movies and TV: Also fetch OMDB data for ratings (skip if descriptionOnly)
        let omdbStatus: 'success' | 'not_found' | 'skipped' | 'error' = 'skipped'
        const omdbRatingsFound: string[] = []

        if (!descriptionOnly && ['MOVIE', 'TV', 'TV_SHOW'].includes(type)) {
            let omdbData = null
            const imdbId = existingItem.external_ids?.imdb || providerResult?.imdb_id

            console.log(`[OMDB] Fetching ratings for "${title}" (${type})`)

            try {
                if (imdbId) {
                    console.log(`[OMDB] Trying IMDB ID: ${imdbId}`)
                    omdbData = await fetchOmdbData(imdbId)
                }

                if (!omdbData) {
                    console.log(`[OMDB] Trying title search: "${title}" (${existingItem.release_year})`)
                    omdbData = await fetchOmdbDataByTitle(title, existingItem.release_year)
                }

                if (omdbData) {
                    omdbStatus = 'success'
                    console.log(`[OMDB] Γ£à Data found:`)

                    // Map OMDB data (force=true: always update, force=false: only update if missing)
                    if (omdbData.imdb_rating && (force || !existingItem.imdb_rating)) {
                        enrichedData.imdb_rating = omdbData.imdb_rating
                        omdbRatingsFound.push(`IMDB: ${omdbData.imdb_rating}`)
                    }
                    if (omdbData.imdb_votes && (force || !existingItem.imdb_votes)) {
                        enrichedData.imdb_votes = omdbData.imdb_votes
                    }
                    if (omdbData.rotten_tomatoes_rating && (force || !existingItem.rotten_tomatoes_rating)) {
                        enrichedData.rotten_tomatoes_rating = omdbData.rotten_tomatoes_rating
                        omdbRatingsFound.push(`RT: ${omdbData.rotten_tomatoes_rating}%`)
                    }
                    if (omdbData.metacritic_rating && (force || !existingItem.metacritic_rating)) {
                        enrichedData.metacritic_rating = omdbData.metacritic_rating
                        omdbRatingsFound.push(`MC: ${omdbData.metacritic_rating}`)
                    }
                    if (omdbData.awards && (force || !existingItem.awards_text)) {
                        enrichedData.awards_text = omdbData.awards
                        omdbRatingsFound.push('Awards')
                    }
                    if (omdbData.rated && (force || !existingItem.content_rating)) {
                        enrichedData.content_rating = omdbData.rated
                    }
                    if (omdbData.writer && (force || !existingItem.writer)) {
                        enrichedData.writer = omdbData.writer
                    }
                    if (omdbData.box_office && (force || !existingItem.box_office)) {
                        enrichedData.box_office = omdbData.box_office
                    }

                    console.log(`[OMDB]    Ratings: ${omdbRatingsFound.length > 0 ? omdbRatingsFound.join(' | ') : 'None new (already populated)'}${force ? ' [FORCED]' : ''}`)
                } else {
                    omdbStatus = 'not_found'
                    console.log(`[OMDB] ΓÜá∩╕Å No data found for "${title}"`)
                }
            } catch (omdbError: any) {
                omdbStatus = 'error'
                console.error(`[OMDB] Γ¥î Error fetching data:`, omdbError.message)
            }
        }

        // Generate 4-part structured description with any new metadata
        const description_parts = await generateStructuredDescription(serviceSupabase, {
            title,
            originalDescription: existingItem.description || '',
            type,
            metadata: { ...existingItem.metadata, ...enrichedData.metadata }
        })

        const description = combineDescription(description_parts)

        // Build rich embedding text
        const embeddingText = buildEmbeddingText({
            ...existingItem,
            ...enrichedData,
            description,
            description_parts
        })

        // Generate new embedding
        const embedding = await generateEmbedding(embeddingText)

        // Prepare update payload
        const updateData: any = {
            description,
            description_parts,
            ...enrichedData
        }

        if (embedding) {
            updateData.embedding = embedding
        }

        // Update the item
        const { error: updateError } = await (supabase.from('global_items') as any)
            .update(updateData)
            .eq('id', itemId)

        if (updateError) {
            return NextResponse.json(
                { error: updateError.message },
                { status: 500 }
            )
        }

        console.log(`[Enrich] Γ£à Updated "${title}" with ${Object.keys(enrichedData).length} fields`)

        return NextResponse.json({
            success: true,
            provider: provider.name,
            enriched: Object.keys(enrichedData).length > 0,
            fieldsUpdated: Object.keys(enrichedData),
            enrichedData, // Include actual values so client can update local state
            omdbStatus,
            omdbRatings: omdbRatingsFound,
            description,
            description_parts
        })

    } catch (error: any) {
        console.error('Enrich metadata error:', error)
        return NextResponse.json(
            { error: error.message || 'Failed to enrich metadata' },
            { status: 500 }
        )
    }
}

/**
 * Map provider-specific data to our unified schema
 * @param force If true, overwrite existing values; if false, only update empty/null fields
 */
function mapProviderData(type: string, providerData: any, existingItem: any, force: boolean = false): Record<string, any> {
    const enriched: Record<string, any> = {}

    // Update field based on force flag
    const updateField = (field: string, value: any) => {
        if (value !== undefined && value !== null && value !== '') {
            // If force mode, always update; otherwise only update if missing
            if (force || existingItem[field] === null || existingItem[field] === undefined || existingItem[field] === '') {
                enriched[field] = value
            }
        }
    }

    // Common fields
    updateField('image_url', providerData.imageUrl || providerData.poster_path)
    updateField('release_year', providerData.year || providerData.releaseYear)

    // Category-specific mappings
    const metadataUpdates: Record<string, any> = {}

    switch (type) {
        case 'MOVIE':
        case 'TV':
        case 'TV_SHOW':
            updateField('backdrop_path', providerData.backdrop_path)
            updateField('vote_average', providerData.vote_average)
            updateField('genres', providerData.genres)
            updateField('runtime', providerData.runtime || (providerData.episode_run_time && providerData.episode_run_time[0]))
            updateField('director', providerData.director)
            updateField('tagline', providerData.tagline)

            // Extended Metadata
            if (providerData.credits?.cast) {
                updateField('cast', providerData.credits.cast.slice(0, 20).map((c: any) => c.name))
                // Also store cast objects in metadata for character mapping
                metadataUpdates.credits = { cast: providerData.credits.cast.slice(0, 20) }
            }
            if (providerData.networks) metadataUpdates.networks = providerData.networks.map((n: any) => n.name)
            if (providerData.created_by) metadataUpdates.created_by = providerData.created_by.map((c: any) => c.name)
            if (providerData.status) enriched.status = providerData.status
            if (providerData.number_of_seasons) enriched.number_of_seasons = providerData.number_of_seasons
            if (providerData.number_of_episodes) enriched.number_of_episodes = providerData.number_of_episodes
            if (providerData.first_air_date) metadataUpdates.first_air_date = providerData.first_air_date
            if (providerData.last_air_date) metadataUpdates.last_air_date = providerData.last_air_date
            break

        case 'ANIME':
            updateField('romaji_title', providerData.romaji_title)
            updateField('anilist_score', providerData.score)
            updateField('status', providerData.status)
            updateField('genres', providerData.genres)
            updateField('studios', providerData.studios)
            break

        case 'VIDEO_GAME':
            updateField('platforms', providerData.platforms)
            updateField('developers', providerData.developers)
            updateField('publishers', providerData.publishers)
            updateField('genres', providerData.genres)
            updateField('vote_average', providerData.rating)
            break

        case 'BOARD_GAME':
            updateField('designers', providerData.designers)
            updateField('publishers', providerData.publishers)
            updateField('min_players', providerData.minPlayers)
            updateField('max_players', providerData.maxPlayers)
            updateField('complexity', providerData.complexity)
            updateField('vote_average', providerData.rating)
            break

        case 'MUSIC_ALBUM':
        case 'MUSIC_TRACK':
        case 'MUSIC_ARTIST':
            updateField('artist_names', providerData.artists || providerData.artistNames)
            updateField('label', providerData.label)
            updateField('popularity', providerData.popularity)
            updateField('spotify_url', providerData.spotify_url || providerData.external_urls?.spotify)
            updateField('preview_url', providerData.preview_url)
            break

        case 'BOOK':
            updateField('author', providerData.authors?.[0])
            updateField('publisher', providerData.publisher)
            updateField('isbn', providerData.isbn)
            updateField('page_count', providerData.pageCount)
            break
    }

    // Merge metadata
    enriched.metadata = { ...(enriched.metadata as object), ...metadataUpdates }

    // Store external ID in metadata (force updates existing, otherwise only if missing)
    if (providerData.id && (force || !existingItem.external_ids?.[type.toLowerCase()])) {
        enriched.external_ids = {
            ...existingItem.external_ids,
            [type.toLowerCase()]: providerData.id
        }
    }

    return enriched
}

'use client';

import { useState } from 'react';
import { toast } from 'sonner';
import { Card, CardDescription, CardHeader, CardTitle, CardContent, CardFooter } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Loader2, Zap, Database, Mail, Brain, RefreshCw, CheckCircle2, AlertTriangle, AlertCircle } from 'lucide-react';
import { updateSystemConfig, getSystemConfig, testLLMConnectionAction, testServiceConnection } from '@/lib/actions/admin';
import { useEffect } from 'react';

interface AdminSystemConfigProps {
    settings: Record<string, string>;
}

export default function AdminSystemConfig({ settings }: AdminSystemConfigProps) {
    const [isLoading, setIsLoading] = useState(false);

    // LLM State
    const [llmProvider, setLlmProvider] = useState(settings?.['llm_provider'] || 'openai');
    const [llmApiKey, setLlmApiKey] = useState(settings?.['llm_api_key'] || '');
    const [llmModel, setLlmModel] = useState(settings?.['llm_model'] || '');
    const [systemPrompt, setSystemPrompt] = useState(settings?.['system_prompt'] || `You are The Curator, an elite cultural critic and algorithm. Your goal is to analyze user taste with surgical precision and sophisticated wit.

**OPERATIONAL RULES:**
1. **Scope:** You analyze Movies, TV, Games, Books, Music, and Podcasts.
2. **Tone:** Authoritative, discerning, and slightly snarky. You are not a cheerleader; you are a critic.
3. **Constraints:** - Never recommend items the user already has (you will receive an exclusion list).
   - Use bolding (markdown **text**) inside strings to highlight key genres/tropes.
   - For "Likely Misses," be critical and explain specifically why the user would dislike it based on their profile.`);

    // Dynamic Model Fetching & Testing
    const [availableModels, setAvailableModels] = useState<string[]>([]);
    const [isLoadingModels, setIsLoadingModels] = useState(false);
    const [isTestLoading, setIsTestLoading] = useState(false);
    const [testResult, setTestResult] = useState<{ success: boolean; message: string } | null>(null);

    // Media API Keys
    const [tmdbApiKey, setTmdbApiKey] = useState(settings?.['tmdb_api_key'] || '');
    const [rawgApiKey, setRawgApiKey] = useState(settings?.['rawg_api_key'] || '');
    const [googleBooksApiKey, setGoogleBooksApiKey] = useState(settings?.['google_books_api_key'] || '');
    const [spotifyClientId, setSpotifyClientId] = useState(settings?.['spotify_client_id'] || '');
    const [spotifyClientSecret, setSpotifyClientSecret] = useState(settings?.['spotify_client_secret'] || '');
    const [comicVineApiKey, setComicVineApiKey] = useState(settings?.['comicvine_api_key'] || '');
    const [bggApiKey, setBggApiKey] = useState(settings?.['bgg_api_key'] || '');
    const [metronUsername, setMetronUsername] = useState(settings?.['metron_username'] || '');
    const [metronPassword, setMetronPassword] = useState(settings?.['metron_password'] || '');
    const [omdbApiKey, setOmdbApiKey] = useState(settings?.['omdb_api_key'] || '');

    // Voyage AI (Embeddings)
    const [voyageApiKey, setVoyageApiKey] = useState(settings?.['voyage_api_key'] || '');
    const [voyageModel, setVoyageModel] = useState(settings?.['voyage_model'] || 'voyage-3');

    // Media API Endpoints (Custom URLs)
    // Twitch / IGDB
    const [twitchClientId, setTwitchClientId] = useState(settings?.['twitch_client_id'] || '');
    const [twitchClientSecret, setTwitchClientSecret] = useState(settings?.['twitch_client_secret'] || '');

    // Email State
    const [resendKey, setResendKey] = useState(settings?.['resend_api_key'] || '');
    const [fromEmail, setFromEmail] = useState(settings?.['resend_from_email'] || '');
    const [appUrl, setAppUrl] = useState(settings?.['public_app_url'] || 'http://localhost:3000');
    const [testEmailRecipient, setTestEmailRecipient] = useState('');
    const [isSendingTestEmail, setIsSendingTestEmail] = useState(false);

    // Feature Flags
    const [enableAiCritic, setEnableAiCritic] = useState(settings['feature_ai_critic'] === 'true');
    const [enableSmartSort, setEnableSmartSort] = useState(settings['feature_smart_sort'] === 'true');
    const [enableRecommendations, setEnableRecommendations] = useState(settings['feature_recommendations'] === 'true');
    const [enableChallenges, setEnableChallenges] = useState(settings['feature_challenges'] === 'true');

    // SteamGridDB
    const [steamGridApiKey, setSteamGridApiKey] = useState(settings['STEAMGRIDDB_API_KEY'] || '');

    // Connection Status for Services
    const [serviceStatuses, setServiceStatuses] = useState<Record<string, { status: 'idle' | 'loading' | 'success' | 'error', message?: string }>>({
        tmdb: { status: 'idle' },
        googlebooks: { status: 'idle' },
        spotify: { status: 'idle' },
        resend: { status: 'idle' },
        comicvine: { status: 'idle' },
        bgg: { status: 'idle' },
        metron: { status: 'idle' },
        steamgrid: { status: 'idle' },
        omdb: { status: 'idle' },
        twitch: { status: 'idle' }
    });



    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        setIsLoading(true);
        try {
            const [config] = await Promise.all([
                getSystemConfig()
            ]);

            // Populate states
            if (config['llm_provider']) setLlmProvider(config['llm_provider']);
            if (config['llm_api_key']) setLlmApiKey(config['llm_api_key']);
            if (config['llm_model']) setLlmModel(config['llm_model']);
            if (config['system_prompt']) setSystemPrompt(config['system_prompt']);

            if (config['tmdb_api_key']) setTmdbApiKey(config['tmdb_api_key']);
            if (config['rawg_api_key']) setRawgApiKey(config['rawg_api_key']);
            if (config['twitch_client_id']) setTwitchClientId(config['twitch_client_id']);
            if (config['twitch_client_secret']) setTwitchClientSecret(config['twitch_client_secret']);
            if (config['google_books_api_key']) setGoogleBooksApiKey(config['google_books_api_key']);
            if (config['spotify_client_id']) setSpotifyClientId(config['spotify_client_id']);
            if (config['spotify_client_secret']) setSpotifyClientSecret(config['spotify_client_secret']);
            if (config['comicvine_api_key']) setComicVineApiKey(config['comicvine_api_key']);
            if (config['bgg_api_key']) setBggApiKey(config['bgg_api_key']);
            if (config['metron_username']) setMetronUsername(config['metron_username']);
            if (config['metron_password']) setMetronPassword(config['metron_password']);
            if (config['omdb_api_key']) setOmdbApiKey(config['omdb_api_key']);

            if (config['resend_api_key']) setResendKey(config['resend_api_key']);
            if (config['resend_from_email']) setFromEmail(config['resend_from_email']);
            if (config['public_app_url']) setAppUrl(config['public_app_url']);


        } catch (e) {
            console.error("Failed to load settings:", e);
            toast.error("Failed to load existing settings.");
        } finally {
            setIsLoading(false);
        }
    };



    const handleTestLLM = async () => {
        setIsTestLoading(true);
        setTestResult(null);
        try {
            const result = await testLLMConnectionAction({
                provider: llmProvider,
                apiKey: llmApiKey,
                model: llmModel
            });
            if (result.success) {
                setTestResult({ success: true, message: result.message || "Connection Verified" });
                toast.success(result.message || "Connection Verified");
            } else {
                setTestResult({ success: false, message: result.error || "Connection Failed" });
                toast.error(result.error || "Connection Failed");
            }
        } catch (e: any) {
            setTestResult({ success: false, message: e.message || "Test Error" });
            toast.error("An error occurred during verification.");
        } finally {
            setIsTestLoading(false);
        }
    };

    const handleTestService = async (service: 'tmdb' | 'twitch' | 'googlebooks' | 'spotify' | 'resend' | 'comicvine' | 'bgg' | 'metron' | 'omdb' | 'steamgrid', apiKey: string, clientSecret?: string) => {
        setServiceStatuses(prev => ({ ...prev, [service]: { status: 'loading' } }));
        try {
            const result = await testServiceConnection({ service, apiKey, clientSecret });
            if (result.success) {
                setServiceStatuses(prev => ({ ...prev, [service]: { status: 'success', message: result.message } }));
                toast.success(result.message || `${service} Verified`);
            } else {
                setServiceStatuses(prev => ({ ...prev, [service]: { status: 'error', message: result.error } }));
                toast.error(result.error || `${service} Verification Failed`);
            }
        } catch (e: any) {
            setServiceStatuses(prev => ({ ...prev, [service]: { status: 'error', message: e.message } }));
            toast.error(`Error testing ${service}`);
        }
    };

    const handleSendTestEmail = async () => {
        if (!testEmailRecipient || !resendKey) {
            toast.error('Please enter a valid recipient email and Resend API key');
            return;
        }
        setIsSendingTestEmail(true);
        try {
            const res = await fetch('/api/admin/test-email', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ recipient: testEmailRecipient, apiKey: resendKey })
            });
            const data = await res.json();
            if (data.success) {
                toast.success(`Test email sent to ${testEmailRecipient}`);
                setTestEmailRecipient('');
            } else {
                toast.error(data.error || 'Failed to send test email');
            }
        } catch (e: any) {
            toast.error(`Error: ${e.message}`);
        } finally {
            setIsSendingTestEmail(false);
        }
    };

    const fetchModels = async () => {
        setIsLoadingModels(true);
        setAvailableModels([]);
        try {
            const res = await fetch('/api/admin/llm/models', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ provider: llmProvider, apiKey: llmApiKey })
            });
            if (!res.ok) throw new Error('Failed to fetch models');
            const data = await res.json();
            setAvailableModels(data.models || []);
            if (data.models?.length > 0 && !llmModel) {
                setLlmModel(data.models[0]);
            }
            toast.success(`Found ${data.models?.length || 0} models`);
        } catch {
            toast.error('Failed to fetch models from provider');
        } finally {
            setIsLoadingModels(false);
        }
    };

    const handleSaveConfig = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        try {
            await updateSystemConfig({
                llmProvider,
                llmApiKey,
                llmModel,
                systemPrompt,
                tmdbApiKey,
                twitchClientId,
                twitchClientSecret,
                // Voyage AI
                voyageApiKey,
                voyageModel,
                steamGridApiKey,
                // Feature Flags
                featureAiCritic: enableAiCritic ? 'true' : 'false',
                featureSmartSort: enableSmartSort ? 'true' : 'false',
                featureRecommendations: enableRecommendations ? 'true' : 'false',
                featureChallenges: enableChallenges ? 'true' : 'false'
            });
            toast.success("System configuration updated!");
        } catch {
            toast.error("Failed to update system config.");
        } finally {
            setIsLoading(false);
        }
    };



    return (
        <div className="space-y-8">
            {/* LLM Provider Section */}
            <Card className="border-white/10 bg-black/20 backdrop-blur-sm">
                <CardHeader>
                    <div className="flex items-center gap-2">
                        <Brain className="h-5 w-5 text-purple-500" />
                        <CardTitle>AI & LLM Provider</CardTitle>
                    </div>
                    <CardDescription>
                        Configure the AI provider for intelligence features.
                    </CardDescription>
                </CardHeader>
                <form onSubmit={handleSaveConfig}>
                    <CardContent className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="grid gap-2">
                                <Label>Provider</Label>
                                <Select value={llmProvider} onValueChange={(v) => { setLlmProvider(v); setAvailableModels([]); setLlmModel(''); }}>
                                    <SelectTrigger className="bg-zinc-900/50">
                                        <SelectValue placeholder="Select provider" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="openai">OpenAI</SelectItem>
                                        <SelectItem value="anthropic">Anthropic (Claude)</SelectItem>
                                        <SelectItem value="openrouter">OpenRouter</SelectItem>
                                        <SelectItem value="gemini">Google Gemini</SelectItem>
                                        <SelectItem value="ollama">Ollama (Local)</SelectItem>
                                        <SelectItem value="mistral">Mistral AI</SelectItem>
                                        <SelectItem value="anannas">Anannas AI</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                            <div className="grid gap-2">
                                <Label>API Key</Label>
                                <div className="flex gap-2">
                                    <Input
                                        type="password"
                                        value={llmApiKey}
                                        onChange={e => setLlmApiKey(e.target.value)}
                                        placeholder="sk-..."
                                        className="flex-1"
                                    />
                                    <Button
                                        type="button"
                                        variant="outline"
                                        size="sm"
                                        onClick={fetchModels}
                                        disabled={isLoadingModels}
                                        className="shrink-0"
                                    >
                                        {isLoadingModels ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
                                        <span className="ml-1 hidden sm:inline">Check Models</span>
                                    </Button>
                                </div>
                            </div>
                        </div>
                        <div className="grid gap-2">
                            <div className="flex items-center justify-between">
                                <Label>Model</Label>
                                <Button
                                    type="button"
                                    variant="secondary"
                                    size="sm"
                                    onClick={handleTestLLM}
                                    disabled={isTestLoading || !llmModel}
                                    className="h-7 text-[10px] gap-1 shadow-none hover:shadow-none hover:translate-y-0 active:scale-100"
                                >
                                    {isTestLoading ? <Loader2 className="h-3 w-3 animate-spin" /> : <Zap className="h-3 w-3" />}
                                    Test Connection
                                </Button>
                            </div>
                            <div className="space-y-1">
                                <div className="relative">
                                    <Input
                                        list="model-options"
                                        name="llmModel"
                                        value={llmModel}
                                        onChange={e => {
                                            setLlmModel(e.target.value);
                                            setTestResult(null); // Clear result on change
                                        }}
                                        placeholder={availableModels.length === 0 ? "Enter model name or click 'Check Models'..." : "Select or type model name..."}
                                        className={`bg-zinc-900/50 pr-10 transition-colors ${testResult ? (
                                            testResult.success
                                                ? "border-green-500/50 focus-visible:ring-green-500/30"
                                                : "border-red-500/50 focus-visible:ring-red-500/30"
                                        ) : (
                                            llmModel && !availableModels.includes(llmModel) && availableModels.length > 0
                                                ? "border-yellow-500/20"
                                                : ""
                                        )
                                            }`}
                                    />
                                    <div className="absolute right-3 top-1/2 -translate-y-1/2">
                                        {testResult ? (
                                            testResult.success ? (
                                                <CheckCircle2 className="h-4 w-4 text-green-500" />
                                            ) : (
                                                <AlertCircle className="h-4 w-4 text-red-500" />
                                            )
                                        ) : (
                                            llmModel && !availableModels.includes(llmModel) && availableModels.length > 0 && (
                                                <AlertTriangle className="h-4 w-4 text-yellow-500/50" />
                                            )
                                        )}
                                    </div>
                                </div>
                                <datalist id="model-options">
                                    {availableModels.map((model) => (
                                        <option key={model} value={model} />
                                    ))}
                                </datalist>
                                <div className="text-[10px] flex flex-col gap-0.5">
                                    {testResult && (
                                        <span className={testResult.success ? "text-green-500 font-medium" : "text-red-500 font-medium"}>
                                            {testResult.success ? "Γ£ô Connection Verified" : `Γ£ù Connection Failed: ${testResult.message}`}
                                        </span>
                                    )}
                                    {availableModels.length === 0 && !testResult && (
                                        <p className="text-muted-foreground">Enter your API key and click "Check Models" to load available models</p>
                                    )}
                                    {llmModel && !availableModels.includes(llmModel) && availableModels.length > 0 && !testResult && (
                                        <span className="text-yellow-500/70 flex items-center gap-1">
                                            <AlertTriangle className="h-3 w-3" /> Manual entry (unverified)
                                        </span>
                                    )}
                                </div>
                            </div>
                        </div>
                        <div className="grid gap-2">
                            <Label>System Prompt</Label>
                            <textarea
                                className="flex min-h-[120px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                                value={systemPrompt}
                                onChange={e => setSystemPrompt(e.target.value)}
                            />
                        </div>
                    </CardContent>
                    <CardFooter className="pt-4">
                        <Button type="submit" disabled={isLoading}>
                            {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                            Save LLM Configuration
                        </Button>
                    </CardFooter>
                </form>
            </Card>

            {/* Voyage AI Embeddings */}
            <Card className="border-white/10 bg-black/20 backdrop-blur-sm">
                <CardHeader>
                    <div className="flex items-center gap-2">
                        <Brain className="h-5 w-5 text-blue-500" />
                        <CardTitle>Voyage AI Embeddings</CardTitle>
                    </div>
                    <CardDescription>
                        API key and model for generating vector embeddings used in taste compatibility and item search.
                    </CardDescription>
                </CardHeader>
                <form onSubmit={handleSaveConfig}>
                    <CardContent className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="grid gap-2">
                                <Label>Voyage API Key</Label>
                                <Input
                                    type="password"
                                    value={voyageApiKey}
                                    onChange={e => setVoyageApiKey(e.target.value)}
                                    placeholder="pa-..."
                                />
                                <p className="text-[10px] text-muted-foreground">Get your key from <a href="https://dash.voyageai.com/" target="_blank" className="underline hover:text-white">dash.voyageai.com</a></p>
                            </div>
                            <div className="grid gap-2">
                                <Label>Embedding Model</Label>
                                <Select value={voyageModel} onValueChange={setVoyageModel}>
                                    <SelectTrigger className="bg-zinc-900/50">
                                        <SelectValue placeholder="Select model" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="voyage-4">voyage-4 (Latest)</SelectItem>
                                        <SelectItem value="voyage-3">voyage-3</SelectItem>
                                        <SelectItem value="voyage-3-lite">voyage-3-lite</SelectItem>
                                        <SelectItem value="voyage-large-2">voyage-large-2</SelectItem>
                                        <SelectItem value="voyage-code-2">voyage-code-2</SelectItem>
                                    </SelectContent>
                                </Select>
                                <p className="text-[10px] text-muted-foreground">Model used for generating embeddings (voyage-4 recommended)</p>
                            </div>
                        </div>
                    </CardContent>
                    <CardFooter className="pt-4">
                        <Button type="submit" disabled={isLoading}>
                            {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                            Save Voyage Configuration
                        </Button>
                    </CardFooter>
                </form>
            </Card>

            {/* Media Data Sources */}
            <Card className="border-white/10 bg-black/20 backdrop-blur-sm">
                <CardHeader>
                    <div className="flex items-center gap-2">
                        <Database className="h-5 w-5 text-green-500" />
                        <CardTitle>Media Data Sources</CardTitle>
                    </div>
                    <CardDescription>
                        API keys for fetching metadata from external services.
                    </CardDescription>
                </CardHeader>
                <form onSubmit={handleSaveConfig}>
                    <CardContent className="space-y-4">
                        <div className="grid gap-2">
                            <div className="flex items-center justify-between">
                                <Label>TMDB API Key (Movies & TV)</Label>
                                <Button
                                    type="button"
                                    variant="outline"
                                    size="sm"
