'use client'

import { useState, useEffect } from 'react'
import { Check, ChevronsUpDown, Filter, SortAsc, SortDesc, X, Search, ChevronRight, ArrowUpDown } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from '@/components/ui/command'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { Badge } from '@/components/ui/badge'
import { Separator } from '@/components/ui/separator'
import { ScrollArea } from '@/components/ui/scroll-area'
import { cn } from '@/lib/utils'
import { createClient } from '@/lib/supabase/client'
import { useSearchParams, useRouter } from 'next/navigation'

interface FilterOption {
    value: string
    count: number
}

interface AdvancedFilterBarProps {
    categoryType?: string
    onSortChange: (sort: string, order: 'asc' | 'desc') => void
    currentSort: string
    currentOrder: 'asc' | 'desc'
}

type FilterField =
    | 'genre' | 'director' | 'writer' | 'studio' | 'cast'
    | 'year' | 'content_rating' | 'country'
    | 'developer' | 'publisher' | 'platform'
    | 'designer' | 'mechanic' | 'artist' | 'category'

const FILTER_FIELDS: { label: string; field: FilterField | 'language' | 'production'; icon?: any }[] = [
    { label: 'Genre', field: 'genre' },
    { label: 'Year', field: 'year' },
    { label: 'Content Rating', field: 'content_rating' },
    { label: 'Studio', field: 'studio' },
    { label: 'Director', field: 'director' },
    { label: 'Writer', field: 'writer' },
    { label: 'Cast', field: 'cast' },
    { label: 'Country', field: 'country' },
    { label: 'Language', field: 'language' },
    { label: 'Production', field: 'production' },
    // Game specific
    { label: 'Developer', field: 'developer' },
    { label: 'Publisher', field: 'publisher' },
    { label: 'Platform', field: 'platform' },
    // Board Game specific
    { label: 'Designer', field: 'designer' },
    { label: 'Mechanic', field: 'mechanic' },
    { label: 'Artist', field: 'artist' },
    { label: 'Category', field: 'category' },
]

const SORT_OPTIONS = [
    { label: 'Date Added', value: 'created_at' },
    { label: 'Title', value: 'title' },
    { label: 'Release Date', value: 'release_year' },
    { label: 'Critic Rating', value: 'metacritic' },
    { label: 'Audience Rating', value: 'vote_average' },
    { label: 'Runtime', value: 'runtime' },
    { label: 'Last Updated', value: 'last_metadata_update' },
    { label: 'Reference ID', value: 'id' },
    { label: 'Director', value: 'director' },
    { label: 'Studio', value: 'studio' },
    { label: 'Writer', value: 'writer' },
    { label: 'Content Rating', value: 'content_rating' },
    { label: 'Language', value: 'original_language' },
]

export function AdvancedFilterBar({ categoryType, onSortChange, currentSort, currentOrder }: AdvancedFilterBarProps) {
    const router = useRouter()
    const searchParams = useSearchParams()
    const supabase = createClient()

    // State for Filter Popover
    const [openFilter, setOpenFilter] = useState(false)
    const [selectedField, setSelectedField] = useState<FilterField | 'language' | 'production' | null>(null)
    const [filterValues, setFilterValues] = useState<FilterOption[]>([])
    const [loadingValues, setLoadingValues] = useState(false)
    const [filterSearch, setFilterSearch] = useState('')

    // Helpers
    const getActiveFilterValue = (field: string) => searchParams.get(field)

    const handleApplyFilter = (field: string, value: string) => {
        const params = new URLSearchParams(searchParams.toString())
        if (value) {
            params.set(field, value)
        } else {
            params.delete(field)
        }
        // Reset page on filter change
        params.delete('page')
        router.push(`/admin/data-browser?${params.toString()}`)
        setOpenFilter(false)
        setSelectedField(null)
    }

    // Fetch values when a field is selected
    useEffect(() => {
        if (!selectedField) return

        const fetchValues = async () => {
            setLoadingValues(true)
            try {
                // Map frontend field to DB column if needed (usually 1:1 map with RPC)
                let dbColumn = selectedField as string
                if (selectedField === 'genre') dbColumn = 'genres'
                if (selectedField === 'year') dbColumn = 'release_year'
                if (selectedField === 'country') dbColumn = 'origin_countries'
                if (selectedField === 'developer') dbColumn = 'developers'
                if (selectedField === 'publisher') dbColumn = 'publishers'
                if (selectedField === 'platform') dbColumn = 'platforms'
                if (selectedField === 'designer') dbColumn = 'designers'
                if (selectedField === 'mechanic') dbColumn = 'mechanics'
                if (selectedField === 'artist') dbColumn = 'artists'
                if (selectedField === 'category') dbColumn = 'categories' // board game categories
                if (selectedField === 'language') dbColumn = 'original_language'
                if (selectedField === 'production') dbColumn = 'production_companies'

                const { data, error } = await supabase.rpc('get_filter_values', {
                    p_column: dbColumn,
                    p_category: categoryType, // Filter by active category tab if any
                    p_search: filterSearch,
                    p_limit: 100
                } as any)

                if (error) {
                    console.error('Error fetching filter values:', error)
                    setFilterValues([])
                } else {
                    setFilterValues(data || [])
                }
            } catch (e) {
                console.error(e)
            } finally {
                setLoadingValues(false)
            }
        }

        const debounceTimer = setTimeout(fetchValues, 300)
        return () => clearTimeout(debounceTimer)
    }, [selectedField, filterSearch, categoryType, supabase])

    return (
        <div className="flex items-center gap-2 mb-4">
            {/* =======================
                SORT CONTROL
            ======================= */}
            <Popover>
                <PopoverTrigger asChild>
                    <Button variant="outline" size="sm" className="h-8 border-dashed border-zinc-700 text-zinc-300 hover:text-white hover:bg-zinc-800">
                        <ArrowUpDown className="mr-2 h-4 w-4" />
                        Sort
                        {currentSort && (
                            <>
                                <Separator orientation="vertical" className="mx-2 h-4" />
                                <Badge variant="secondary" className="rounded-sm px-1 font-normal bg-zinc-800 text-zinc-300">
                                    {SORT_OPTIONS.find(s => s.value === currentSort)?.label || currentSort}
                                </Badge>
                            </>
                        )}
                    </Button>
                </PopoverTrigger>
                <PopoverContent className="w-[200px] p-0 bg-zinc-950 border-zinc-800" align="start">
                    <Command className="bg-transparent">
                        <CommandList>
                            <CommandGroup heading="Sort By">
                                {SORT_OPTIONS.map((option) => (
                                    <CommandItem
                                        key={option.value}
                                        onSelect={() => onSortChange(option.value, currentOrder)}
                                        className="text-zinc-300 aria-selected:bg-zinc-900 aria-selected:text-white cursor-pointer"
                                    >
                                        <div className={cn(
                                            "mr-2 flex h-4 w-4 items-center justify-center rounded-sm border border-zinc-700",
                                            currentSort === option.value ? "bg-cyan-900 border-cyan-700 text-cyan-400" : "opacity-50 [&_svg]:invisible"
                                        )}>
                                            <Check className={cn("h-4 w-4")} />
                                        </div>
                                        {option.label}
                                    </CommandItem>
                                ))}
                            </CommandGroup>
                            <Separator className="bg-zinc-800" />
                            <CommandGroup heading="Direction">
                                <CommandItem
                                    onSelect={() => onSortChange(currentSort, 'asc')}
                                    className="text-zinc-300 aria-selected:bg-zinc-900 aria-selected:text-white cursor-pointer"
                                >
                                    <SortAsc className="mr-2 h-4 w-4" />
                                    Ascending
                                    {currentOrder === 'asc' && <Check className="ml-auto h-4 w-4" />}
                                </CommandItem>
                                <CommandItem
                                    onSelect={() => onSortChange(currentSort, 'desc')}
                                    className="text-zinc-300 aria-selected:bg-zinc-900 aria-selected:text-white cursor-pointer"
                                >
                                    <SortDesc className="mr-2 h-4 w-4" />
                                    Descending
                                    {currentOrder === 'desc' && <Check className="ml-auto h-4 w-4" />}
                                </CommandItem>
                            </CommandGroup>
                        </CommandList>
                    </Command>
                </PopoverContent>
            </Popover>

            {/* =======================
                FILTER CONTROL
            ======================= */}
            <Popover open={openFilter} onOpenChange={(open) => {
                setOpenFilter(open)
                if (!open) {
                    setSelectedField(null)
                    setFilterSearch('')
                }
            }}>
                <PopoverTrigger asChild>
                    <Button variant="outline" size="sm" className="h-8 border-dashed border-zinc-700 text-zinc-300 hover:text-white hover:bg-zinc-800">
                        <Filter className="mr-2 h-4 w-4" />
                        Filter
                    </Button>
                </PopoverTrigger>
                <PopoverContent className="w-[280px] p-0 bg-zinc-950 border-zinc-800" align="start">
                    {/* LEVEL 1: Select Field */}
                    {!selectedField && (
                        <Command className="bg-transparent">
                            <CommandInput placeholder="Filter by..." className="border-none focus:ring-0 text-zinc-300 placeholder:text-zinc-600" />
                            <CommandList>
                                <CommandEmpty>No filter found.</CommandEmpty>
                                <CommandGroup>
                                    <ScrollArea className="h-[300px]">
                                        {FILTER_FIELDS.map((f) => {
                                            const isActive = !!getActiveFilterValue(f.field)
                                            // Check if this filter is relevant to current category? 
                                            // For now show all, or maybe hide Game ones if not game?
                                            // Simple logic: Hide Game specific if category is Moive? 
                                            // Let's rely on user for now or use categoryType prop to filter list.

                                            return (
                                                <CommandItem
                                                    key={f.field}
                                                    onSelect={() => setSelectedField(f.field)}
                                                    className="justify-between text-zinc-300 aria-selected:bg-zinc-900 aria-selected:text-white cursor-pointer"
                                                >
                                                    <span className={isActive ? "text-cyan-400 font-medium" : ""}>
                                                        {f.label}
                                                    </span>
                                                    <ChevronRight className="h-4 w-4 opacity-50" />
                                                </CommandItem>
                                            )
                                        })}
                                    </ScrollArea>
                                </CommandGroup>
                            </CommandList>
                        </Command>
                    )}

                    {/* LEVEL 2: Select Value */}
                    {selectedField && (
                        <div className="flex flex-col h-[350px]">
                            <div className="flex items-center gap-2 p-2 border-b border-zinc-800">
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    className="h-6 w-6 text-zinc-400 hover:text-white"
                                    onClick={() => setSelectedField(null)}
                                >
                                    <ChevronRight className="h-4 w-4 rotate-180" />
                                </Button>
                                <span className="font-medium text-sm text-zinc-200">
                                    {FILTER_FIELDS.find(f => f.field === selectedField)?.label}
                                </span>
                            </div>

                            <div className="p-2 border-b border-zinc-800">
                                <div className="relative">
                                    <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-500" />
                                    <input
                                        className="w-full bg-zinc-900 border border-zinc-700 rounded-md py-1.5 pl-8 pr-2 text-sm text-zinc-200 focus:outline-none focus:border-cyan-700"
                                        placeholder="Search..."
                                        value={filterSearch}
                                        onChange={(e) => setFilterSearch(e.target.value)}
                                        autoFocus
                                    />
                                </div>
                            </div>

                            <ScrollArea className="flex-1">
                                <div className="p-1">
                                    {loadingValues ? (
                                        <div className="p-4 text-center text-xs text-zinc-500">Loading...</div>
                                    ) : filterValues.length === 0 ? (
                                        <div className="p-4 text-center text-xs text-zinc-500">No results found</div>
                                    ) : (
                                        filterValues.map((opt) => (
                                            <div
                                                key={opt.value}
                                                className="flex items-center justify-between p-2 rounded-sm hover:bg-zinc-900 cursor-pointer text-sm text-zinc-300 hover:text-white"
                                                onClick={() => handleApplyFilter(selectedField, opt.value)}
                                            >
                                                <span className="truncate mr-2">{opt.value}</span>
                                                <span className="text-xs text-zinc-600 font-mono">{opt.count}</span>
                                            </div>
                                        ))
                                    )}
                                </div>
                            </ScrollArea>
                        </div>
                    )}
                </PopoverContent>
            </Popover>
        </div>
    )
}

'use client'

import React, { useState } from 'react'
import { motion } from 'framer-motion'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Sparkles, X, Loader2, Layers, ArrowRight } from 'lucide-react'
import type { CanvasItem } from './InfiniteCanvas'

interface ClusterSuggestion {
    name: string
    description: string
    itemIds: string[]
    confidence: number
}

interface AISidekickProps {
    items: CanvasItem[]
    selectedItemIds: string[]
    onClose: () => void
    onApplyClusters: (clusters: ClusterSuggestion[]) => void
}

export function AISidekick({
    items,
    selectedItemIds,
    onClose,
    onApplyClusters
}: AISidekickProps) {
    const [isAnalyzing, setIsAnalyzing] = useState(false)
    const [suggestions, setSuggestions] = useState<ClusterSuggestion[]>([])
    const [error, setError] = useState<string | null>(null)

    const handleAnalyze = async () => {
        setIsAnalyzing(true)
        setError(null)

        try {
            // In production, this would call an API endpoint that uses
            // the findSimilarItems RPC and agent orchestrator
            // For now, simulate with mock data
            await new Promise(resolve => setTimeout(resolve, 1500))

            // Mock suggestions based on items
            const mockSuggestions: ClusterSuggestion[] = [
                {
                    name: "High-Rated Classics",
                    description: "Items with S or A tier ratings that share similar themes",
                    itemIds: items.filter(i => i.tier === 'S' || i.tier === 'A').slice(0, 5).map(i => i.id),
                    confidence: 0.89
                },
                {
                    name: "Similar Genre",
                    description: "Items clustered by vector similarity",
                    itemIds: items.slice(0, 4).map(i => i.id),
                    confidence: 0.76
                },
                {
                    name: "Recent Additions",
                    description: "Newly added items that might relate",
                    itemIds: items.slice(-3).map(i => i.id),
                    confidence: 0.65
                }
            ].filter(s => s.itemIds.length > 1)

            setSuggestions(mockSuggestions)
        } catch (e) {
            setError('Failed to analyze items. Try again.')
        } finally {
            setIsAnalyzing(false)
        }
    }

    return (
        <motion.div
            initial={{ opacity: 0, x: 300 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 300 }}
            transition={{ type: 'spring', damping: 25 }}
            className="absolute right-4 top-4 bottom-4 w-80 z-50"
        >
            <Card className="h-full bg-black/90 backdrop-blur-xl border-white/10 flex flex-col">
                <CardHeader className="pb-3 flex-shrink-0">
                    <div className="flex items-center justify-between">
                        <CardTitle className="text-white flex items-center gap-2">
                            <Sparkles className="w-5 h-5 text-purple-400" />
                            AI Sidekick
                        </CardTitle>
                        <Button
                            variant="ghost"
                            size="icon"
                            onClick={onClose}
                            className="text-white/60 hover:text-white hover:bg-white/10"
                        >
                            <X className="w-4 h-4" />
                        </Button>
                    </div>
                    <p className="text-sm text-white/60 mt-1">
                        Auto-group items based on vector similarity
                    </p>
                </CardHeader>

                <CardContent className="flex-1 flex flex-col min-h-0">
                    {/* Context info */}
                    <div className="bg-white/5 rounded-lg p-3 mb-4">
                        <div className="text-xs text-white/50 mb-1">Analyzing</div>
                        <div className="text-sm text-white">
                            {selectedItemIds.length > 0
                                ? `${selectedItemIds.length} selected items`
                                : `${items.length} items on canvas`
                            }
                        </div>
                    </div>

                    {/* Analyze button */}
                    {suggestions.length === 0 && !isAnalyzing && (
                        <Button
                            onClick={handleAnalyze}
                            disabled={isAnalyzing}
                            className="w-full bg-purple-600 hover:bg-purple-700 text-white mb-4"
                        >
                            {isAnalyzing ? (
                                <>
                                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                    Analyzing...
                                </>
                            ) : (
                                <>
                                    <Sparkles className="w-4 h-4 mr-2" />
                                    Find Clusters
                                </>
                            )}
                        </Button>
                    )}

                    {/* Loading state */}
                    {isAnalyzing && (
                        <div className="flex-1 flex flex-col items-center justify-center text-white/60">
                            <Loader2 className="w-8 h-8 animate-spin mb-3 text-purple-400" />
                            <p className="text-sm">Analyzing embeddings...</p>
                        </div>
                    )}

                    {/* Error */}
                    {error && (
                        <div className="bg-red-500/20 text-red-300 rounded-lg p-3 mb-4 text-sm">
                            {error}
                        </div>
                    )}

                    {/* Suggestions */}
                    {suggestions.length > 0 && (
                        <ScrollArea className="flex-1">
                            <div className="space-y-3 pr-4">
                                {suggestions.map((suggestion, idx) => (
                                    <motion.div
                                        key={idx}
                                        initial={{ opacity: 0, y: 10 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        transition={{ delay: idx * 0.1 }}
                                    >
                                        <Card className="bg-white/5 border-white/10 hover:border-purple-500/50 transition-colors cursor-pointer">
                                            <CardContent className="p-3">
                                                <div className="flex items-start justify-between mb-2">
                                                    <div className="flex items-center gap-2">
                                                        <Layers className="w-4 h-4 text-purple-400" />
                                                        <span className="text-sm font-medium text-white">
                                                            {suggestion.name}
                                                        </span>
                                                    </div>
                                                    <Badge
                                                        variant="secondary"
                                                        className="bg-purple-500/20 text-purple-300 text-xs"
                                                    >
                                                        {Math.round(suggestion.confidence * 100)}%
                                                    </Badge>
                                                </div>
                                                <p className="text-xs text-white/50 mb-2">
                                                    {suggestion.description}
                                                </p>
                                                <div className="flex items-center justify-between">
                                                    <span className="text-xs text-white/40">
                                                        {suggestion.itemIds.length} items
                                                    </span>
                                                    <Button
                                                        size="sm"
                                                        variant="ghost"
                                                        className="text-purple-400 hover:text-purple-300 hover:bg-purple-500/20 h-7 px-2"
                                                        onClick={() => onApplyClusters([suggestion])}
                                                    >
                                                        Apply
                                                        <ArrowRight className="w-3 h-3 ml-1" />
                                                    </Button>
                                                </div>
                                            </CardContent>
                                        </Card>
                                    </motion.div>
                                ))}

                                {/* Apply all button */}
                                <Button
                                    onClick={() => onApplyClusters(suggestions)}
                                    className="w-full bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white mt-2"
                                >
                                    Apply All Clusters
                                </Button>
                            </div>
                        </ScrollArea>
                    )}
                </CardContent>
            </Card>
        </motion.div>
    )
}

'use client'

import React, { useCallback, useMemo, useState } from 'react'
import {
    ReactFlow,
    Background,
    Controls,
    MiniMap,
    useNodesState,
    useEdgesState,
    addEdge,
    Connection,
    Node,
    Edge,
    Panel,
    BackgroundVariant,
    type NodeMouseHandler,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import { motion, AnimatePresence } from 'framer-motion'
import { Button } from '@/components/ui/button'
import { Layers, Sparkles } from 'lucide-react'
import { ItemNode, ItemNodeData } from './ItemNode'
import { AISidekick } from './AISidekick'

// Node types registration - use type assertion for compatibility
const nodeTypes = {
    item: ItemNode,
} as const

export interface CanvasItem {
    id: string
    title: string
    image_url: string | null
    tier?: string | null
    category_type?: string
    similarity?: number
    embedding?: number[] // For clustering
}

interface InfiniteCanvasProps {
    items: CanvasItem[]
    onItemClick?: (item: CanvasItem) => void
    onClusterItems?: (itemIds: string[]) => void
    similarityThreshold?: number
}

// Layout algorithm for initial placement
function calculateInitialLayout(items: CanvasItem[]): Node[] {
    const GRID_SPACING = 200
    const ITEMS_PER_ROW = Math.ceil(Math.sqrt(items.length))

    return items.map((item, index) => {
        const row = Math.floor(index / ITEMS_PER_ROW)
        const col = index % ITEMS_PER_ROW

        return {
            id: item.id,
            type: 'item',
            position: {
                x: col * GRID_SPACING + (Math.random() * 20 - 10), // Slight randomness
                y: row * GRID_SPACING + (Math.random() * 20 - 10)
            },
            data: {
                title: item.title,
                image: item.image_url,
                tier: item.tier,
                category: item.category_type,
                similarity: item.similarity,
            } satisfies ItemNodeData
        }
    })
}

// Create edges between similar items
function createSimilarityEdges(
    items: CanvasItem[],
    threshold: number = 0.7
): Edge[] {
    const edges: Edge[] = []

    // For items with similarity scores
    items.forEach((item, i) => {
        if (item.similarity && item.similarity >= threshold) {
            // Connect to the "source" item (first in list)
            if (i > 0) {
                edges.push({
                    id: `sim-${items[0].id}-${item.id}`,
                    source: items[0].id,
                    target: item.id,
                    style: {
                        stroke: `rgba(139, 92, 246, ${item.similarity})`,
                        strokeWidth: 2,
                    },
                    animated: item.similarity > 0.8,
                })
            }
        }
    })

    return edges
}

export function InfiniteCanvas({
    items,
    onItemClick,
    onClusterItems,
    similarityThreshold = 0.7
}: InfiniteCanvasProps) {
    const [showSidekick, setShowSidekick] = useState(false)
    const [selectedNodes, setSelectedNodes] = useState<string[]>([])

    // Initialize nodes and edges
    const initialNodes = useMemo(() => calculateInitialLayout(items), [items])
    const initialEdges = useMemo(
        () => createSimilarityEdges(items, similarityThreshold),
        [items, similarityThreshold]
    )

    const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes)
    const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges)

    const onConnect = useCallback(
        (params: Connection) => setEdges((eds) => addEdge(params, eds)),
        [setEdges]
    )

    const onNodeClick: NodeMouseHandler = useCallback((_event, node) => {
        const item = items.find(i => i.id === node.id)
        if (item && onItemClick) {
            onItemClick(item)
        }
    }, [items, onItemClick])

    const onSelectionChange = useCallback(({ nodes: selectedNodesList }: { nodes: Node[] }) => {
        setSelectedNodes(selectedNodesList.map(n => n.id))
    }, [])

    const handleClusterSelected = useCallback(() => {
        if (selectedNodes.length > 1 && onClusterItems) {
            onClusterItems(selectedNodes)
        }
    }, [selectedNodes, onClusterItems])

    // Auto-cluster by similarity
    const handleAutoCluster = useCallback(async () => {
        // This would call the backend to get similarity clusters
        // For now, just trigger the sidekick
        setShowSidekick(true)
    }, [])

    return (
        <div className="w-full h-full relative">
            <ReactFlow
                nodes={nodes}
                edges={edges}
                onNodesChange={onNodesChange}
                onEdgesChange={onEdgesChange}
                onConnect={onConnect}
                onNodeClick={onNodeClick}
                onSelectionChange={onSelectionChange}
                nodeTypes={nodeTypes}
                fitView
                minZoom={0.1}
                maxZoom={2}
                className="bg-black"
                selectionOnDrag
                panOnScroll
                selectNodesOnDrag={false}
            >
                <Background
                    variant={BackgroundVariant.Dots}
                    gap={20}
                    size={1}
                    color="rgba(255,255,255,0.1)"
                />

                <Controls
                    className="bg-black/50 backdrop-blur-md border border-white/10 rounded-lg"
                    showInteractive={false}
                />

                <MiniMap
                    className="bg-black/50 backdrop-blur-md border border-white/10 rounded-lg"
                    nodeColor={(node) => {
                        const nodeData = node.data as ItemNodeData
                        const tier = nodeData?.tier
                        switch (tier) {
                            case 'S': return '#f87171'
                            case 'A': return '#fb923c'
                            case 'B': return '#facc15'
                            case 'C': return '#4ade80'
                            case 'D': return '#60a5fa'
                            default: return '#6b7280'
                        }
                    }}
                    maskColor="rgba(0,0,0,0.8)"
                />

                {/* Top Panel - Controls */}
                <Panel position="top-left" className="flex gap-2">
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={handleAutoCluster}
                        className="bg-black/50 backdrop-blur-md border-white/20 text-white hover:bg-white/10"
                    >
                        <Sparkles className="w-4 h-4 mr-2" />
                        AI Cluster
                    </Button>

                    {selectedNodes.length > 1 && (
                        <motion.div
                            initial={{ opacity: 0, x: -10 }}
                            animate={{ opacity: 1, x: 0 }}
                        >
                            <Button
                                variant="outline"
                                size="sm"
                                onClick={handleClusterSelected}
                                className="bg-purple-500/20 backdrop-blur-md border-purple-500/50 text-white hover:bg-purple-500/30"
                            >
                                <Layers className="w-4 h-4 mr-2" />
                                Group {selectedNodes.length} Items
                            </Button>
                        </motion.div>
                    )}
                </Panel>

                {/* Stats Panel */}
                <Panel position="top-right">
                    <div className="bg-black/50 backdrop-blur-md rounded-lg px-3 py-2 border border-white/10">
                        <div className="flex items-center gap-3 text-sm text-white/70">
                            <span>{nodes.length} items</span>
                            <span>ΓÇó</span>
                            <span>{edges.length} connections</span>
                        </div>
                    </div>
                </Panel>
            </ReactFlow>

            {/* AI Sidekick */}
            <AnimatePresence>
                {showSidekick && (
                    <AISidekick
                        items={items}
                        selectedItemIds={selectedNodes}
                        onClose={() => setShowSidekick(false)}
                        onApplyClusters={(clusters) => {
                            // Apply clustering - update node positions
                            console.log('Apply clusters:', clusters)
                            setShowSidekick(false)
                        }}
                    />
                )}
            </AnimatePresence>
        </div>
    )
}

