'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import { createClient } from '@/lib/supabase/client'
import { Button } from '@/components/ui/button'
import { Play, Pause, Music } from 'lucide-react'
import { ScrollArea } from '@/components/ui/scroll-area'

interface Track {
    id: string
    title: string
    track_number: number | null
    duration_ms: number | null
    preview_url: string | null
    audio_features: {
        danceability?: number
        energy?: number
        valence?: number
        acousticness?: number
        tempo?: number
    } | null
}

interface TrackListProps {
    albumName: string
    artistNames: string[]
    onFeaturesLoad?: (features: Track['audio_features'][]) => void
}

// Format duration to m:ss
function formatDuration(ms: number | null): string {
    if (!ms) return '--:--'
    const totalSeconds = Math.floor(ms / 1000)
    const minutes = Math.floor(totalSeconds / 60)
    const seconds = totalSeconds % 60
    return `${minutes}:${seconds.toString().padStart(2, '0')}`
}

export default function TrackList({ albumName, artistNames, onFeaturesLoad }: TrackListProps) {
    const [tracks, setTracks] = useState<Track[]>([])
    const [loading, setLoading] = useState(true)
    const [playingId, setPlayingId] = useState<string | null>(null)
    const audioRef = useRef<HTMLAudioElement | null>(null)

    // Fetch tracks for this album
    const fetchTracks = useCallback(async () => {
        setLoading(true)
        const supabase = createClient()

        try {
            // Query tracks where album_name matches and artist overlap
            const { data, error } = await (supabase
                .from('global_items') as any)
                .select('id, title, track_number, duration_ms, preview_url, audio_features')
                .eq('category_type', 'MUSIC_TRACK')
                .eq('album_name', albumName)
                .order('track_number', { ascending: true })

            if (error) throw error

            // Filter by artist overlap if needed (relaxed for now)
            const filteredTracks = data || []
            setTracks(filteredTracks)

            // Pass features up for aggregation
            if (onFeaturesLoad && filteredTracks.length > 0) {
                const features = filteredTracks
                    .map((t: Track) => t.audio_features)
                    .filter(Boolean)
                onFeaturesLoad(features)
            }
        } catch (err) {
            console.error('Failed to fetch tracks:', err)
        } finally {
            setLoading(false)
        }
    }, [albumName, artistNames, onFeaturesLoad])

    useEffect(() => {
        if (albumName) {
            fetchTracks()
        }
    }, [albumName, fetchTracks])

    // Handle play/pause
    const handlePlayPause = (track: Track) => {
        if (!track.preview_url) return

        if (playingId === track.id) {
            // Pause current
            audioRef.current?.pause()
            setPlayingId(null)
        } else {
            // Play new track
            if (audioRef.current) {
                audioRef.current.pause()
            }
            const audio = new Audio(track.preview_url)
            audio.volume = 0.5
            audio.play()
            audio.onended = () => setPlayingId(null)
            audioRef.current = audio
            setPlayingId(track.id)
        }
    }

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            audioRef.current?.pause()
        }
    }, [])

    if (loading) {
        return (
            <div className="flex items-center gap-2 text-zinc-500 text-sm py-4">
                <Music className="w-4 h-4 animate-pulse" />
                <span>Loading tracks...</span>
            </div>
        )
    }

    if (tracks.length === 0) {
        return (
            <div className="text-zinc-500 text-sm py-4 text-center">
                No tracks found for this album
            </div>
        )
    }

    return (
        <div className="space-y-2">
            <h3 className="text-sm font-medium text-zinc-300 flex items-center gap-2">
                <Music className="w-4 h-4" />
                Tracklist ({tracks.length})
            </h3>

            <ScrollArea className="max-h-[300px]">
                <div className="space-y-1">
                    {tracks.map((track, index) => (
                        <div
                            key={track.id}
                            className={`flex items-center gap-3 py-2 px-3 rounded-lg transition-colors ${playingId === track.id
                                    ? 'bg-purple-500/10 text-purple-300'
                                    : 'hover:bg-zinc-800/50'
                                }`}
                        >
                            {/* Track Number */}
                            <span className="w-6 text-xs text-zinc-500 text-right tabular-nums">
                                {track.track_number || index + 1}
                            </span>

                            {/* Play Button */}
                            {track.preview_url ? (
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    className="h-7 w-7 shrink-0 text-zinc-400 hover:text-white"
                                    onClick={() => handlePlayPause(track)}
                                    aria-label={playingId === track.id ? `Pause ${track.title}` : `Play ${track.title}`}
                                >
                                    {playingId === track.id ? (
                                        <Pause className="w-3.5 h-3.5 fill-current" />
                                    ) : (
                                        <Play className="w-3.5 h-3.5 fill-current" />
                                    )}
                                </Button>
                            ) : (
                                <div className="h-7 w-7 shrink-0" />
                            )}

                            {/* Title */}
                            <span className="flex-1 text-sm text-zinc-200 truncate">
                                {track.title}
                            </span>

                            {/* Duration */}
                            <span className="text-xs text-zinc-500 tabular-nums">
                                {formatDuration(track.duration_ms)}
                            </span>
                        </div>
                    ))}
                </div>
            </ScrollArea>
        </div>
    )
}

'use client'

import { useMemo } from 'react'
import { Progress } from '@/components/ui/progress'

interface AudioFeatures {
    danceability?: number
    energy?: number
    valence?: number
    acousticness?: number
    tempo?: number
}

interface VibeMeterProps {
    // Can accept array of track features or single album average
    features: AudioFeatures | AudioFeatures[] | null
}

// Labels for meter display
const VIBE_METRICS: { key: string; icon: string; label: string; color: string; subtext?: string }[] = [
    { key: 'danceability', icon: '≡ƒÆâ', label: 'Danceability', color: 'bg-purple-500' },
    { key: 'energy', icon: 'ΓÜí', label: 'Energy', color: 'bg-orange-500' },
    { key: 'valence', icon: '≡ƒî₧', label: 'Mood', subtext: 'Sad ΓåÆ Happy', color: 'bg-yellow-500' },
    { key: 'acousticness', icon: '≡ƒÄ╕', label: 'Acousticness', color: 'bg-green-500' },
]

type MetricKey = 'danceability' | 'energy' | 'valence' | 'acousticness'

// Aggregate multiple features into averages
function aggregateFeatures(features: AudioFeatures[]): AudioFeatures {
    if (features.length === 0) return {}

    const sums: Record<string, { total: number; count: number }> = {}

    for (const f of features) {
        for (const key of ['danceability', 'energy', 'valence', 'acousticness'] as const) {
            if (f[key] != null) {
                if (!sums[key]) sums[key] = { total: 0, count: 0 }
                sums[key].total += f[key]!
                sums[key].count++
            }
        }
    }

    const result: AudioFeatures = {}
    for (const [key, val] of Object.entries(sums)) {
        if (val.count > 0) {
            (result as any)[key] = val.total / val.count
        }
    }

    return result
}

export default function VibeMeter({ features }: VibeMeterProps) {
    // Compute the averaged features
    const avgFeatures = useMemo(() => {
        if (!features) return null
        if (Array.isArray(features)) {
            const validFeatures = features.filter(Boolean)
            return validFeatures.length > 0 ? aggregateFeatures(validFeatures) : null
        }
        return features
    }, [features])

    // Check if we have any data
    const hasData = avgFeatures && Object.keys(avgFeatures).length > 0

    if (!hasData) {
        return (
            <div className="text-zinc-500 text-xs text-center py-4">
                No audio analysis available
            </div>
        )
    }

    return (
        <div className="space-y-3">
            <h4 className="text-xs font-medium text-zinc-400 uppercase tracking-wider">
                Album Vibe
            </h4>

            <div className="space-y-3">
                {VIBE_METRICS.map((metric) => {
                    const value = avgFeatures[metric.key as MetricKey]
                    if (value == null) return null

                    // Convert 0-1 to 0-100
                    const percentage = Math.round(value * 100)

                    return (
                        <div key={metric.key} className="space-y-1">
                            <div className="flex items-center justify-between text-xs">
                                <span className="flex items-center gap-1.5 text-zinc-300">
                                    <span>{metric.icon}</span>
                                    <span>{metric.label}</span>
                                </span>
                                <span className="text-zinc-500 tabular-nums">
                                    {percentage}%
                                </span>
                            </div>

                            <div className="relative h-2 bg-zinc-800 rounded-full overflow-hidden">
                                <div
                                    className={`h-full ${metric.color} transition-all duration-500 rounded-full`}
                                    style={{ width: `${percentage}%` }}
                                />
                            </div>

                            {metric.subtext && (
                                <p className="text-[10px] text-zinc-600 text-center">
                                    {metric.subtext}
                                </p>
                            )}
                        </div>
                    )
                })}
            </div>
        </div>
    )
}

'use server'

import { createClient } from '@/lib/supabase/server'
import { revalidatePath } from 'next/cache'
import { downloadImageFromUrl } from './upload'
import { getGuestUserId } from '@/lib/actions/auth'
import { parseItemMetadata } from '@/lib/types/metadata'
import { z } from 'zod'
import { zfd } from 'zod-form-data'
import { getSession } from '@/lib/auth'
import { searchMediaAction } from './media'
import { getCategory } from './categories'
import { transformItem, transformItems } from '@/lib/utils/transformItem'
import { upsertGlobalItem } from '@/lib/utils/globalItems'
import { requireAuth, requireOwnership, requireResource } from '@/lib/utils/errors'

export async function getItems(
    query?: string,
    page: number = 1,
    limit: number = 12,
    categoryId?: string
) {
    const userId = await getGuestUserId()
    const supabase = await createClient()
    const offset = (page - 1) * limit

    // Build query
    let queryBuilder = (supabase.from('items') as any)
        .select(`
            *,
            global_item:global_items(*),
            tags:items_to_tags(tag:tags(*)),
            ratings(*)
        `, { count: 'exact' })

    if (categoryId) {
        queryBuilder = queryBuilder.eq('category_id', categoryId)
    }

    if (query) {
        // Search in both global_items title and items name
        queryBuilder = queryBuilder.or(`name.ilike.%${query}%,global_item.title.ilike.%${query}%`)
    }

    queryBuilder = queryBuilder
        .order('created_at', { ascending: false })

    if (limit > 0) {
        queryBuilder = queryBuilder.range(offset, offset + limit - 1)
    }

    const { data, count, error } = await queryBuilder

    if (error) throw error

    const totalCount = count || 0

    // Transform items using shared helper
    const transformedItems = transformItems(data || [], userId || undefined)

    return {
        items: transformedItems,
        totalCount,
        totalPages: limit > 0 ? Math.ceil(totalCount / limit) : 1
    }
}

export async function getItem(id: string) {
    const userId = await getGuestUserId()
    const supabase = await createClient()

    const { data: item, error } = await (supabase.from('items') as any)
        .select(`
            *,
            global_item:global_items(*),
            tags:items_to_tags(tag:tags(*)),
            ratings(*),
            category:categories(*, custom_ranks:custom_ranks(*))
        `)
        .eq('id', id)
        .single()

    if (error && error.code !== 'PGRST116') throw error
    if (!item) return null

    // Transform using shared helper
    return transformItem(item, userId || undefined)
}

// Zod Schemas
const createItemSchema = z.object({
    name: z.string().min(1),
    description: z.string().optional().default(""),
    categoryId: z.string().uuid(),
    image: z.string().optional().default(""),
    tags: z.array(z.string()).optional().default([]),
    metadata: z.string().optional().nullable()
})

const updateItemSchema = z.object({
    name: z.string().optional(),
    description: z.string().optional(),
    categoryId: z.string().uuid().optional(),
    image: z.string().optional(),
    metadata: z.string().optional(),
    tags: z.array(z.string()).optional(),
    notes: z.string().optional(),
    tier: z.string().optional(),
    rank: z.number().optional(),
    categoryType: z.string().optional()
})

export async function createItemInternal(input: z.input<typeof createItemSchema>) {
    const data = createItemSchema.parse(input)
    const userId = await getGuestUserId()
    const supabase = await createClient()
    const { name, description, categoryId, tags: tagIds, metadata } = data
    let image = data.image

    // Auto-localize external images
    if (image && image.startsWith('http')) {
        const localPath = await downloadImageFromUrl(image)
        if (localPath) {
            image = localPath
        }
    }

    // Upsert GlobalItem first
    let externalId: string | null = null
    if (metadata) {
        const parsedMeta = parseItemMetadata(typeof metadata === 'string' ? metadata : JSON.stringify(metadata))
        externalId = parsedMeta?.externalId || null
    }

    const globalItem = await upsertGlobalItem({
        externalId,
        title: name,
        description,
        imageUrl: image,
        metadata: typeof metadata === 'string' ? metadata : (metadata ? JSON.stringify(metadata) : null)
    })

    const { data: newItem, error } = await (supabase.from('items') as any)
        .insert({
            global_item_id: globalItem.id,
            user_id: userId,
            category_id: categoryId,
            elo_score: 1200,
        })
        .select()
        .single()

    if (error) throw error

    if (tagIds && tagIds.length > 0) {
        await (supabase.from('items_to_tags') as any).insert(
            tagIds.map(tagId => ({
                item_id: newItem.id,
                tag_id: tagId
            }))
        )
    }

    revalidatePath('/items')
    if (categoryId) {
        revalidatePath(`/categories/${categoryId}`)
    }
    return newItem
}

