/**
 * Auto-match items without global_item_id to external media services.
 * Uses the category to determine which provider to search (TMDB, Spotify, RAWG, etc.)
 * 
 * @param items - Array of items with id, name, and optional global_item_id
 * @param categoryId - Category ID to determine search provider
 * @returns Map of item IDs to their matched global_item data (image, description)
 */
export async function autoMatchItemsToGlobal(
    items: { id: string; name: string; global_item_id?: string | null }[],
    categoryId: string
): Promise<Map<string, { image: string | null; description: string | null; globalItemId: string }>> {
    const supabase = await createClient()
    const results = new Map<string, { image: string | null; description: string | null; globalItemId: string }>()

    // Get category info for search routing
    const category = await getCategory(categoryId)
    if (!category) return results

    // Filter items that need matching (either no global_item_id OR explicitly requested)
    // We trust the caller to pass only items that need processing
    const itemsToMatch = items
    if (itemsToMatch.length === 0) return results

    console.log(`[AutoMatch] Matching/Updating ${itemsToMatch.length} items for category "${category.name}"`)

    // Process items in batches to avoid rate limits
    for (const item of itemsToMatch) {
        try {
            // Strip year from name for better matching
            const cleanName = item.name.replace(/\s*\(\d{4}\)\s*$/, '').trim()

            // Search using MediaService (routes to correct provider based on category)
            const searchResult = await searchMediaAction(cleanName, category.name, null, categoryId)

            if (!searchResult.success || !searchResult.data || searchResult.data.length === 0) {
                console.log(`[AutoMatch] No results for "${cleanName}"`)
                continue
            }

            // Take first result
            const match = searchResult.data[0]
            console.log(`[AutoMatch] Matched "${cleanName}" -> "${match.title}" (${match.id})`)

            // Create/get global item
            const globalItem = await upsertGlobalItem({
                externalId: match.id,
                title: match.title,
                description: match.description,
                imageUrl: match.imageUrl,
                metadata: match.metadata
            })

            // Update item to link to global item
            await (supabase.from('items') as any)
                .update({ global_item_id: globalItem.id })
                .eq('id', item.id)

            results.set(item.id, {
                image: globalItem.image_url,
                description: globalItem.description,
                globalItemId: globalItem.id
            })

        } catch (error) {
            console.error(`[AutoMatch] Error matching "${item.name}":`, error)
        }
    }

    console.log(`[AutoMatch] Successfully matched ${results.size} of ${itemsToMatch.length} items`)
    return results
}

import {
    type ImportStrategy,
    type ParsedImport,
    type ParsedImportItem,
    URL_PATTERNS
} from '@/lib/types/import'

interface SpotifyToken {
    access_token: string;
    expires_in: number;
}

interface SpotifyTrack {
    track: {
        name: string;
        artists: { name: string }[];
        album: { name: string; release_date: string };
    };
}

export class SpotifyAdapter implements ImportStrategy {
    name = 'SpotifyAdapter'
    private clientId = process.env.SPOTIFY_CLIENT_ID
    private clientSecret = process.env.SPOTIFY_CLIENT_SECRET

    canHandle(input: string): boolean {
        return URL_PATTERNS.SPOTIFY_PLAYLIST.test(input)
    }

    async parse(input: string): Promise<ParsedImport> {
        const playlistId = this.extractPlaylistId(input)
        if (!playlistId) {
            throw new Error('Invalid Spotify playlist URL')
        }

        const token = await this.getAccessToken()
        if (!token) {
            throw new Error('Failed to authenticate with Spotify')
        }

        const playlistData = await this.fetchPlaylistData(token, playlistId)
        const items = await this.fetchPlaylistTracks(token, playlistId)

        return {
            source: 'spotify_playlist',
            collectionTitle: playlistData.name,
            collectionDescription: playlistData.description,
            mediaType: 'music',
            items: items.map((item, index) => ({
                title: item.track.name,
                artist: item.track.artists.map(a => a.name).join(', '),
                releaseYear: item.track.album.release_date ? parseInt(item.track.album.release_date.split('-')[0]) : undefined,
                rank: index + 1,
                mediaType: 'music',
                confidence: 1,
                rawInput: `${item.track.name} - ${item.track.artists.map(a => a.name).join(', ')}`
            })),
            parseConfidence: 1
        }
    }

    private extractPlaylistId(url: string): string | null {
        const match = url.match(/playlist\/([a-zA-Z0-9]+)/)
        return match ? match[1] : null
    }

    private async getAccessToken(): Promise<string | null> {
        if (!this.clientId || !this.clientSecret) return null

        try {
            const response = await fetch('https://accounts.spotify.com/api/token', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                    'Authorization': `Basic ${Buffer.from(`${this.clientId}:${this.clientSecret}`).toString('base64')}`
                },
                body: 'grant_type=client_credentials'
            })

            if (!response.ok) return null
            const data: SpotifyToken = await response.json()
            return data.access_token
        } catch (error) {
            console.error('[SpotifyAdapter] Auth error:', error)
            return null
        }
    }

    private async fetchPlaylistData(token: string, playlistId: string): Promise<{ name: string, description: string }> {
        const response = await fetch(`https://api.spotify.com/v1/playlists/${playlistId}?fields=name,description`, {
            headers: { 'Authorization': `Bearer ${token}` }
        })

        if (!response.ok) {
            throw new Error(`Failed to fetch playlist data: ${response.status}`)
        }

        return await response.json()
    }

    private async fetchPlaylistTracks(token: string, playlistId: string): Promise<SpotifyTrack[]> {
        const tracks: SpotifyTrack[] = []
        let offset = 0
        const limit = 100
        let next = true

        while (next) {
            const response = await fetch(`https://api.spotify.com/v1/playlists/${playlistId}/tracks?offset=${offset}&limit=${limit}&fields=items(track(name,artists(name),album(name,release_date))),next`, {
                headers: { 'Authorization': `Bearer ${token}` }
            })

            if (!response.ok) break

            const data = await response.json()
            if (data.items) {
                tracks.push(...data.items.filter((i: any) => i.track)) // Filter out null tracks
            }

            if (!data.next) {
                next = false
            } else {
                offset += limit
            }
        }

        return tracks
    }
}

/**
 * Layout Optimizer
 * 
 * Calculates optimal grid layouts based on item count, container size, and display mode.
 * Provides responsive tile sizing and spacing recommendations.
 */

export interface LayoutConfig {
    tileSize: number
    gap: number
    columns: number
    rows: number
    containerPadding: number
}

export interface LayoutConstraints {
    minTileSize?: number
    maxTileSize?: number
    minGap?: number
    maxGap?: number
    preferSquare?: boolean
}

const DEFAULT_CONSTRAINTS: LayoutConstraints = {
    minTileSize: 80,
    maxTileSize: 200,
    minGap: 8,
    maxGap: 16,
    preferSquare: true
}

/**
 * Calculate optimal layout for a grid of items
 */
export function calculateOptimalLayout(
    itemCount: number,
    containerWidth: number,
    containerHeight: number,
    constraints: LayoutConstraints = {}
): LayoutConfig {
    const opts = { ...DEFAULT_CONSTRAINTS, ...constraints }
    const { minTileSize, maxTileSize, minGap, maxGap } = opts

    // Handle edge cases
    if (itemCount === 0) {
        return {
            tileSize: maxTileSize!,
            gap: minGap!,
            columns: 1,
            rows: 1,
            containerPadding: 16
        }
    }

    // Calculate aspect ratio of container
    const containerRatio = containerWidth / containerHeight

    // Try to find a layout that fills the container nicely
    let bestLayout: LayoutConfig | null = null
    let bestScore = -Infinity

    // Try different column counts
    for (let cols = 1; cols <= Math.min(itemCount, 20); cols++) {
        const rows = Math.ceil(itemCount / cols)

        // Calculate tile size that would fit
        const availableWidth = containerWidth - (minGap! * (cols + 1))
        const availableHeight = containerHeight - (minGap! * (rows + 1))

        const maxTileFromWidth = availableWidth / cols
        const maxTileFromHeight = availableHeight / rows

        // Use the smaller dimension to ensure tiles fit
        let tileSize = Math.min(maxTileFromWidth, maxTileFromHeight)

        // Clamp to constraints
        tileSize = Math.max(minTileSize!, Math.min(maxTileSize!, tileSize))

        // Calculate actual gap (distribute remaining space)
        const usedWidth = tileSize * cols
        const usedHeight = tileSize * rows
        const horizontalGap = (containerWidth - usedWidth) / (cols + 1)
        const verticalGap = (containerHeight - usedHeight) / (rows + 1)
        const gap = Math.max(minGap!, Math.min(maxGap!, Math.min(horizontalGap, verticalGap)))

        // Score this layout
        // Prefer: larger tiles, square-ish aspect ratios, more items visible
        const fillRatio = (usedWidth / containerWidth) * (usedHeight / containerHeight)
        const aspectScore = opts.preferSquare ? 1 - Math.abs(1 - (cols / rows)) / 10 : 1
        const sizeScore = tileSize / maxTileSize!

        const score = (fillRatio * 0.4) + (aspectScore * 0.3) + (sizeScore * 0.3)

        if (score > bestScore) {
            bestScore = score
            bestLayout = {
                tileSize: Math.round(tileSize),
                gap: Math.round(gap),
                columns: cols,
                rows,
                containerPadding: Math.round(gap)
            }
        }
    }

    return bestLayout || {
        tileSize: 120,
        gap: 12,
        columns: Math.ceil(Math.sqrt(itemCount)),
        rows: Math.ceil(itemCount / Math.ceil(Math.sqrt(itemCount))),
        containerPadding: 16
    }
}

/**
 * Get responsive tile size based on viewport and item count
 */
export function getResponsiveTileSize(
    itemCount: number,
    viewportWidth: number
): number {
    // Mobile
    if (viewportWidth < 640) {
        if (itemCount <= 6) return 100
        if (itemCount <= 12) return 80
        return 60
    }

    // Tablet
    if (viewportWidth < 1024) {
        if (itemCount <= 10) return 120
        if (itemCount <= 25) return 100
        return 80
    }

    // Desktop
    if (itemCount <= 15) return 150
    if (itemCount <= 40) return 120
    if (itemCount <= 80) return 100
    return 80
}

/**
 * Calculate columns for CSS Grid based on container and tile size
 */
export function calculateGridColumns(
    containerWidth: number,
    tileSize: number,
    gap: number
): number {
    return Math.floor((containerWidth + gap) / (tileSize + gap))
}

/**
 * Breakpoints for responsive layouts
 */
export const LAYOUT_BREAKPOINTS = {
    xs: 480,
    sm: 640,
    md: 768,
    lg: 1024,
    xl: 1280,
    '2xl': 1536
} as const

/**
 * Hook-compatible layout calculator
 */
export function useLayoutConfig(
    itemCount: number,
    containerRef: React.RefObject<HTMLElement | null>,
    constraints?: LayoutConstraints
): LayoutConfig {
    // This would be used with useEffect and ResizeObserver in actual usage
    // For now, return a sensible default
    const defaultWidth = typeof window !== 'undefined' ? window.innerWidth : 1200
    const defaultHeight = typeof window !== 'undefined' ? window.innerHeight * 0.7 : 600

    return calculateOptimalLayout(itemCount, defaultWidth, defaultHeight, constraints)
}
